(function(g){g.__QURAN_DATA=g.__QURAN_DATA||{};g.__QURAN_DATA["tamil-041"]={"sura":41,"name_ar":"فصلت","name_en":"Fussilat","verses":54,"source":"https://www.tamililquran.com/tafsiribnkathir.php","count":54,"missing":[],"data":{"1":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=41&ayah=5\" class=\"link\">41:5</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 41:5 ஐ பார்க்கவும்"},"2":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=41&ayah=5\" class=\"link\">41:5</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 41:5 ஐ பார்க்கவும்"},"3":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=41&ayah=5\" class=\"link\">41:5</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 41:5 ஐ பார்க்கவும்"},"4":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=41&ayah=5\" class=\"link\">41:5</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 41:5 ஐ பார்க்கவும்"},"5":{"html":"<strong>அத்தியாயம் 41 ஃபுஸ்ஸிலத்</strong><br />\r\n<strong>இது மக்காவில் அருளப்பட்டது</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾بِسْمِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَنِ</span> <span class=\"quran-arabic-font text-success\">الرَّحِيمِ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n<br />\r\nஅளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால்.<br />\r\n<br />\r\n<strong>திருக்குர்ஆனின் சிறப்பும், அதைப் புறக்கணிப்பவர்கள் கூறுவதும்</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾حـم</span> - <span class=\"quran-arabic-font text-success\">تَنزِيلٌ</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَنِ</span> <span class=\"quran-arabic-font text-success\">الرَّحِيمِ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n<br />\r\n(ஹா மீம். இது அளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்விடமிருந்து அருளப்பட்ட வஹீ (இறைச்செய்தி) ஆகும்.) அதாவது, திருக்குர்ஆன் அளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்விடமிருந்து அருளப்பட்டது என்பதாகும். இது பின்வரும் வசனத்தைப் போன்றது:<span class=\"quran-arabic-font text-success\">﴾قُلْ</span> <span class=\"quran-arabic-font text-success\">نَزَّلَهُ</span> <span class=\"quran-arabic-font text-success\">رُوحُ</span> <span class=\"quran-arabic-font text-success\">الْقُدُسِ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">رَّبِّكَ</span> <span class=\"quran-arabic-font text-success\">بِالْحَقِّ﴿</span><br />\r\n<br />\r\n<br />\r\n(ரூஹுல் குதுஸ் (ஜிப்ரீல் (அலை)) இதனை உமது இறைவனிடமிருந்து சத்தியத்தைக் கொண்டு இறக்கினார் என்று (நபியே!) நீர் கூறுவீராக.) (<a href=\"qurandisp.php?sura=16&ayah=102\" class=\"link\">16:102</a>).<span class=\"quran-arabic-font text-success\">﴾وَإِنَّهُ</span> <span class=\"quran-arabic-font text-success\">لَتَنزِيلُ</span> <span class=\"quran-arabic-font text-success\">رَبِّ</span> <span class=\"quran-arabic-font text-success\">الْعَالَمِينَ</span> - <span class=\"quran-arabic-font text-success\">نَزَلَ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">الرُّوحُ</span> <span class=\"quran-arabic-font text-success\">الْأَمِينُ</span> - <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">قَلْبِكَ</span> <span class=\"quran-arabic-font text-success\">لِتَكُونَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْمُنْذِرِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n<br />\r\n(நிச்சயமாக இது அகிலங்களின் இறைவனால் அருளப்பட்ட வஹீ (இறைச்செய்தி) ஆகும். இதனை நம்பிக்கைக்குரிய ரூஹ் (ஜிப்ரீல் (அலை)) உமது இதயத்தில் இறக்கி வைத்தார்; நீர் எச்சரிக்கை செய்பவர்களில் ஒருவராக இருப்பதற்காக.) (<a href=\"qurandisp.php?sura=26&ayah=192\" class=\"link\">26:192</a>-194).<span class=\"quran-arabic-font text-success\">﴾كِتَابٌ</span> <span class=\"quran-arabic-font text-success\">فُصِّلَتْ</span> <span class=\"quran-arabic-font text-success\">آيَاتُهُ﴿</span><br />\r\n<br />\r\n<br />\r\n(இது ஒரு வேதம்; இதன் வசனங்கள் தெளிவாக விளக்கப்பட்டுள்ளன.) இதன் பொருள், இதன் கருத்துக்கள் தெளிவானவை, இதன் சட்டங்கள் உறுதியானவை மற்றும் ஞானமிக்கவை என்பதாகும்.<span class=\"quran-arabic-font text-success\">﴾قُرْءَاناً</span> <span class=\"quran-arabic-font text-success\">عَرَبِيّاً﴿</span><br />\r\n<br />\r\n<br />\r\n(அரபி மொழியிலான குர்ஆன்.) இது தெளிவான அரபி மொழியில் அமைந்த குர்ஆன் என்பதால், இதன் கருத்துக்கள் துல்லியமாகவும் விரிவாகவும் உள்ளன. இதன் சொற்கள் குழப்பமின்றி மிகத் தெளிவாக இருக்கின்றன. இது பின்வரும் வசனத்தைப் போன்றது:<span class=\"quran-arabic-font text-success\">﴾كِتَابٌ</span> <span class=\"quran-arabic-font text-success\">أُحْكِمَتْ</span> <span class=\"quran-arabic-font text-success\">آيَاتُهُ</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">فُصِّلَتْ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">لَّدُنْ</span> <span class=\"quran-arabic-font text-success\">حَكِيمٍ</span> <span class=\"quran-arabic-font text-success\">خَبِيرٍ﴿</span><br />\r\n<br />\r\n<br />\r\n((இது) ஒரு வேதம்; இதன் வசனங்கள் (முதலில்) உறுதியாக்கப்பட்டு, பின்னர் ஞானமிக்கோனும், நுணுக்கமாக அறிபவனுமாகிய அல்லாஹ்விடமிருந்து விரிவாக விளக்கப்பட்டுள்ளன.) (<a href=\"qurandisp.php?sura=11&ayah=1\" class=\"link\">11:1</a>). அதாவது, இது தன் சொல்லமைப்பிலும் கருத்தமைப்பிலும் ஓர் அற்புதமாகும்.<span class=\"quran-arabic-font text-success\">﴾لاَّ</span> <span class=\"quran-arabic-font text-success\">يَأْتِيهِ</span> <span class=\"quran-arabic-font text-success\">الْبَاطِلُ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">بَيْنِ</span> <span class=\"quran-arabic-font text-success\">يَدَيْهِ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">خَلْفِهِ</span> <span class=\"quran-arabic-font text-success\">تَنزِيلٌ</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">حَكِيمٍ</span> <span class=\"quran-arabic-font text-success\">حَمِيدٍ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n<br />\r\n(இதன் முன்னாலோ அல்லது பின்னாலோ எந்த ஒரு பொய்யும் அண்ட முடியாது. இது ஞானமிக்கோனும், புகழுக்குரியவனுமாகிய அல்லாஹ்விடமிருந்து அருளப்பட்டதாகும்.) (<a href=\"qurandisp.php?sura=41&ayah=42\" class=\"link\">41:42</a>).<span class=\"quran-arabic-font text-success\">﴾لِقَوْمٍ</span> <span class=\"quran-arabic-font text-success\">يَعْلَمُونَ﴿</span><br />\r\n<br />\r\n<br />\r\n(அறிகின்ற மக்களுக்காக.) அதாவது, அறிவில் ஆழமான புலமை பெற்ற அறிஞர்கள் இந்தத் தெளிவான நடையை எளிதில் புரிந்து கொள்வார்கள்.<span class=\"quran-arabic-font text-success\">﴾بَشِيراً</span> <span class=\"quran-arabic-font text-success\">وَنَذِيراً﴿</span><br />\r\n<br />\r\n<br />\r\n(நற்செய்தி கூறுவதாகவும், எச்சரிப்பதாகவும் இது உள்ளது.) அதாவது, இது சில நேரங்களில் நம்பிக்கையாளர்களுக்கு நற்செய்தியையும், சில நேரங்களில் நிராகரிப்பாளர்களுக்கு எச்சரிக்கையையும் வழங்குகிறது.<span class=\"quran-arabic-font text-success\">﴾فَأَعْرَضَ</span> <span class=\"quran-arabic-font text-success\">أَكْثَرُهُمْ</span> <span class=\"quran-arabic-font text-success\">فَهُمْ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَسْمَعُونَ﴿</span><br />\r\n<br />\r\n<br />\r\n(ஆனால் அவர்களில் பெரும்பாலோர் புறக்கணித்துவிட்டனர்; எனவே அவர்கள் செவியேற்க மாட்டார்கள்.) அதாவது, குரைஷிகளில் பெரும்பாலோர், இந்த வேதம் இவ்வளவு தெளிவாக இருந்தபோதிலும், அதிலிருந்து எதையுமே புரிந்து கொள்ளவில்லை.<span class=\"quran-arabic-font text-success\">﴾وَقَالُواْ</span> <span class=\"quran-arabic-font text-success\">قُلُوبُنَا</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">أَكِنَّةٍ</span> <span class=\"quran-arabic-font text-success\">مِّمَّا</span> <span class=\"quran-arabic-font text-success\">تَدْعُونَا</span> <span class=\"quran-arabic-font text-success\">إِلَيْهِ﴿</span><br />\r\n<br />\r\n<br />\r\n(மேலும் அவர்கள்: \"நீர் எதன் பக்கம் எங்களை அழைக்கிறீரோ அதை விட்டும் எங்கள் இதயங்கள் உறைகளுக்குள் மூடப்பட்டுள்ளன...\" என்று கூறுகின்றனர்.) அதாவது, அவை திரையிடப்பட்டு மூடப்பட்டுள்ளன.<span class=\"quran-arabic-font text-success\">﴾وَفِى</span> <span class=\"quran-arabic-font text-success\">آذَانِنَا</span> <span class=\"quran-arabic-font text-success\">وَقْرٌ﴿</span><br />\r\n<br />\r\n<br />\r\n(\"மேலும் எங்கள் காதுகளில் செவிட்டுத்தன்மை உள்ளது\" (என்கின்றனர்).) அதாவது, \"நீர் எங்களுக்குக் கொண்டு வரும் செய்திக்கு நாங்கள் செவிடர்களாக இருக்கிறோம்\" என்பதாகும்.<span class=\"quran-arabic-font text-success\">﴾وَمِن</span> <span class=\"quran-arabic-font text-success\">بَيْنِنَا</span> <span class=\"quran-arabic-font text-success\">وَبَيْنِكَ</span> <span class=\"quran-arabic-font text-success\">حِجَابٌ﴿</span><br />\r\n<br />\r\n<br />\r\n(\"எங்களுக்கும் உமக்கும் இடையில் ஒரு திரை உள்ளது\" (என்கின்றனர்).) அதாவது, \"நீர் கூறுவது எதுவும் எங்களை வந்தடையாது.\"<span class=\"quran-arabic-font text-success\">﴾فَاعْمَلْ</span> <span class=\"quran-arabic-font text-success\">إِنَّنَا</span> <span class=\"quran-arabic-font text-success\">عَامِلُونَ﴿</span><br />\r\n<br />\r\n<br />\r\n(\"எனவே நீர் (உமது வழியில்) செயல்படுவீராக! நிச்சயமாக நாங்களும் (எங்கள் வழியில்) செயல்படுகிறோம்\" (என்கின்றனர்).) அதாவது, \"நீர் உமது வழியில் செல்லுங்கள், நாங்கள் எங்கள் வழியில் செல்கிறோம்; நாங்கள் உம்மைப் பின்பற்றப் போவதில்லை\" என்பதாகும்.<br />\r\n<br />","text":"அத்தியாயம் 41 ஃபுஸ்ஸிலத்\n\r\nஇது மக்காவில் அருளப்பட்டது\n\r\n\n\r\n﴾بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ ﴿\n\r\n\n\r\n\n\r\nஅளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால்.\n\r\n\n\r\nதிருக்குர்ஆனின் சிறப்பும், அதைப் புறக்கணிப்பவர்கள் கூறுவதும்\n\r\n\n\r\n﴾حـم - تَنزِيلٌ مِّنَ الرَّحْمَنِ الرَّحِيمِ ﴿\n\r\n\n\r\n\n\r\n(ஹா மீம். இது அளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்விடமிருந்து அருளப்பட்ட வஹீ (இறைச்செய்தி) ஆகும்.) அதாவது, திருக்குர்ஆன் அளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்விடமிருந்து அருளப்பட்டது என்பதாகும். இது பின்வரும் வசனத்தைப் போன்றது:﴾قُلْ نَزَّلَهُ رُوحُ الْقُدُسِ مِن رَّبِّكَ بِالْحَقِّ﴿\n\r\n\n\r\n\n\r\n(ரூஹுல் குதுஸ் (ஜிப்ரீல் (அலை)) இதனை உமது இறைவனிடமிருந்து சத்தியத்தைக் கொண்டு இறக்கினார் என்று (நபியே!) நீர் கூறுவீராக.) (16:102).﴾وَإِنَّهُ لَتَنزِيلُ رَبِّ الْعَالَمِينَ - نَزَلَ بِهِ الرُّوحُ الْأَمِينُ - عَلَى قَلْبِكَ لِتَكُونَ مِنَ الْمُنْذِرِينَ ﴿\n\r\n\n\r\n\n\r\n(நிச்சயமாக இது அகிலங்களின் இறைவனால் அருளப்பட்ட வஹீ (இறைச்செய்தி) ஆகும். இதனை நம்பிக்கைக்குரிய ரூஹ் (ஜிப்ரீல் (அலை)) உமது இதயத்தில் இறக்கி வைத்தார்; நீர் எச்சரிக்கை செய்பவர்களில் ஒருவராக இருப்பதற்காக.) (26:192-194).﴾كِتَابٌ فُصِّلَتْ آيَاتُهُ﴿\n\r\n\n\r\n\n\r\n(இது ஒரு வேதம்; இதன் வசனங்கள் தெளிவாக விளக்கப்பட்டுள்ளன.) இதன் பொருள், இதன் கருத்துக்கள் தெளிவானவை, இதன் சட்டங்கள் உறுதியானவை மற்றும் ஞானமிக்கவை என்பதாகும்.﴾قُرْءَاناً عَرَبِيّاً﴿\n\r\n\n\r\n\n\r\n(அரபி மொழியிலான குர்ஆன்.) இது தெளிவான அரபி மொழியில் அமைந்த குர்ஆன் என்பதால், இதன் கருத்துக்கள் துல்லியமாகவும் விரிவாகவும் உள்ளன. இதன் சொற்கள் குழப்பமின்றி மிகத் தெளிவாக இருக்கின்றன. இது பின்வரும் வசனத்தைப் போன்றது:﴾كِتَابٌ أُحْكِمَتْ آيَاتُهُ ثُمَّ فُصِّلَتْ مِن لَّدُنْ حَكِيمٍ خَبِيرٍ﴿\n\r\n\n\r\n\n\r\n((இது) ஒரு வேதம்; இதன் வசனங்கள் (முதலில்) உறுதியாக்கப்பட்டு, பின்னர் ஞானமிக்கோனும், நுணுக்கமாக அறிபவனுமாகிய அல்லாஹ்விடமிருந்து விரிவாக விளக்கப்பட்டுள்ளன.) (11:1). அதாவது, இது தன் சொல்லமைப்பிலும் கருத்தமைப்பிலும் ஓர் அற்புதமாகும்.﴾لاَّ يَأْتِيهِ الْبَاطِلُ مِن بَيْنِ يَدَيْهِ وَلاَ مِنْ خَلْفِهِ تَنزِيلٌ مِّنْ حَكِيمٍ حَمِيدٍ ﴿\n\r\n\n\r\n\n\r\n(இதன் முன்னாலோ அல்லது பின்னாலோ எந்த ஒரு பொய்யும் அண்ட முடியாது. இது ஞானமிக்கோனும், புகழுக்குரியவனுமாகிய அல்லாஹ்விடமிருந்து அருளப்பட்டதாகும்.) (41:42).﴾لِقَوْمٍ يَعْلَمُونَ﴿\n\r\n\n\r\n\n\r\n(அறிகின்ற மக்களுக்காக.) அதாவது, அறிவில் ஆழமான புலமை பெற்ற அறிஞர்கள் இந்தத் தெளிவான நடையை எளிதில் புரிந்து கொள்வார்கள்.﴾بَشِيراً وَنَذِيراً﴿\n\r\n\n\r\n\n\r\n(நற்செய்தி கூறுவதாகவும், எச்சரிப்பதாகவும் இது உள்ளது.) அதாவது, இது சில நேரங்களில் நம்பிக்கையாளர்களுக்கு நற்செய்தியையும், சில நேரங்களில் நிராகரிப்பாளர்களுக்கு எச்சரிக்கையையும் வழங்குகிறது.﴾فَأَعْرَضَ أَكْثَرُهُمْ فَهُمْ لاَ يَسْمَعُونَ﴿\n\r\n\n\r\n\n\r\n(ஆனால் அவர்களில் பெரும்பாலோர் புறக்கணித்துவிட்டனர்; எனவே அவர்கள் செவியேற்க மாட்டார்கள்.) அதாவது, குரைஷிகளில் பெரும்பாலோர், இந்த வேதம் இவ்வளவு தெளிவாக இருந்தபோதிலும், அதிலிருந்து எதையுமே புரிந்து கொள்ளவில்லை.﴾وَقَالُواْ قُلُوبُنَا فِى أَكِنَّةٍ مِّمَّا تَدْعُونَا إِلَيْهِ﴿\n\r\n\n\r\n\n\r\n(மேலும் அவர்கள்: \"நீர் எதன் பக்கம் எங்களை அழைக்கிறீரோ அதை விட்டும் எங்கள் இதயங்கள் உறைகளுக்குள் மூடப்பட்டுள்ளன...\" என்று கூறுகின்றனர்.) அதாவது, அவை திரையிடப்பட்டு மூடப்பட்டுள்ளன.﴾وَفِى آذَانِنَا وَقْرٌ﴿\n\r\n\n\r\n\n\r\n(\"மேலும் எங்கள் காதுகளில் செவிட்டுத்தன்மை உள்ளது\" (என்கின்றனர்).) அதாவது, \"நீர் எங்களுக்குக் கொண்டு வரும் செய்திக்கு நாங்கள் செவிடர்களாக இருக்கிறோம்\" என்பதாகும்.﴾وَمِن بَيْنِنَا وَبَيْنِكَ حِجَابٌ﴿\n\r\n\n\r\n\n\r\n(\"எங்களுக்கும் உமக்கும் இடையில் ஒரு திரை உள்ளது\" (என்கின்றனர்).) அதாவது, \"நீர் கூறுவது எதுவும் எங்களை வந்தடையாது.\"﴾فَاعْمَلْ إِنَّنَا عَامِلُونَ﴿\n\r\n\n\r\n\n\r\n(\"எனவே நீர் (உமது வழியில்) செயல்படுவீராக! நிச்சயமாக நாங்களும் (எங்கள் வழியில்) செயல்படுகிறோம்\" (என்கின்றனர்).) அதாவது, \"நீர் உமது வழியில் செல்லுங்கள், நாங்கள் எங்கள் வழியில் செல்கிறோம்; நாங்கள் உம்மைப் பின்பற்றப் போவதில்லை\" என்பதாகும்."},"6":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=41&ayah=8\" class=\"link\">41:8</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 41:8 ஐ பார்க்கவும்"},"7":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=41&ayah=8\" class=\"link\">41:8</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 41:8 ஐ பார்க்கவும்"},"8":{"html":"<strong>தவ்ஹீதின் பக்கம் அழைப்பு - அல்லாஹ் கூறுகிறான்,</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾قُلْ﴿</span><br />\r\n<br />\r\n(கூறுவீராக) \"முஹம்மதே (ஸல்)! இந்த நிராகரிப்பாளர்களிடமும் இணைவைப்பாளர்களிடமும் கூறுவீராக:\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾إِنَّمَا</span> <span class=\"quran-arabic-font text-success\">أَنَا</span> <span class=\"quran-arabic-font text-success\">بَشَرٌ</span> <span class=\"quran-arabic-font text-success\">مِّثْلُكُمْ</span> <span class=\"quran-arabic-font text-success\">يُوحَى</span> <span class=\"quran-arabic-font text-success\">إِلَيَّ</span> <span class=\"quran-arabic-font text-success\">أَنَّمَا</span> <span class=\"quran-arabic-font text-success\">إِلَهُكُمْ</span> <span class=\"quran-arabic-font text-success\">إِلَهٌ</span> <span class=\"quran-arabic-font text-success\">وَاحِدٌ﴿</span><br />\r\n<br />\r\n(நான் உங்களைப் போன்ற ஒரு மனிதனே அன்றி வேறில்லை. நிச்சயமாக உங்கள் இறைவன் ஒரே இறைவனே என்று எனக்கு வஹீ (இறைச்செய்தி) அறிவிக்கப்படுகிறது.) \"நீங்கள் வணங்கும் இந்தச் சிலைகளையும் பொய்த் தெய்வங்களையும் போன்றவன் அல்லன் அவன். அல்லாஹ் ஒருவனே இறைவன்.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَاسْتَقِيمُواْ</span> <span class=\"quran-arabic-font text-success\">إِلَيْهِ﴿</span><br />\r\n<br />\r\n(எனவே, அவனிடமே நேரான வழியில் செல்லுங்கள்) என்பதன் பொருள், \"அவன் தனது தூதர்கள் மூலம் உங்களுக்குக் கட்டளையிட்டபடி, தூய்மையான மனதுடன் அவனை மட்டுமே வணங்குங்கள்\" என்பதாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَاسْتَغْفِرُوهُ﴿</span><br />\r\n<br />\r\n(மேலும் அவனிடம் மன்னிப்புக் கோருங்கள்) என்பது, \"உங்கள் கடந்த காலப் பாவங்களுக்காக (மன்னிப்புக் கோருங்கள்)\" என்று பொருள்படும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَوَيْلٌ</span> <span class=\"quran-arabic-font text-success\">لِّلْمُشْرِكِينَ﴿</span><br />\r\n<br />\r\n(இணைவைப்பாளர்களுக்கோ கேடுதான்!) அதாவது, அழிவும் நாசமுமே அவர்களுக்குரிய பங்காகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يُؤْتُونَ</span> <span class=\"quran-arabic-font text-success\">الزَّكَاةَ</span> <span class=\"quran-arabic-font text-success\">وَهُم</span> <span class=\"quran-arabic-font text-success\">بِالآخِرَةِ</span> <span class=\"quran-arabic-font text-success\">هُمْ</span> <span class=\"quran-arabic-font text-success\">كَافِرُونَ﴿</span><br />\r\n<br />\r\n(அவர்கள் ஜகாத் கொடுக்க மாட்டார்கள்; மேலும் அவர்கள் மறுமையை நிராகரிப்பவர்கள்.) \"அல்லாஹ்வைத் தவிர வணக்கத்திற்குரியவன் வேறு யாருமில்லை என்று சாட்சி கூறாதவர்களையே இது குறிக்கும்\" என்று இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து அலி பின் அபீ தல்ஹா (ரழி) அறிவிக்கிறார்கள். இக்ரிமா (ரழி) அவர்களும் இதே கருத்தைக் கொண்டிருந்தார்கள். இது பின்வரும் வசனங்களைப் போன்றதாகும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾قَدْ</span> <span class=\"quran-arabic-font text-success\">أَفْلَحَ</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">زَكَّاهَا</span> - <span class=\"quran-arabic-font text-success\">وَقَدْ</span> <span class=\"quran-arabic-font text-success\">خَابَ</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">دَسَّاهَا﴿</span><br />\r\n<br />\r\n(தன்னைத் தூய்மைப்படுத்திக் கொண்டவர் நிச்சயமாக வெற்றி பெற்றுவிட்டார். மேலும், தன்னை மாசுபடுத்திக் கொண்டவர் நிச்சயமாக நஷ்டமடைந்துவிட்டார்.) (<a href=\"qurandisp.php?sura=91&ayah=9\" class=\"link\">91:9</a>-10) மேலும்;<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾قَدْ</span> <span class=\"quran-arabic-font text-success\">أَفْلَحَ</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">تَزَكَّى</span> - <span class=\"quran-arabic-font text-success\">وَذَكَرَ</span> <span class=\"quran-arabic-font text-success\">اسْمَ</span> <span class=\"quran-arabic-font text-success\">رَبِّهِ</span> <span class=\"quran-arabic-font text-success\">فَصَلَّى</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(எவர் தன்னைத் தூய்மைப்படுத்திக் கொண்டாரோ அவர் நிச்சயமாக வெற்றி பெற்றுவிட்டார். மேலும், தனது இறைவனின் பெயரை நினைவு கூர்ந்து (துதித்து), தொழுதார்.) (<a href=\"qurandisp.php?sura=87&ayah=14\" class=\"link\">87:14</a>-15) மேலும்;<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَقُلْ</span> <span class=\"quran-arabic-font text-success\">هَل</span> <span class=\"quran-arabic-font text-success\">لَّكَ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">تَزَكَّى</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(மேலும் அவரிடம் கூறுவீராக: \"நீர் உன்னைத் தூய்மைப்படுத்திக் கொள்ள விரும்புகிறாயா?\") (<a href=\"qurandisp.php?sura=79&ayah=18\" class=\"link\">79:18</a>)<br />\r\n<br />\r\nஇங்கு 'ஜகாத்' என்பது ஆன்மாவைத் தூய்மைப்படுத்துவதையும், அனைத்து தீய குணங்களிலிருந்தும் தன்னை விடுவித்துக் கொள்வதையும் குறிக்கிறது. அத்தீய குணங்களில் மிக மோசமானது 'ஷிர்க்' (இணைவைத்தல்) ஆகும். ஒருவருடைய செல்வத்திற்காக வழங்கப்படும் ஜகாத் அவ்வாறு அழைக்கப்படுவதற்குக் காரணம், அது செல்வத்தைத் தூய்மைப்படுத்துகிறது. மேலும் அது செல்வத்தை அதிகரிக்கவும், அதில் பரக்கத் (அருள்வளம்) ஏற்படவும், அதைப் பயனுள்ளதாக்கவும் வழிசெய்கிறது. அதோடு நற்செயல்களில் செல்வத்தைச் செலவிட ஒருவருக்கு அது துணைபுரிகிறது. கதாதா (ரழி) அவர்கள் கூறும்போது, \"அவர்கள் தங்கள் செல்வத்திற்கான ஜகாத்தைத் தடுத்துக் கொண்டார்கள்\" என்றார்கள். பல தஃப்ஸீர் அறிஞர்களின் கூற்றுப்படி இதுவே வெளிப்படையான கருத்தாகும். இப்னு ஜரீர் அவர்களும் இக்கருத்தையே ஆதரிக்கிறார்கள்.<br />\r\n<br />\r\nஇருப்பினும், இந்த விஷயம் மேலும் ஆய்வுக்குரியதாகும். ஏனெனில் பல அறிஞர்கள் குறிப்பிட்டுள்ளபடி, ஜகாத் கடமையாக்கப்பட்டது மதீனாவிற்கு ஹிஜ்ரத் செய்த இரண்டாம் ஆண்டிலாகும். ஆனால் இந்த வசனமோ மக்காவில் அருளப்பட்டது. எனவே, தர்மம் மற்றும் ஜகாத் வழங்கும் கொள்கை நபிகள் நாயகம் (ஸல்) அவர்களின் தூதுத்துவத்தின் ஆரம்பத்திலேயே நடைமுறையில் இருந்திருக்கலாம். அல்லாஹ் கூறுவதைப் போல:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَءَاتُواْ</span> <span class=\"quran-arabic-font text-success\">حَقَّهُ</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">حَصَادِهِ﴿</span><br />\r\n<br />\r\n(அதன் அறுவடை நாளில் அதற்குரிய கடமையை வழங்கி விடுங்கள்.) (<a href=\"qurandisp.php?sura=6&ayah=141\" class=\"link\">6:141</a>). ஜகாத்தின் விரிவான சட்டங்களும் 'நிஸாப்' (குறைந்தபட்ச அளவு) முறைப்படியான கணக்கீடுகளும் மதீனாவிலேயே விளக்கப்பட்டன. இவ்வாறுதான் நாம் இவ்விரு கருத்துக்களுக்கும் இடையே இணக்கம் காண முடியும். இதேபோல், தொழுகையும் ஆரம்பத்தில் நபிகள் நாயகம் (ஸல்) அவர்களின் தூதுத்துவத்தின் தொடக்கத்தில் சூரிய உதயத்திற்கு முன்பும் சூரிய அஸ்தமனத்திற்கு முன்பும் கடமையாக்கப்பட்டது. ஹிஜ்ரத்திற்கு ஒன்றரை ஆண்டுகளுக்கு முன்பு 'இஸ்ரா' இரவில்தான் அல்லாஹ் தனது தூதருக்கு (ஸல்) ஐந்து நேரத் தொழுகைகளைக் கடமையாக்கினான். தொழுகையின் நிபந்தனைகளும் அடிப்படை அம்சங்களும் பின்னர் படிப்படியாக விளக்கப்பட்டன. அல்லாஹ்வே மிக அறிந்தவன்.<br />\r\n<br />\r\nபின்னர் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾إِنَّ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">آمَنُوا</span> <span class=\"quran-arabic-font text-success\">وَعَمِلُوا</span> <span class=\"quran-arabic-font text-success\">الصَّالِحَاتِ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">أَجْرٌ</span> <span class=\"quran-arabic-font text-success\">غَيْرُ</span> <span class=\"quran-arabic-font text-success\">مَمْنُونٍ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக, எவர்கள் ஈமான் (நம்பிக்கை) கொண்டு நற்செயல்கள் செய்கிறார்களோ, அவர்களுக்கு ஒருபோதும் முடிவடையாத மகத்தான கூலி உண்டு.) முஜாஹித் மற்றும் பிற அறிஞர்கள் கூறும்போது, \"அது ஒருபோதும் துண்டிக்கப்படாது அல்லது குறையாது\" என்றார்கள். இது பின்வரும் வசனங்களைப் போன்றதாகும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾مَّاكِثِينَ</span> <span class=\"quran-arabic-font text-success\">فِيهِ</span> <span class=\"quran-arabic-font text-success\">أَبَدًا</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அவர்கள் அதில் என்றென்றும் தங்கியிருப்பார்கள்.) (<a href=\"qurandisp.php?sura=18&ayah=3\" class=\"link\">18:3</a>)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾عَطَآءً</span> <span class=\"quran-arabic-font text-success\">غَيْرَ</span> <span class=\"quran-arabic-font text-success\">مَجْذُوذٍ﴿</span><br />\r\n<br />\r\n(இது துண்டிக்கப்படாத ஒரு கொடையாகும்.) (<a href=\"qurandisp.php?sura=11&ayah=108\" class=\"link\">11:108</a>)<br />\r\n<br />","text":"தவ்ஹீதின் பக்கம் அழைப்பு - அல்லாஹ் கூறுகிறான்,\n\r\n\n\r\n﴾قُلْ﴿\n\r\n\n\r\n(கூறுவீராக) \"முஹம்மதே (ஸல்)! இந்த நிராகரிப்பாளர்களிடமும் இணைவைப்பாளர்களிடமும் கூறுவீராக:\"\n\r\n\n\r\n﴾إِنَّمَا أَنَا بَشَرٌ مِّثْلُكُمْ يُوحَى إِلَيَّ أَنَّمَا إِلَهُكُمْ إِلَهٌ وَاحِدٌ﴿\n\r\n\n\r\n(நான் உங்களைப் போன்ற ஒரு மனிதனே அன்றி வேறில்லை. நிச்சயமாக உங்கள் இறைவன் ஒரே இறைவனே என்று எனக்கு வஹீ (இறைச்செய்தி) அறிவிக்கப்படுகிறது.) \"நீங்கள் வணங்கும் இந்தச் சிலைகளையும் பொய்த் தெய்வங்களையும் போன்றவன் அல்லன் அவன். அல்லாஹ் ஒருவனே இறைவன்.\"\n\r\n\n\r\n﴾فَاسْتَقِيمُواْ إِلَيْهِ﴿\n\r\n\n\r\n(எனவே, அவனிடமே நேரான வழியில் செல்லுங்கள்) என்பதன் பொருள், \"அவன் தனது தூதர்கள் மூலம் உங்களுக்குக் கட்டளையிட்டபடி, தூய்மையான மனதுடன் அவனை மட்டுமே வணங்குங்கள்\" என்பதாகும்.\n\r\n\n\r\n﴾وَاسْتَغْفِرُوهُ﴿\n\r\n\n\r\n(மேலும் அவனிடம் மன்னிப்புக் கோருங்கள்) என்பது, \"உங்கள் கடந்த காலப் பாவங்களுக்காக (மன்னிப்புக் கோருங்கள்)\" என்று பொருள்படும்.\n\r\n\n\r\n﴾وَوَيْلٌ لِّلْمُشْرِكِينَ﴿\n\r\n\n\r\n(இணைவைப்பாளர்களுக்கோ கேடுதான்!) அதாவது, அழிவும் நாசமுமே அவர்களுக்குரிய பங்காகும்.\n\r\n\n\r\n﴾الَّذِينَ لاَ يُؤْتُونَ الزَّكَاةَ وَهُم بِالآخِرَةِ هُمْ كَافِرُونَ﴿\n\r\n\n\r\n(அவர்கள் ஜகாத் கொடுக்க மாட்டார்கள்; மேலும் அவர்கள் மறுமையை நிராகரிப்பவர்கள்.) \"அல்லாஹ்வைத் தவிர வணக்கத்திற்குரியவன் வேறு யாருமில்லை என்று சாட்சி கூறாதவர்களையே இது குறிக்கும்\" என்று இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து அலி பின் அபீ தல்ஹா (ரழி) அறிவிக்கிறார்கள். இக்ரிமா (ரழி) அவர்களும் இதே கருத்தைக் கொண்டிருந்தார்கள். இது பின்வரும் வசனங்களைப் போன்றதாகும்:\n\r\n\n\r\n﴾قَدْ أَفْلَحَ مَن زَكَّاهَا - وَقَدْ خَابَ مَن دَسَّاهَا﴿\n\r\n\n\r\n(தன்னைத் தூய்மைப்படுத்திக் கொண்டவர் நிச்சயமாக வெற்றி பெற்றுவிட்டார். மேலும், தன்னை மாசுபடுத்திக் கொண்டவர் நிச்சயமாக நஷ்டமடைந்துவிட்டார்.) (91:9-10) மேலும்;\n\r\n\n\r\n﴾قَدْ أَفْلَحَ مَن تَزَكَّى - وَذَكَرَ اسْمَ رَبِّهِ فَصَلَّى ﴿\n\r\n\n\r\n(எவர் தன்னைத் தூய்மைப்படுத்திக் கொண்டாரோ அவர் நிச்சயமாக வெற்றி பெற்றுவிட்டார். மேலும், தனது இறைவனின் பெயரை நினைவு கூர்ந்து (துதித்து), தொழுதார்.) (87:14-15) மேலும்;\n\r\n\n\r\n﴾فَقُلْ هَل لَّكَ إِلَى أَن تَزَكَّى ﴿\n\r\n\n\r\n(மேலும் அவரிடம் கூறுவீராக: \"நீர் உன்னைத் தூய்மைப்படுத்திக் கொள்ள விரும்புகிறாயா?\") (79:18)\n\r\n\n\r\nஇங்கு 'ஜகாத்' என்பது ஆன்மாவைத் தூய்மைப்படுத்துவதையும், அனைத்து தீய குணங்களிலிருந்தும் தன்னை விடுவித்துக் கொள்வதையும் குறிக்கிறது. அத்தீய குணங்களில் மிக மோசமானது 'ஷிர்க்' (இணைவைத்தல்) ஆகும். ஒருவருடைய செல்வத்திற்காக வழங்கப்படும் ஜகாத் அவ்வாறு அழைக்கப்படுவதற்குக் காரணம், அது செல்வத்தைத் தூய்மைப்படுத்துகிறது. மேலும் அது செல்வத்தை அதிகரிக்கவும், அதில் பரக்கத் (அருள்வளம்) ஏற்படவும், அதைப் பயனுள்ளதாக்கவும் வழிசெய்கிறது. அதோடு நற்செயல்களில் செல்வத்தைச் செலவிட ஒருவருக்கு அது துணைபுரிகிறது. கதாதா (ரழி) அவர்கள் கூறும்போது, \"அவர்கள் தங்கள் செல்வத்திற்கான ஜகாத்தைத் தடுத்துக் கொண்டார்கள்\" என்றார்கள். பல தஃப்ஸீர் அறிஞர்களின் கூற்றுப்படி இதுவே வெளிப்படையான கருத்தாகும். இப்னு ஜரீர் அவர்களும் இக்கருத்தையே ஆதரிக்கிறார்கள்.\n\r\n\n\r\nஇருப்பினும், இந்த விஷயம் மேலும் ஆய்வுக்குரியதாகும். ஏனெனில் பல அறிஞர்கள் குறிப்பிட்டுள்ளபடி, ஜகாத் கடமையாக்கப்பட்டது மதீனாவிற்கு ஹிஜ்ரத் செய்த இரண்டாம் ஆண்டிலாகும். ஆனால் இந்த வசனமோ மக்காவில் அருளப்பட்டது. எனவே, தர்மம் மற்றும் ஜகாத் வழங்கும் கொள்கை நபிகள் நாயகம் (ஸல்) அவர்களின் தூதுத்துவத்தின் ஆரம்பத்திலேயே நடைமுறையில் இருந்திருக்கலாம். அல்லாஹ் கூறுவதைப் போல:\n\r\n\n\r\n﴾وَءَاتُواْ حَقَّهُ يَوْمَ حَصَادِهِ﴿\n\r\n\n\r\n(அதன் அறுவடை நாளில் அதற்குரிய கடமையை வழங்கி விடுங்கள்.) (6:141). ஜகாத்தின் விரிவான சட்டங்களும் 'நிஸாப்' (குறைந்தபட்ச அளவு) முறைப்படியான கணக்கீடுகளும் மதீனாவிலேயே விளக்கப்பட்டன. இவ்வாறுதான் நாம் இவ்விரு கருத்துக்களுக்கும் இடையே இணக்கம் காண முடியும். இதேபோல், தொழுகையும் ஆரம்பத்தில் நபிகள் நாயகம் (ஸல்) அவர்களின் தூதுத்துவத்தின் தொடக்கத்தில் சூரிய உதயத்திற்கு முன்பும் சூரிய அஸ்தமனத்திற்கு முன்பும் கடமையாக்கப்பட்டது. ஹிஜ்ரத்திற்கு ஒன்றரை ஆண்டுகளுக்கு முன்பு 'இஸ்ரா' இரவில்தான் அல்லாஹ் தனது தூதருக்கு (ஸல்) ஐந்து நேரத் தொழுகைகளைக் கடமையாக்கினான். தொழுகையின் நிபந்தனைகளும் அடிப்படை அம்சங்களும் பின்னர் படிப்படியாக விளக்கப்பட்டன. அல்லாஹ்வே மிக அறிந்தவன்.\n\r\n\n\r\nபின்னர் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\n﴾إِنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ﴿\n\r\n\n\r\n(நிச்சயமாக, எவர்கள் ஈமான் (நம்பிக்கை) கொண்டு நற்செயல்கள் செய்கிறார்களோ, அவர்களுக்கு ஒருபோதும் முடிவடையாத மகத்தான கூலி உண்டு.) முஜாஹித் மற்றும் பிற அறிஞர்கள் கூறும்போது, \"அது ஒருபோதும் துண்டிக்கப்படாது அல்லது குறையாது\" என்றார்கள். இது பின்வரும் வசனங்களைப் போன்றதாகும்:\n\r\n\n\r\n﴾مَّاكِثِينَ فِيهِ أَبَدًا ﴿\n\r\n\n\r\n(அவர்கள் அதில் என்றென்றும் தங்கியிருப்பார்கள்.) (18:3)\n\r\n\n\r\n﴾عَطَآءً غَيْرَ مَجْذُوذٍ﴿\n\r\n\n\r\n(இது துண்டிக்கப்படாத ஒரு கொடையாகும்.) (11:108)"},"9":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=41&ayah=12\" class=\"link\">41:12</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 41:12 ஐ பார்க்கவும்"},"10":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=41&ayah=12\" class=\"link\">41:12</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 41:12 ஐ பார்க்கவும்"},"11":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=41&ayah=12\" class=\"link\">41:12</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 41:12 ஐ பார்க்கவும்"},"12":{"html":"<strong>இப்பிரபஞ்சத்தின் படைப்பு பற்றிய சில விவரங்கள் இங்கே</strong><br />\r\n<br />\r\nஅல்லாஹ்வே அனைத்தையும் படைத்தவனாகவும், அடக்கி ஆள்பவனாகவும், அனைத்தையும் கட்டுப்படுத்துபவனாகவும் இருந்தபோதிலும், அவனை விடுத்து மற்ற தெய்வங்களை வணங்கும் இணைவைப்பாளர்களை அவன் கண்டிக்கிறான். அவன் கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾قُلْ</span> <span class=\"quran-arabic-font text-success\">أَئِنَّكُمْ</span> <span class=\"quran-arabic-font text-success\">لَتَكْفُرُونَ</span> <span class=\"quran-arabic-font text-success\">بِالَّذِى</span> <span class=\"quran-arabic-font text-success\">خَلَقَ</span> <span class=\"quran-arabic-font text-success\">الأَرْضَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">يَوْمَيْنِ</span> <span class=\"quran-arabic-font text-success\">وَتَجْعَلُونَ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">أَندَاداً﴿</span><br />\r\n(கூறுவீராக: \"நிச்சயமாக நீங்கள் பூமியை இரண்டு நாட்களில் படைத்தவனை நிராகரித்து, அவனுக்கு இணைகளை ஏற்படுத்துகிறீர்களா?\") அதாவது, அவனுடன் நீங்கள் வணங்கும் பொய்த் தெய்வங்களை அவனுக்கு இணையாக்குகிறீர்களா?<br />\r\n<span class=\"quran-arabic-font text-success\">﴾ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">رَبُّ</span> <span class=\"quran-arabic-font text-success\">الْعَالَمِينَ﴿</span><br />\r\n(அவனே அகிலங்களின் இறைவன்.) அனைத்துப் பொருட்களையும் படைத்தவனே அகிலத்தின் அனைத்துப் படைப்பினங்களுக்கும் இறைவன் ஆவான். இங்கே இந்த வசனம்;<br />\r\n<span class=\"quran-arabic-font text-success\">﴾خَلَقَ</span> <span class=\"quran-arabic-font text-success\">السَّمَاوَاتِ</span> <span class=\"quran-arabic-font text-success\">وَالأَرْضَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">سِتَّةِ</span> <span class=\"quran-arabic-font text-success\">أَيَّامٍ﴿</span><br />\r\n(வானங்களையும் பூமியையும் ஆறு நாட்களில் படைத்தவன்) (<a href=\"qurandisp.php?sura=7&ayah=54\" class=\"link\">7:54</a>) என்பது இன்னும் விரிவாக விளக்கப்படுகிறது. பூமியின் படைப்பு மற்றும் வானத்தின் படைப்பு ஆகியவை குறித்து இங்கே தனித்தனியாக விவாதிக்கப்படுகின்றன. பூமிதான் அஸ்திவாரம் என்பதால் அல்லாஹ் முதலில் பூமியைப் படைத்ததாகக் கூறுகிறான்; அஸ்திவாரம் முதலில் அமைக்கப்பட்ட பின்னரே கூரை எழுப்பப்பட வேண்டும். அல்லாஹ் மற்றோரிடத்தில் கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾هُوَ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">خَلَقَ</span> <span class=\"quran-arabic-font text-success\">لَكُم</span> <span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الأَرْضِ</span> <span class=\"quran-arabic-font text-success\">جَمِيعاً</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">اسْتَوَى</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">السَّمَآءِ</span> <span class=\"quran-arabic-font text-success\">فَسَوَّاهُنَّ</span> <span class=\"quran-arabic-font text-success\">سَبْعَ</span> <span class=\"quran-arabic-font text-success\">سَمَاوَاتٍ﴿</span><br />\r\n(அவன்தான் உங்களுக்காக பூமியில் உள்ள அனைத்தையும் படைத்தான். பின்னர் அவன் வானத்தின் பக்கம் நாடி, அவற்றை ஏழு வானங்களாகச் செம்மையாக்கினான்.) (<a href=\"qurandisp.php?sura=2&ayah=29\" class=\"link\">2:29</a>).<br />\r\n<br />\r\nஇந்த வசனங்களைப் பொறுத்தவரை:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أَأَنتُمْ</span> <span class=\"quran-arabic-font text-success\">أَشَدُّ</span> <span class=\"quran-arabic-font text-success\">خَلْقاً</span> <span class=\"quran-arabic-font text-success\">أَمِ</span> <span class=\"quran-arabic-font text-success\">السَّمَآءُ</span> <span class=\"quran-arabic-font text-success\">بَنَاهَا</span> - <span class=\"quran-arabic-font text-success\">رَفَعَ</span> <span class=\"quran-arabic-font text-success\">سَمْكَهَا</span> <span class=\"quran-arabic-font text-success\">فَسَوَّاهَا</span> - <span class=\"quran-arabic-font text-success\">وَأَغْطَشَ</span> <span class=\"quran-arabic-font text-success\">لَيْلَهَا</span> <span class=\"quran-arabic-font text-success\">وَأَخْرَجَ</span> <span class=\"quran-arabic-font text-success\">ضُحَاهَا</span> - <span class=\"quran-arabic-font text-success\">وَالأَرْضَ</span> <span class=\"quran-arabic-font text-success\">بَعْدَ</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">دَحَاهَا</span> - <span class=\"quran-arabic-font text-success\">أَخْرَجَ</span> <span class=\"quran-arabic-font text-success\">مِنْهَا</span> <span class=\"quran-arabic-font text-success\">مَآءَهَا</span> <span class=\"quran-arabic-font text-success\">وَمَرْعَاهَا</span> - <span class=\"quran-arabic-font text-success\">وَالْجِبَالَ</span> <span class=\"quran-arabic-font text-success\">أَرْسَاهَا</span> - <span class=\"quran-arabic-font text-success\">مَتَاعاً</span> <span class=\"quran-arabic-font text-success\">لَّكُمْ</span> <span class=\"quran-arabic-font text-success\">وَلِأَنْعَامِكُمْ﴿</span><br />\r\n(உங்களைப் படைப்பது அதிகக் கடினமானதா அல்லது அவன் நிர்மாணித்த வானமா? அதன் முகட்டை அவன் உயர்த்தி, அதனைச் செம்மைப்படுத்தினான். அதன் இரவை அவன் இருளாக்கினான்; அதன் பகலை வெளிப்படுத்தினான். அதன் பின்னர் அவன் பூமியை விரித்தான். அதிலிருந்து அதன் நீரையும் அதன் மேய்ச்சல் நிலங்களையும் வெளிப்படுத்தினான். இன்னும் மலைகளை அவன் உறுதியாக நாட்டினான். (இவை) உங்களுக்கும் உங்கள் கால்நடைகளுக்கும் பயன் தருவதற்காக.) (<a href=\"qurandisp.php?sura=79&ayah=27\" class=\"link\">79:27</a>-33). வானங்களைப் படைத்த பின்னரே பூமி விரிவுபடுத்தப்பட்டது என்று இந்த வசனம் கூறுகிறது. ஆனால் சில சான்றுகளின்படி, வானங்களுக்கு முன்பே பூமி படைக்கப்பட்டது. இது குறித்து ஸஹீஹ் புகாரியில் இடம்பெற்றுள்ள தஃப்ஸீர் பகுதியில் இப்னு அப்பாஸ் (ரழி) அவர்கள் அளித்த விளக்கம் வருமாறு:<br />\r\n<br />\r\nஸயீத் பின் ஜுபைர் (ரழி) அவர்கள் கூறியதாவது: \"ஒரு மனிதர் இப்னு அப்பாஸ் (ரழி) அவர்களிடம் வந்து, 'குர்ஆனில் உள்ள சில விஷயங்கள் எனக்குக் குழப்பமாக உள்ளன' என்று கூறி பின்வருவனவற்றைக் குறிப்பிட்டார்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَلاَ</span> <span class=\"quran-arabic-font text-success\">أَنسَابَ</span> <span class=\"quran-arabic-font text-success\">بَيْنَهُمْ</span> <span class=\"quran-arabic-font text-success\">يَوْمَئِذٍ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">يَتَسَآءَلُونَ﴿</span><br />\r\n(அந்நாளில் அவர்களுக்கிடையே எந்த உறவும் இருக்காது; ஒருவரையொருவர் விசாரித்துக் கொள்ளவும் மாட்டார்கள்) (<a href=\"qurandisp.php?sura=23&ayah=101\" class=\"link\">23:101</a>),<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَأَقْبَلَ</span> <span class=\"quran-arabic-font text-success\">بَعْضُهُمْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">بَعْضٍ</span> <span class=\"quran-arabic-font text-success\">يَتَسَآءَلُونَ﴿</span><br />\r\n(அவர்கள் ஒருவரையொருவர் முன்னோக்கி விசாரித்துக் கொள்வார்கள்) (<a href=\"qurandisp.php?sura=37&ayah=27\" class=\"link\">37:27</a>),<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَلاَ</span> <span class=\"quran-arabic-font text-success\">يَكْتُمُونَ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">حَدِيثاً﴿</span><br />\r\n(அல்லாஹ்விடம் அவர்கள் எந்த ஒரு செய்தியையும் மறைக்க முடியாது) (<a href=\"qurandisp.php?sura=4&ayah=42\" class=\"link\">4:42</a>),<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَاللَّهِ</span> <span class=\"quran-arabic-font text-success\">رَبِّنَا</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">كُنَّا</span> <span class=\"quran-arabic-font text-success\">مُشْرِكِينَ﴿</span><br />\r\n(எங்கள் இறைவனாகிய அல்லாஹ்வின் மீது ஆணையாக, நாங்கள் இணைவைப்பாளர்களாக இருக்கவில்லை) (<a href=\"qurandisp.php?sura=6&ayah=23\" class=\"link\">6:23</a>). ஆனால் இந்த வசனத்தில் அவர்கள் உண்மையை மறைக்க முற்படுகிறார்கள். மேலும் அல்லாஹ் கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أَأَنتُمْ</span> <span class=\"quran-arabic-font text-success\">أَشَدُّ</span> <span class=\"quran-arabic-font text-success\">خَلْقاً</span> <span class=\"quran-arabic-font text-success\">أَمِ</span> <span class=\"quran-arabic-font text-success\">السَّمَآءُ</span> <span class=\"quran-arabic-font text-success\">بَنَاهَا﴿</span><br />\r\n(உங்களைப் படைப்பது கடினமானதா அல்லது அவன் நிர்மாணித்த வானமா) என்பது முதல்;<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَالأَرْضَ</span> <span class=\"quran-arabic-font text-success\">بَعْدَ</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">دَحَاهَا﴿</span><br />\r\n(அதன் பின்னர் அவன் பூமியை விரித்தான்.) (<a href=\"qurandisp.php?sura=79&ayah=27\" class=\"link\">79:27</a>-30) வரை. ஆக, அவன் பூமிக்கு முன் வானங்களைப் படைத்ததைக் குறிப்பிட்டான், பின்னர் அவன் கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾قُلْ</span> <span class=\"quran-arabic-font text-success\">أَئِنَّكُمْ</span> <span class=\"quran-arabic-font text-success\">لَتَكْفُرُونَ</span> <span class=\"quran-arabic-font text-success\">بِالَّذِى</span> <span class=\"quran-arabic-font text-success\">خَلَقَ</span> <span class=\"quran-arabic-font text-success\">الأَرْضَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">يَوْمَيْنِ﴿</span><br />\r\n(கூறுவீராக: \"பூமியை இரண்டு நாட்களில் படைத்தவனை நீங்கள் நிச்சயமாக நிராகரிக்கிறீர்களா?...\") என்பது முதல்;<br />\r\n<span class=\"quran-arabic-font text-success\">﴾طَائِعِينَ﴿</span><br />\r\n(நாங்கள் வழிப்பட்டவர்களாக வருகிறோம்.) இங்கே அவன் வானங்களைப் படைப்பதற்கு முன் பூமியைப் படைத்ததைக் குறிப்பிட்டான். மேலும் அவன் கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَكَانَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">غَفُوراً</span> <span class=\"quran-arabic-font text-success\">رَّحِيماً﴿</span><br />\r\n(நிச்சயமாக அல்லாஹ் (கான) மன்னிப்பவனாகவும், நிகரற்ற அன்புடையவனாகவும் இருக்கிறான்) (<a href=\"qurandisp.php?sura=4&ayah=23\" class=\"link\">4:23</a>).<br />\r\n<span class=\"quran-arabic-font text-success\">﴾عَزِيزاً</span> <span class=\"quran-arabic-font text-success\">حَكِيماً﴿</span><br />\r\n(மிகைத்தவனாகவும் ஞானமிக்கவனாகவும்) (<a href=\"qurandisp.php?sura=4&ayah=56\" class=\"link\">4:56</a>).<br />\r\n<span class=\"quran-arabic-font text-success\">﴾سَمِيعاً</span> <span class=\"quran-arabic-font text-success\">بَصِيراً﴿</span><br />\r\n(யாவற்றையும் செவியுறுபவனாகவும் பார்ப்பவனாகவும்) (<a href=\"qurandisp.php?sura=4&ayah=58\" class=\"link\">4:58</a>). இதில் 'கான' (இருந்தான்) என்ற சொல் பயின்று வருவதால், அவன் முன்பு அவ்வாறு இருந்தான், இப்போது இல்லை என்பது போல் தோன்றுகிறதே?\"<br />\r\n<br />\r\nஇப்னு அப்பாஸ் (ரழி) அவர்கள் பதிலளித்தார்கள்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَلاَ</span> <span class=\"quran-arabic-font text-success\">أَنسَابَ</span> <span class=\"quran-arabic-font text-success\">بَيْنَهُمْ</span> <span class=\"quran-arabic-font text-success\">يَوْمَئِذٍ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">يَتَسَآءَلُونَ﴿</span><br />\r\n(அந்நாளில் அவர்களுக்கிடையே எந்த உறவும் இருக்காது; ஒருவரையொருவர் விசாரித்துக் கொள்ளவும் மாட்டார்கள்) (<a href=\"qurandisp.php?sura=23&ayah=101\" class=\"link\">23:101</a>) என்பது முதல் முறை ஸூர் (எக்காளம்) ஊதப்படும்போது நிகழும்.<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَصَعِقَ</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">السَّمَاوَاتِ</span> <span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الأَرْضِ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">شَآءَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ﴿</span><br />\r\n(அல்லாஹ் நாடியவர்களைத் தவிர, வானங்களிலும் பூமியிலும் உள்ள அனைவரும் மூர்ச்சையாகி விழுவார்கள்) (<a href=\"qurandisp.php?sura=39&ayah=68\" class=\"link\">39:68</a>). அந்த நேரத்தில் அவர்களுக்குள் எந்த உறவும் இருக்காது, அவர்கள் ஒருவரையொருவர் விசாரித்துக் கொள்ளவும் மாட்டார்கள். பின்னர் மீண்டும் ஸூர் ஊதப்படும்போது,<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَأَقْبَلَ</span> <span class=\"quran-arabic-font text-success\">بَعْضُهُمْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">بَعْضٍ</span> <span class=\"quran-arabic-font text-success\">يَتَسَآءَلُونَ﴿</span><br />\r\n(அவர்கள் ஒருவரையொருவர் முன்னோக்கி விசாரித்துக் கொள்வார்கள்) (<a href=\"qurandisp.php?sura=37&ayah=27\" class=\"link\">37:27</a>).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَاللَّهِ</span> <span class=\"quran-arabic-font text-success\">رَبِّنَا</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">كُنَّا</span> <span class=\"quran-arabic-font text-success\">مُشْرِكِينَ﴿</span><br />\r\n(எங்கள் இறைவனாகிய அல்லாஹ்வின் மீது ஆணையாக, நாங்கள் இணைவைப்பாளர்களாக இருக்கவில்லை) (<a href=\"qurandisp.php?sura=6&ayah=23\" class=\"link\">6:23</a>) மற்றும்<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَلاَ</span> <span class=\"quran-arabic-font text-success\">يَكْتُمُونَ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">حَدِيثاً﴿</span><br />\r\n(அல்லாஹ்விடம் அவர்கள் எந்த ஒரு செய்தியையும் மறைக்க முடியாது) (<a href=\"qurandisp.php?sura=4&ayah=42\" class=\"link\">4:42</a>) ஆகிய வசனங்களைப் பொறுத்தவரை: அல்லாஹ் உண்மையான முஃமின்களின் (நம்பிக்கையாளர்கள்) பாவங்களை மன்னிப்பான். இதைப் பார்க்கும் இணைவைப்பாளர்கள், 'நாமும் அல்லாஹ்வுக்கு யாரையும் இணைவைக்கவில்லை என்று கூறுவோம்' என முடிவு செய்வர். அப்போது அவர்களின் வாய்கள் முத்திரையிடப்பட்டு, அவர்களின் கைகள் பேசும். அதன் மூலம் அல்லாஹ்விடம் எதையும் மறைக்க முடியாது என்பது தெளிவாகும். அந்த நேரத்தில்,<br />\r\n<span class=\"quran-arabic-font text-success\">﴾يَوَدُّ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُواْ﴿</span><br />\r\n(நிராகரித்தவர்கள் விரும்புவார்கள்) (<a href=\"qurandisp.php?sura=4&ayah=42\" class=\"link\">4:42</a>).<br />\r\n<br />\r\nஅல்லாஹ் பூமியை இரண்டு நாட்களில் படைத்தான். பிறகு வானத்தைப் படைக்க நாடினான். மேலும் இரண்டு நாட்களில் அதற்குரிய வடிவத்தைக் கொடுத்து (ஏழு வானங்களாக) அமைத்தான். அதன் பிறகு பூமியை விரித்தான்; அதாவது பூமியிலிருந்து நீரையும் மேய்ச்சல் நிலங்களையும் வெளிப்படுத்தினான். மேலும் மலைகள், மணல் பரப்புகள், உயிரற்ற பொருட்கள், பாறைகள், குன்றுகள் மற்றும் அவற்றுக்கு இடையே உள்ள அனைத்தையும் இன்னும் இரண்டு நாட்களில் படைத்தான். இதையே அல்லாஹ்,<br />\r\n<span class=\"quran-arabic-font text-success\">﴾دَحَاهَا﴿</span><br />\r\n((அவன்) பூமியை விரித்தான்) (<a href=\"qurandisp.php?sura=79&ayah=30\" class=\"link\">79:30</a>) என்று கூறுகிறான். மேலும் அல்லாஹ்வின் கூற்றான:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾خَلَقَ</span> <span class=\"quran-arabic-font text-success\">الأَرْضَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">يَوْمَيْنِ﴿</span><br />\r\n(பூமியை இரண்டு நாட்களில் படைத்தான்) என்பதன்படி, பூமியையும் அதில் உள்ளவற்றையும் நான்கு நாட்களில் படைத்தான். வானங்களை இரண்டு நாட்களில் படைத்தான்.<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَكَانَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">غَفُوراً</span> <span class=\"quran-arabic-font text-success\">رَّحِيماً﴿</span><br />\r\n(நிச்சயமாக அல்லாஹ் (கான) மன்னிப்பவனாகவும், நிகரற்ற அன்புடையவனாகவும் இருக்கிறான்) (<a href=\"qurandisp.php?sura=4&ayah=23\" class=\"link\">4:23</a>). இது அவன் தன்னை விவரிக்கும் முறையாகும்; அவன் இப்போதும் அப்படித்தான் இருக்கிறான். அல்லாஹ் எதை நாடுகிறானோ அதுவே நடக்கும். எனவே குர்ஆனைப் பற்றிக் குழப்பமடையாதீர்கள், ஏனெனில் அது அனைத்தும் அல்லாஹ்விடமிருந்து வந்ததாகும்.\" இது புகாரியில் பதிவு செய்யப்பட்டுள்ளது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾خَلَقَ</span> <span class=\"quran-arabic-font text-success\">الأَرْضَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">يَوْمَيْنِ﴿</span><br />\r\n(பூமியை இரண்டு நாட்களில் படைத்தான்) என்பது ஞாயிறு மற்றும் திங்கட்கிழமைகளைக் குறிக்கும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَجَعَلَ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">رَوَاسِىَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">فَوْقِهَا</span> <span class=\"quran-arabic-font text-success\">وَبَارَكَ</span> <span class=\"quran-arabic-font text-success\">فِيهَا﴿</span><br />\r\n(அவன் அதன் மேலிருந்து உறுதியான மலைகளை அமைத்தான், மேலும் அதில் அபிவிருத்தி செய்தான்) என்பது, அல்லாஹ் அதில் பரகத் (அபிவிருத்தி) செய்து, விதைகள் விதைக்கப்பட்டுப் பயிர்கள் விளையக்கூடிய ஆற்றலை வழங்கினான் என்பதைக் குறிக்கும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَقَدَّرَ</span> <span class=\"quran-arabic-font text-success\">فِيهَآ</span> <span class=\"quran-arabic-font text-success\">أَقْوَاتَهَا﴿</span><br />\r\n(மேலும் அதில் அதன் உணவுகளை நிர்ணயித்தான்) என்பது, அங்குள்ள மக்களுக்குத் தேவையான வாழ்வாதாரங்களையும், பயிரிடுவதற்கான இடங்களையும் நிர்ணயித்ததைக் குறிக்கும். இது செவ்வாய் மற்றும் புதன்கிழமைகளில் நிகழ்ந்தது. முந்தைய இரண்டு நாட்களுடன் சேர்த்து இவை மொத்தம் நான்கு நாட்களாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فِى</span> <span class=\"quran-arabic-font text-success\">أَرْبَعَةِ</span> <span class=\"quran-arabic-font text-success\">أَيَّامٍ</span> <span class=\"quran-arabic-font text-success\">سَوَآءً</span> <span class=\"quran-arabic-font text-success\">لِّلسَّآئِلِينَ﴿</span><br />\r\n(கேட்பவர்கள் அனைவருக்கும் சமமாக நான்கு நாட்களில்.) அதாவது, இதைப் பற்றி அறிந்து கொள்ள விரும்பும் எவரும் கேட்டுத் தெரிந்து கொள்வதற்காக (இவ்வாறு நான்கு நாட்களில் முடிக்கப்பட்டது). இக்ரிமா மற்றும் முஜாஹித் ஆகியோர் இந்த வசனத்தைப் பற்றி கூறுகையில்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَقَدَّرَ</span> <span class=\"quran-arabic-font text-success\">فِيهَآ</span> <span class=\"quran-arabic-font text-success\">أَقْوَاتَهَا﴿</span><br />\r\n(மேலும் அதில் அதன் உணவுகளை நிர்ணயித்தான்): \"ஒவ்வொரு நிலத்திலும் அந்த நிலத்திற்கு மட்டுமே உரிய பிரத்யேகமானவற்றை அவன் அமைத்தான்\" என்றனர். இப்னு அப்பாஸ் (ரழி), கத்தாதா மற்றும் அஸ்-ஸுத்தி ஆகியோர் இந்த வசனத்தைப் பற்றி கூறுகையில்,<br />\r\n<span class=\"quran-arabic-font text-success\">﴾سَوَآءً</span> <span class=\"quran-arabic-font text-success\">لِّلسَّآئِلِينَ﴿</span><br />\r\n(கேட்பவர்கள் அனைவருக்கும் சமமாக): இதற்கு, \"யார் இதைப் பற்றிக் கேட்க விரும்புகிறார்களோ அவர்களுக்காக\" என்று பொருள் கூறினர். இப்னு ஜைத் அவர்கள் கூறினார்கள்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَقَدَّرَ</span> <span class=\"quran-arabic-font text-success\">فِيهَآ</span> <span class=\"quran-arabic-font text-success\">أَقْوَاتَهَا</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">أَرْبَعَةِ</span> <span class=\"quran-arabic-font text-success\">أَيَّامٍ</span> <span class=\"quran-arabic-font text-success\">سَوَآءً</span> <span class=\"quran-arabic-font text-success\">لِّلسَّآئِلِينَ﴿</span><br />\r\n(மேலும் அதில் அதன் உணவுகளை நான்கு நாட்களில், கேட்பவர்கள் அனைவருக்கும் சமமாக நிர்ணயித்தான்.) \"வாழ்வாதாரம் தேவைப்படும் ஒருவரின் தேவைக்கேற்ப அல்லாஹ் அவருக்குத் தேவையானதை நிர்ணயிக்கிறான்.\" இது, அவர்கள் பின்வரும் வசனத்தைப் பற்றி கூறியதைப் போன்றதாகும்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَآتَاكُم</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">كُلِّ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">سَأَلْتُمُوهُ﴿</span><br />\r\n(மேலும் நீங்கள் கேட்ட அனைத்திலிருந்தும் அவன் உங்களுக்குக் கொடுத்தான்) (<a href=\"qurandisp.php?sura=14&ayah=34\" class=\"link\">14:34</a>). மேலும் அல்லாஹ்வே மிக அறிந்தவன்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾ثُمَّ</span> <span class=\"quran-arabic-font text-success\">اسْتَوَى</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">السَّمَآءِ</span> <span class=\"quran-arabic-font text-success\">وَهِىَ</span> <span class=\"quran-arabic-font text-success\">دُخَانٌ﴿</span><br />\r\n(பின்னர் அவன் வானம் புகையாக இருந்தபோது அதன் பக்கம் நாடினான்,) அதாவது பூமி படைக்கப்பட்டபோது அதிலிருந்து எழுந்த ஆவி (புகை).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَقَالَ</span> <span class=\"quran-arabic-font text-success\">لَهَا</span> <span class=\"quran-arabic-font text-success\">وَلِلأَرْضِ</span> <span class=\"quran-arabic-font text-success\">ائْتِيَا</span> <span class=\"quran-arabic-font text-success\">طَوْعاً</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">كَرْهاً﴿</span><br />\r\n(பின்பு அதற்கும் பூமிக்கும்: \"நீங்கள் இருவரும் விரும்பியோ அல்லது விரும்பாமலோ வாருங்கள்\" என்று கூறினான்.) அதாவது, \"எனது கட்டளைக்குக் கீழ்ப்படிந்து, இந்தச் செயல்பாட்டிற்கு உட்படுங்கள், விரும்பியோ அல்லது விரும்பாமலோ.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾قَالَتَآ</span> <span class=\"quran-arabic-font text-success\">أَتَيْنَا</span> <span class=\"quran-arabic-font text-success\">طَائِعِينَ﴿</span><br />\r\n(அதற்கவை, \"நாங்கள் விரும்பி வழிப்பட்டவர்களாக வந்தோம்\" என்று கூறின.) அதாவது, \"நாங்கள் உனக்கு விருப்பத்துடன் கீழ்ப்படிகிறோம். எங்களில் நீ படைக்கப்போகும் வானவர்கள், ஜின்கள் மற்றும் மனிதர்கள் அனைவரும் உனக்குக் கீழ்ப்படிந்திருப்பார்கள்\" என்பதாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَقَضَاهُنَّ</span> <span class=\"quran-arabic-font text-success\">سَبْعَ</span> <span class=\"quran-arabic-font text-success\">سَمَاوَاتٍ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">يَوْمَيْنِ﴿</span><br />\r\n(பின்னர் அவன் இரண்டு நாட்களில் ஏழு வானங்களாக அவற்றின் படைப்பை நிறைவு செய்தான்) அதாவது, வியாழன் மற்றும் வெள்ளிக்கிழமைகளான மேலும் இரண்டு நாட்களில் அவற்றை ஏழு வானங்களாக உருவாக்கி முடித்தான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَأَوْحَى</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">كُلِّ</span> <span class=\"quran-arabic-font text-success\">سَمَآءٍ</span> <span class=\"quran-arabic-font text-success\">أَمْرَهَا﴿</span><br />\r\n(மேலும் ஒவ்வொரு வானத்திலும் அதற்குரிய காரியத்தை அவன் வஹீ (இறைச்செய்தி) மூலம் அறிவித்தான்.) என்பது, ஒவ்வொரு வானத்திற்கும் தேவையான வானவர்களையும் அவனுக்கு மட்டுமே தெரிந்த விடயங்களையும் அங்கு நிர்ணயித்தான் என்பதைக் குறிக்கும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَزَيَّنَّا</span> <span class=\"quran-arabic-font text-success\">السَّمَآءَ</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span> <span class=\"quran-arabic-font text-success\">بِمَصَابِيحَ﴿</span><br />\r\n(இன்னும் மிக நெருக்கமான (தாழ்வான) வானத்தை நாம் விளக்குகளால் அலங்கரித்தோம்) என்பது, பூமியில் உள்ள மக்களுக்குப் பிரகாசம் தரும் நட்சத்திரங்கள் மற்றும் கோள்களைக் குறிக்கும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَحِفْظاً﴿</span><br />\r\n(மேலும் பாதுகாப்பாகவும் (ஆக்கினோம்).) என்பது, ஷைத்தான்கள் மேல் உலக வானவர்களின் செய்திகளை ஒட்டுக் கேட்காதவாறு பாதுகாப்பாக அமைத்தான் என்பதைக் குறிக்கும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">تَقْدِيرُ</span> <span class=\"quran-arabic-font text-success\">الْعَزِيزِ</span> <span class=\"quran-arabic-font text-success\">الْعَلِيمِ﴿</span><br />\r\n(இவை யாவற்றையும் மிகைத்தவனும் எல்லாம் அறிந்தவனுமாகிய (இறைவனின்) நிர்ணயமாகும்) அதாவது, அனைத்தையும் தன் கட்டுப்பாட்டிற்குள் வைத்திருக்கும் மிகைத்தவனும், தன் படைப்பினங்களின் ஒவ்வொரு அசைவையும் நன்கு அறிந்தவனுமான அல்லாஹ்வின் ஏற்பாடாகும்.<br />\r\n<br />\r\n<br />\r\n<br />","text":"இப்பிரபஞ்சத்தின் படைப்பு பற்றிய சில விவரங்கள் இங்கே\n\r\n\n\r\nஅல்லாஹ்வே அனைத்தையும் படைத்தவனாகவும், அடக்கி ஆள்பவனாகவும், அனைத்தையும் கட்டுப்படுத்துபவனாகவும் இருந்தபோதிலும், அவனை விடுத்து மற்ற தெய்வங்களை வணங்கும் இணைவைப்பாளர்களை அவன் கண்டிக்கிறான். அவன் கூறுகிறான்:\n\r\n﴾قُلْ أَئِنَّكُمْ لَتَكْفُرُونَ بِالَّذِى خَلَقَ الأَرْضَ فِى يَوْمَيْنِ وَتَجْعَلُونَ لَهُ أَندَاداً﴿\n\r\n(கூறுவீராக: \"நிச்சயமாக நீங்கள் பூமியை இரண்டு நாட்களில் படைத்தவனை நிராகரித்து, அவனுக்கு இணைகளை ஏற்படுத்துகிறீர்களா?\") அதாவது, அவனுடன் நீங்கள் வணங்கும் பொய்த் தெய்வங்களை அவனுக்கு இணையாக்குகிறீர்களா?\n\r\n﴾ذَلِكَ رَبُّ الْعَالَمِينَ﴿\n\r\n(அவனே அகிலங்களின் இறைவன்.) அனைத்துப் பொருட்களையும் படைத்தவனே அகிலத்தின் அனைத்துப் படைப்பினங்களுக்கும் இறைவன் ஆவான். இங்கே இந்த வசனம்;\n\r\n﴾خَلَقَ السَّمَاوَاتِ وَالأَرْضَ فِى سِتَّةِ أَيَّامٍ﴿\n\r\n(வானங்களையும் பூமியையும் ஆறு நாட்களில் படைத்தவன்) (7:54) என்பது இன்னும் விரிவாக விளக்கப்படுகிறது. பூமியின் படைப்பு மற்றும் வானத்தின் படைப்பு ஆகியவை குறித்து இங்கே தனித்தனியாக விவாதிக்கப்படுகின்றன. பூமிதான் அஸ்திவாரம் என்பதால் அல்லாஹ் முதலில் பூமியைப் படைத்ததாகக் கூறுகிறான்; அஸ்திவாரம் முதலில் அமைக்கப்பட்ட பின்னரே கூரை எழுப்பப்பட வேண்டும். அல்லாஹ் மற்றோரிடத்தில் கூறுகிறான்:\n\r\n﴾هُوَ الَّذِى خَلَقَ لَكُم مَّا فِى الأَرْضِ جَمِيعاً ثُمَّ اسْتَوَى إِلَى السَّمَآءِ فَسَوَّاهُنَّ سَبْعَ سَمَاوَاتٍ﴿\n\r\n(அவன்தான் உங்களுக்காக பூமியில் உள்ள அனைத்தையும் படைத்தான். பின்னர் அவன் வானத்தின் பக்கம் நாடி, அவற்றை ஏழு வானங்களாகச் செம்மையாக்கினான்.) (2:29).\n\r\n\n\r\nஇந்த வசனங்களைப் பொறுத்தவரை:\n\r\n﴾أَأَنتُمْ أَشَدُّ خَلْقاً أَمِ السَّمَآءُ بَنَاهَا - رَفَعَ سَمْكَهَا فَسَوَّاهَا - وَأَغْطَشَ لَيْلَهَا وَأَخْرَجَ ضُحَاهَا - وَالأَرْضَ بَعْدَ ذَلِكَ دَحَاهَا - أَخْرَجَ مِنْهَا مَآءَهَا وَمَرْعَاهَا - وَالْجِبَالَ أَرْسَاهَا - مَتَاعاً لَّكُمْ وَلِأَنْعَامِكُمْ﴿\n\r\n(உங்களைப் படைப்பது அதிகக் கடினமானதா அல்லது அவன் நிர்மாணித்த வானமா? அதன் முகட்டை அவன் உயர்த்தி, அதனைச் செம்மைப்படுத்தினான். அதன் இரவை அவன் இருளாக்கினான்; அதன் பகலை வெளிப்படுத்தினான். அதன் பின்னர் அவன் பூமியை விரித்தான். அதிலிருந்து அதன் நீரையும் அதன் மேய்ச்சல் நிலங்களையும் வெளிப்படுத்தினான். இன்னும் மலைகளை அவன் உறுதியாக நாட்டினான். (இவை) உங்களுக்கும் உங்கள் கால்நடைகளுக்கும் பயன் தருவதற்காக.) (79:27-33). வானங்களைப் படைத்த பின்னரே பூமி விரிவுபடுத்தப்பட்டது என்று இந்த வசனம் கூறுகிறது. ஆனால் சில சான்றுகளின்படி, வானங்களுக்கு முன்பே பூமி படைக்கப்பட்டது. இது குறித்து ஸஹீஹ் புகாரியில் இடம்பெற்றுள்ள தஃப்ஸீர் பகுதியில் இப்னு அப்பாஸ் (ரழி) அவர்கள் அளித்த விளக்கம் வருமாறு:\n\r\n\n\r\nஸயீத் பின் ஜுபைர் (ரழி) அவர்கள் கூறியதாவது: \"ஒரு மனிதர் இப்னு அப்பாஸ் (ரழி) அவர்களிடம் வந்து, 'குர்ஆனில் உள்ள சில விஷயங்கள் எனக்குக் குழப்பமாக உள்ளன' என்று கூறி பின்வருவனவற்றைக் குறிப்பிட்டார்:\n\r\n﴾فَلاَ أَنسَابَ بَيْنَهُمْ يَوْمَئِذٍ وَلاَ يَتَسَآءَلُونَ﴿\n\r\n(அந்நாளில் அவர்களுக்கிடையே எந்த உறவும் இருக்காது; ஒருவரையொருவர் விசாரித்துக் கொள்ளவும் மாட்டார்கள்) (23:101),\n\r\n﴾وَأَقْبَلَ بَعْضُهُمْ عَلَى بَعْضٍ يَتَسَآءَلُونَ﴿\n\r\n(அவர்கள் ஒருவரையொருவர் முன்னோக்கி விசாரித்துக் கொள்வார்கள்) (37:27),\n\r\n﴾وَلاَ يَكْتُمُونَ اللَّهَ حَدِيثاً﴿\n\r\n(அல்லாஹ்விடம் அவர்கள் எந்த ஒரு செய்தியையும் மறைக்க முடியாது) (4:42),\n\r\n﴾وَاللَّهِ رَبِّنَا مَا كُنَّا مُشْرِكِينَ﴿\n\r\n(எங்கள் இறைவனாகிய அல்லாஹ்வின் மீது ஆணையாக, நாங்கள் இணைவைப்பாளர்களாக இருக்கவில்லை) (6:23). ஆனால் இந்த வசனத்தில் அவர்கள் உண்மையை மறைக்க முற்படுகிறார்கள். மேலும் அல்லாஹ் கூறுகிறான்:\n\r\n﴾أَأَنتُمْ أَشَدُّ خَلْقاً أَمِ السَّمَآءُ بَنَاهَا﴿\n\r\n(உங்களைப் படைப்பது கடினமானதா அல்லது அவன் நிர்மாணித்த வானமா) என்பது முதல்;\n\r\n﴾وَالأَرْضَ بَعْدَ ذَلِكَ دَحَاهَا﴿\n\r\n(அதன் பின்னர் அவன் பூமியை விரித்தான்.) (79:27-30) வரை. ஆக, அவன் பூமிக்கு முன் வானங்களைப் படைத்ததைக் குறிப்பிட்டான், பின்னர் அவன் கூறுகிறான்:\n\r\n﴾قُلْ أَئِنَّكُمْ لَتَكْفُرُونَ بِالَّذِى خَلَقَ الأَرْضَ فِى يَوْمَيْنِ﴿\n\r\n(கூறுவீராக: \"பூமியை இரண்டு நாட்களில் படைத்தவனை நீங்கள் நிச்சயமாக நிராகரிக்கிறீர்களா?...\") என்பது முதல்;\n\r\n﴾طَائِعِينَ﴿\n\r\n(நாங்கள் வழிப்பட்டவர்களாக வருகிறோம்.) இங்கே அவன் வானங்களைப் படைப்பதற்கு முன் பூமியைப் படைத்ததைக் குறிப்பிட்டான். மேலும் அவன் கூறுகிறான்:\n\r\n﴾وَكَانَ اللَّهُ غَفُوراً رَّحِيماً﴿\n\r\n(நிச்சயமாக அல்லாஹ் (கான) மன்னிப்பவனாகவும், நிகரற்ற அன்புடையவனாகவும் இருக்கிறான்) (4:23).\n\r\n﴾عَزِيزاً حَكِيماً﴿\n\r\n(மிகைத்தவனாகவும் ஞானமிக்கவனாகவும்) (4:56).\n\r\n﴾سَمِيعاً بَصِيراً﴿\n\r\n(யாவற்றையும் செவியுறுபவனாகவும் பார்ப்பவனாகவும்) (4:58). இதில் 'கான' (இருந்தான்) என்ற சொல் பயின்று வருவதால், அவன் முன்பு அவ்வாறு இருந்தான், இப்போது இல்லை என்பது போல் தோன்றுகிறதே?\"\n\r\n\n\r\nஇப்னு அப்பாஸ் (ரழி) அவர்கள் பதிலளித்தார்கள்:\n\r\n﴾فَلاَ أَنسَابَ بَيْنَهُمْ يَوْمَئِذٍ وَلاَ يَتَسَآءَلُونَ﴿\n\r\n(அந்நாளில் அவர்களுக்கிடையே எந்த உறவும் இருக்காது; ஒருவரையொருவர் விசாரித்துக் கொள்ளவும் மாட்டார்கள்) (23:101) என்பது முதல் முறை ஸூர் (எக்காளம்) ஊதப்படும்போது நிகழும்.\n\r\n﴾فَصَعِقَ مَن فِى السَّمَاوَاتِ وَمَن فِى الأَرْضِ إِلاَّ مَن شَآءَ اللَّهُ﴿\n\r\n(அல்லாஹ் நாடியவர்களைத் தவிர, வானங்களிலும் பூமியிலும் உள்ள அனைவரும் மூர்ச்சையாகி விழுவார்கள்) (39:68). அந்த நேரத்தில் அவர்களுக்குள் எந்த உறவும் இருக்காது, அவர்கள் ஒருவரையொருவர் விசாரித்துக் கொள்ளவும் மாட்டார்கள். பின்னர் மீண்டும் ஸூர் ஊதப்படும்போது,\n\r\n﴾وَأَقْبَلَ بَعْضُهُمْ عَلَى بَعْضٍ يَتَسَآءَلُونَ﴿\n\r\n(அவர்கள் ஒருவரையொருவர் முன்னோக்கி விசாரித்துக் கொள்வார்கள்) (37:27).\n\r\n\n\r\n﴾وَاللَّهِ رَبِّنَا مَا كُنَّا مُشْرِكِينَ﴿\n\r\n(எங்கள் இறைவனாகிய அல்லாஹ்வின் மீது ஆணையாக, நாங்கள் இணைவைப்பாளர்களாக இருக்கவில்லை) (6:23) மற்றும்\n\r\n﴾وَلاَ يَكْتُمُونَ اللَّهَ حَدِيثاً﴿\n\r\n(அல்லாஹ்விடம் அவர்கள் எந்த ஒரு செய்தியையும் மறைக்க முடியாது) (4:42) ஆகிய வசனங்களைப் பொறுத்தவரை: அல்லாஹ் உண்மையான முஃமின்களின் (நம்பிக்கையாளர்கள்) பாவங்களை மன்னிப்பான். இதைப் பார்க்கும் இணைவைப்பாளர்கள், 'நாமும் அல்லாஹ்வுக்கு யாரையும் இணைவைக்கவில்லை என்று கூறுவோம்' என முடிவு செய்வர். அப்போது அவர்களின் வாய்கள் முத்திரையிடப்பட்டு, அவர்களின் கைகள் பேசும். அதன் மூலம் அல்லாஹ்விடம் எதையும் மறைக்க முடியாது என்பது தெளிவாகும். அந்த நேரத்தில்,\n\r\n﴾يَوَدُّ الَّذِينَ كَفَرُواْ﴿\n\r\n(நிராகரித்தவர்கள் விரும்புவார்கள்) (4:42).\n\r\n\n\r\nஅல்லாஹ் பூமியை இரண்டு நாட்களில் படைத்தான். பிறகு வானத்தைப் படைக்க நாடினான். மேலும் இரண்டு நாட்களில் அதற்குரிய வடிவத்தைக் கொடுத்து (ஏழு வானங்களாக) அமைத்தான். அதன் பிறகு பூமியை விரித்தான்; அதாவது பூமியிலிருந்து நீரையும் மேய்ச்சல் நிலங்களையும் வெளிப்படுத்தினான். மேலும் மலைகள், மணல் பரப்புகள், உயிரற்ற பொருட்கள், பாறைகள், குன்றுகள் மற்றும் அவற்றுக்கு இடையே உள்ள அனைத்தையும் இன்னும் இரண்டு நாட்களில் படைத்தான். இதையே அல்லாஹ்,\n\r\n﴾دَحَاهَا﴿\n\r\n((அவன்) பூமியை விரித்தான்) (79:30) என்று கூறுகிறான். மேலும் அல்லாஹ்வின் கூற்றான:\n\r\n﴾خَلَقَ الأَرْضَ فِى يَوْمَيْنِ﴿\n\r\n(பூமியை இரண்டு நாட்களில் படைத்தான்) என்பதன்படி, பூமியையும் அதில் உள்ளவற்றையும் நான்கு நாட்களில் படைத்தான். வானங்களை இரண்டு நாட்களில் படைத்தான்.\n\r\n﴾وَكَانَ اللَّهُ غَفُوراً رَّحِيماً﴿\n\r\n(நிச்சயமாக அல்லாஹ் (கான) மன்னிப்பவனாகவும், நிகரற்ற அன்புடையவனாகவும் இருக்கிறான்) (4:23). இது அவன் தன்னை விவரிக்கும் முறையாகும்; அவன் இப்போதும் அப்படித்தான் இருக்கிறான். அல்லாஹ் எதை நாடுகிறானோ அதுவே நடக்கும். எனவே குர்ஆனைப் பற்றிக் குழப்பமடையாதீர்கள், ஏனெனில் அது அனைத்தும் அல்லாஹ்விடமிருந்து வந்ததாகும்.\" இது புகாரியில் பதிவு செய்யப்பட்டுள்ளது.\n\r\n\n\r\n﴾خَلَقَ الأَرْضَ فِى يَوْمَيْنِ﴿\n\r\n(பூமியை இரண்டு நாட்களில் படைத்தான்) என்பது ஞாயிறு மற்றும் திங்கட்கிழமைகளைக் குறிக்கும்.\n\r\n\n\r\n﴾وَجَعَلَ فِيهَا رَوَاسِىَ مِن فَوْقِهَا وَبَارَكَ فِيهَا﴿\n\r\n(அவன் அதன் மேலிருந்து உறுதியான மலைகளை அமைத்தான், மேலும் அதில் அபிவிருத்தி செய்தான்) என்பது, அல்லாஹ் அதில் பரகத் (அபிவிருத்தி) செய்து, விதைகள் விதைக்கப்பட்டுப் பயிர்கள் விளையக்கூடிய ஆற்றலை வழங்கினான் என்பதைக் குறிக்கும்.\n\r\n\n\r\n﴾وَقَدَّرَ فِيهَآ أَقْوَاتَهَا﴿\n\r\n(மேலும் அதில் அதன் உணவுகளை நிர்ணயித்தான்) என்பது, அங்குள்ள மக்களுக்குத் தேவையான வாழ்வாதாரங்களையும், பயிரிடுவதற்கான இடங்களையும் நிர்ணயித்ததைக் குறிக்கும். இது செவ்வாய் மற்றும் புதன்கிழமைகளில் நிகழ்ந்தது. முந்தைய இரண்டு நாட்களுடன் சேர்த்து இவை மொத்தம் நான்கு நாட்களாகும்.\n\r\n\n\r\n﴾فِى أَرْبَعَةِ أَيَّامٍ سَوَآءً لِّلسَّآئِلِينَ﴿\n\r\n(கேட்பவர்கள் அனைவருக்கும் சமமாக நான்கு நாட்களில்.) அதாவது, இதைப் பற்றி அறிந்து கொள்ள விரும்பும் எவரும் கேட்டுத் தெரிந்து கொள்வதற்காக (இவ்வாறு நான்கு நாட்களில் முடிக்கப்பட்டது). இக்ரிமா மற்றும் முஜாஹித் ஆகியோர் இந்த வசனத்தைப் பற்றி கூறுகையில்:\n\r\n﴾وَقَدَّرَ فِيهَآ أَقْوَاتَهَا﴿\n\r\n(மேலும் அதில் அதன் உணவுகளை நிர்ணயித்தான்): \"ஒவ்வொரு நிலத்திலும் அந்த நிலத்திற்கு மட்டுமே உரிய பிரத்யேகமானவற்றை அவன் அமைத்தான்\" என்றனர். இப்னு அப்பாஸ் (ரழி), கத்தாதா மற்றும் அஸ்-ஸுத்தி ஆகியோர் இந்த வசனத்தைப் பற்றி கூறுகையில்,\n\r\n﴾سَوَآءً لِّلسَّآئِلِينَ﴿\n\r\n(கேட்பவர்கள் அனைவருக்கும் சமமாக): இதற்கு, \"யார் இதைப் பற்றிக் கேட்க விரும்புகிறார்களோ அவர்களுக்காக\" என்று பொருள் கூறினர். இப்னு ஜைத் அவர்கள் கூறினார்கள்:\n\r\n﴾وَقَدَّرَ فِيهَآ أَقْوَاتَهَا فِى أَرْبَعَةِ أَيَّامٍ سَوَآءً لِّلسَّآئِلِينَ﴿\n\r\n(மேலும் அதில் அதன் உணவுகளை நான்கு நாட்களில், கேட்பவர்கள் அனைவருக்கும் சமமாக நிர்ணயித்தான்.) \"வாழ்வாதாரம் தேவைப்படும் ஒருவரின் தேவைக்கேற்ப அல்லாஹ் அவருக்குத் தேவையானதை நிர்ணயிக்கிறான்.\" இது, அவர்கள் பின்வரும் வசனத்தைப் பற்றி கூறியதைப் போன்றதாகும்:\n\r\n﴾وَآتَاكُم مِّن كُلِّ مَا سَأَلْتُمُوهُ﴿\n\r\n(மேலும் நீங்கள் கேட்ட அனைத்திலிருந்தும் அவன் உங்களுக்குக் கொடுத்தான்) (14:34). மேலும் அல்லாஹ்வே மிக அறிந்தவன்.\n\r\n\n\r\n﴾ثُمَّ اسْتَوَى إِلَى السَّمَآءِ وَهِىَ دُخَانٌ﴿\n\r\n(பின்னர் அவன் வானம் புகையாக இருந்தபோது அதன் பக்கம் நாடினான்,) அதாவது பூமி படைக்கப்பட்டபோது அதிலிருந்து எழுந்த ஆவி (புகை).\n\r\n\n\r\n﴾فَقَالَ لَهَا وَلِلأَرْضِ ائْتِيَا طَوْعاً أَوْ كَرْهاً﴿\n\r\n(பின்பு அதற்கும் பூமிக்கும்: \"நீங்கள் இருவரும் விரும்பியோ அல்லது விரும்பாமலோ வாருங்கள்\" என்று கூறினான்.) அதாவது, \"எனது கட்டளைக்குக் கீழ்ப்படிந்து, இந்தச் செயல்பாட்டிற்கு உட்படுங்கள், விரும்பியோ அல்லது விரும்பாமலோ.\"\n\r\n\n\r\n﴾قَالَتَآ أَتَيْنَا طَائِعِينَ﴿\n\r\n(அதற்கவை, \"நாங்கள் விரும்பி வழிப்பட்டவர்களாக வந்தோம்\" என்று கூறின.) அதாவது, \"நாங்கள் உனக்கு விருப்பத்துடன் கீழ்ப்படிகிறோம். எங்களில் நீ படைக்கப்போகும் வானவர்கள், ஜின்கள் மற்றும் மனிதர்கள் அனைவரும் உனக்குக் கீழ்ப்படிந்திருப்பார்கள்\" என்பதாகும்.\n\r\n\n\r\n﴾فَقَضَاهُنَّ سَبْعَ سَمَاوَاتٍ فِى يَوْمَيْنِ﴿\n\r\n(பின்னர் அவன் இரண்டு நாட்களில் ஏழு வானங்களாக அவற்றின் படைப்பை நிறைவு செய்தான்) அதாவது, வியாழன் மற்றும் வெள்ளிக்கிழமைகளான மேலும் இரண்டு நாட்களில் அவற்றை ஏழு வானங்களாக உருவாக்கி முடித்தான்.\n\r\n\n\r\n﴾وَأَوْحَى فِى كُلِّ سَمَآءٍ أَمْرَهَا﴿\n\r\n(மேலும் ஒவ்வொரு வானத்திலும் அதற்குரிய காரியத்தை அவன் வஹீ (இறைச்செய்தி) மூலம் அறிவித்தான்.) என்பது, ஒவ்வொரு வானத்திற்கும் தேவையான வானவர்களையும் அவனுக்கு மட்டுமே தெரிந்த விடயங்களையும் அங்கு நிர்ணயித்தான் என்பதைக் குறிக்கும்.\n\r\n\n\r\n﴾وَزَيَّنَّا السَّمَآءَ الدُّنْيَا بِمَصَابِيحَ﴿\n\r\n(இன்னும் மிக நெருக்கமான (தாழ்வான) வானத்தை நாம் விளக்குகளால் அலங்கரித்தோம்) என்பது, பூமியில் உள்ள மக்களுக்குப் பிரகாசம் தரும் நட்சத்திரங்கள் மற்றும் கோள்களைக் குறிக்கும்.\n\r\n\n\r\n﴾وَحِفْظاً﴿\n\r\n(மேலும் பாதுகாப்பாகவும் (ஆக்கினோம்).) என்பது, ஷைத்தான்கள் மேல் உலக வானவர்களின் செய்திகளை ஒட்டுக் கேட்காதவாறு பாதுகாப்பாக அமைத்தான் என்பதைக் குறிக்கும்.\n\r\n\n\r\n﴾ذَلِكَ تَقْدِيرُ الْعَزِيزِ الْعَلِيمِ﴿\n\r\n(இவை யாவற்றையும் மிகைத்தவனும் எல்லாம் அறிந்தவனுமாகிய (இறைவனின்) நிர்ணயமாகும்) அதாவது, அனைத்தையும் தன் கட்டுப்பாட்டிற்குள் வைத்திருக்கும் மிகைத்தவனும், தன் படைப்பினங்களின் ஒவ்வொரு அசைவையும் நன்கு அறிந்தவனுமான அல்லாஹ்வின் ஏற்பாடாகும்."},"13":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=41&ayah=18\" class=\"link\">41:18</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 41:18 ஐ பார்க்கவும்"},"14":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=41&ayah=18\" class=\"link\">41:18</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 41:18 ஐ பார்க்கவும்"},"15":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=41&ayah=18\" class=\"link\">41:18</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 41:18 ஐ பார்க்கவும்"},"16":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=41&ayah=18\" class=\"link\">41:18</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 41:18 ஐ பார்க்கவும்"},"17":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=41&ayah=18\" class=\"link\">41:18</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 41:18 ஐ பார்க்கவும்"},"18":{"html":"<strong>நிராகரிப்பாளர்களுக்கு ஓர் எச்சரிக்கையும் ஆது மற்றும் ஸமூது கூட்டத்தாரின் வரலாற்றினைப் பற்றிய நினைவூட்டலும்</strong><br />\r\n<br />\r\nஅல்லாஹ் கூறுகிறான்: \"முஹம்மது (ஸல்) அவர்களே! நீர் கொண்டு வந்த சத்தியச் செய்தியை நிராகரிக்கின்ற இந்த இணைவைப்பாளர்களிடம் கூறுவீராக: அல்லாஹ்விடமிருந்து நான் உங்களிடம் கொண்டு வந்ததை நீங்கள் புறக்கணித்தால், இறைத்தூதர்களை நிராகரித்ததற்காக முந்தைய சமுதாயத்தினர் அனுபவித்த வேதனையைப் போன்ற அல்லாஹ்வின் தண்டனையைக் குறித்து நான் உங்களை எச்சரிக்கிறேன்.\"<span class=\"quran-arabic-font text-success\">﴾فَإِنْ</span> <span class=\"quran-arabic-font text-success\">أَعْرَضُواْ</span> <span class=\"quran-arabic-font text-success\">فَقُلْ</span> <span class=\"quran-arabic-font text-success\">أَنذَرْتُكُمْ</span> <span class=\"quran-arabic-font text-success\">صَاعِقَةً</span> <span class=\"quran-arabic-font text-success\">مِّثْلَ</span> <span class=\"quran-arabic-font text-success\">صَاعِقَةِ</span> <span class=\"quran-arabic-font text-success\">عَادٍ</span> <span class=\"quran-arabic-font text-success\">وَثَمُودَ﴿</span><br />\r\n<br />\r\n(ஆது மற்றும் ஸமூது கூட்டத்தாரைத் தாக்கிய அந்தப் பேரொலி (இடி) போன்றதொரு பேரொலி.) இவர்களைப் போன்றே செயல்பட்ட மற்ற சமுதாயத்தினரையும் அது தாக்கியது.<span class=\"quran-arabic-font text-success\">﴾إِذْ</span> <span class=\"quran-arabic-font text-success\">جَآءَتْهُمُ</span> <span class=\"quran-arabic-font text-success\">الرُّسُلُ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">بَيْنِ</span> <span class=\"quran-arabic-font text-success\">أَيْدِيهِمْ</span> <span class=\"quran-arabic-font text-success\">وَمِنْ</span> <span class=\"quran-arabic-font text-success\">خَلْفِهِمْ﴿</span><br />\r\n<br />\r\n(இறைத்தூதர்கள் அவர்களுக்கு முன்னாலும் பின்னாலும் வந்தபோது). இது பின்வரும் வசனத்தைப் போன்றதாகும்:<span class=\"quran-arabic-font text-success\">﴾وَاذْكُرْ</span> <span class=\"quran-arabic-font text-success\">أَخَا</span> <span class=\"quran-arabic-font text-success\">عَادٍ</span> <span class=\"quran-arabic-font text-success\">إِذْ</span> <span class=\"quran-arabic-font text-success\">أَنذَرَ</span> <span class=\"quran-arabic-font text-success\">قَوْمَهُ</span> <span class=\"quran-arabic-font text-success\">بِالاٌّحْقَافِ</span> <span class=\"quran-arabic-font text-success\">وَقَدْ</span> <span class=\"quran-arabic-font text-success\">خَلَتِ</span> <span class=\"quran-arabic-font text-success\">النُّذُرُ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">بَيْنِ</span> <span class=\"quran-arabic-font text-success\">يَدَيْهِ</span> <span class=\"quran-arabic-font text-success\">وَمِنْ</span> <span class=\"quran-arabic-font text-success\">خَلْفِهِ﴿</span><br />\r\n<br />\r\n(ஆது கூட்டத்தாரின் சகோதரரான ஹூத் (அலை) அவர்களை நினைவுகூறுவீராக! அவர் 'அஹ்காஃப்' பகுதியில் இருந்த தம் சமூகத்தாரை எச்சரித்தபோது, அவருக்கு முன்னரும் பின்னரும் எச்சரிக்கையாளர்கள் பலர் கடந்து சென்றுள்ளனர்.) (<a href=\"qurandisp.php?sura=46&ayah=21\" class=\"link\">46:21</a>). அதாவது, அண்டை ஊர்களிலும் நகரங்களிலும் அல்லாஹ் தூதர்களை அனுப்பினான். <span class=\"quran-arabic-font text-success\">﴾أَلاَّ</span> <span class=\"quran-arabic-font text-success\">تَعْبُدُواْ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ﴿</span> அவர்கள் இணைதுணையற்ற அல்லாஹ் ஒருவனையே வணங்குமாறு மக்களுக்குக் கட்டளையிட்டனர். மேலும் அவர்கள் நற்செய்திகளையும் எச்சரிக்கைகளையும் கொண்டு வந்தனர். அல்லாஹ் தன் எதிரிகளுக்கு வழங்கிய தண்டனையையும், தன் நேசர்களுக்கு வழங்கிய அருட்கொடைகளையும் அவர்கள் கண்டனர். இருப்பினும், அவர்கள் அத்தூதர்களை நம்பிக்கை கொள்ளவில்லை. மாறாக, அவர்களைப் பொய்யாக்கிப் புறக்கணித்தனர். மேலும் அவர்கள் கூறினார்கள்:<span class=\"quran-arabic-font text-success\">﴾لَوْ</span> <span class=\"quran-arabic-font text-success\">شَآءَ</span> <span class=\"quran-arabic-font text-success\">رَبُّنَا</span> <span class=\"quran-arabic-font text-success\">لَأَنزَلَ</span> <span class=\"quran-arabic-font text-success\">مَلَـئِكَةً﴿</span><br />\r\n<br />\r\n(\"எங்கள் இறைவன் நாடியிருந்தால், நிச்சயமாக வானவர்களையே இறக்கியிருப்பான்.\") அதாவது, அல்லாஹ் தூதர்களை அனுப்புவதாக இருந்தால், அவர்கள் அவனிடமிருந்து அனுப்பப்பட்ட வானவர்களாகத்தான் இருந்திருப்பார்கள்.<span class=\"quran-arabic-font text-success\">﴾فَإِنَّا</span> <span class=\"quran-arabic-font text-success\">بِمَآ</span> <span class=\"quran-arabic-font text-success\">أُرْسِلْتُمْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">كَـفِرُونَ﴿</span><br />\r\n<br />\r\n(\"எனவே, நீங்கள் எதைக் கொண்டு அனுப்பப்பட்டீர்களோ அதை நிச்சயமாக நாங்கள் நிராகரிக்கிறோம்.\") இதன் பொருள்: \"நீங்கள் ஒரு சாதாரண மனிதர்தான்; எங்களைப் போன்ற மனிதர்களாக இருப்பதால் நாங்கள் உங்களைப் பின்பற்ற மாட்டோம்\" என்பதாகும்.<span class=\"quran-arabic-font text-success\">﴾فَأَمَّا</span> <span class=\"quran-arabic-font text-success\">عَادٌ</span> <span class=\"quran-arabic-font text-success\">فَاسْتَكْبَرُواْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الاٌّرْضِ</span> <span class=\"quran-arabic-font text-success\">بِغَيْرِ</span> <span class=\"quran-arabic-font text-success\">الْحَقِّ﴿</span><br />\r\n<br />\r\n(ஆது கூட்டத்தாரோ, பூமியில் அநியாயமாகப் பெருமையடித்தார்கள்.) அதாவது, அவர்கள் ஆணவம் கொண்டும், பிடிவாதமாகவும், கீழ்ப்படியாமலும் நடந்துகொண்டனர்.<span class=\"quran-arabic-font text-success\">﴾وَقَالُواْ</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">أَشَدُّ</span> <span class=\"quran-arabic-font text-success\">مِنَّا</span> <span class=\"quran-arabic-font text-success\">قُوَّةً﴿</span><br />\r\n<br />\r\n(மேலும் அவர்கள், \"வலிமையில் எங்களை விடச் சிறந்தவர் யார்?\" என்று கூறினார்கள்.) அவர்கள் தங்களின் உடல் வலிமையையும் ஆற்றலையும் குறித்துப் பெருமை பேசினார்கள். இது அல்லாஹ்வின் தண்டனையிலிருந்து தங்களைப் பாதுகாக்கும் என்று அவர்கள் எண்ணினார்கள்.<span class=\"quran-arabic-font text-success\">﴾أَوَلَمْ</span> <span class=\"quran-arabic-font text-success\">يَرَوْاْ</span> <span class=\"quran-arabic-font text-success\">أَنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">خَلَقَهُمْ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">أَشَدُّ</span> <span class=\"quran-arabic-font text-success\">مِنْهُمْ</span> <span class=\"quran-arabic-font text-success\">قُوَّةً﴿</span><br />\r\n<br />\r\n(அவர்களைப் படைத்த அல்லாஹ், அவர்களை விட வலிமையில் மிகச் சிறந்தவன் என்பதை அவர்கள் உணரவில்லையா?) அதாவது, அவர்கள் பகைமை காட்டும்போது, அனைத்துப் பொருட்களையும் படைத்து, அவர்களுக்கு வலிமையை வழங்கியவன் சர்வ வல்லமையுள்ள அல்லாஹ்வே என்பதையும், அவனது பிடி மிகவும் கடுமையானதாக இருக்கும் என்பதையும் அவர்கள் உணரவில்லையா? இது பின்வரும் வசனத்தைப் போன்றது:<span class=\"quran-arabic-font text-success\">﴾وَالسَّمَآءَ</span> <span class=\"quran-arabic-font text-success\">بَنَيْنَـهَا</span> <span class=\"quran-arabic-font text-success\">بِأَيْدٍ</span> <span class=\"quran-arabic-font text-success\">وَإِنَّا</span> <span class=\"quran-arabic-font text-success\">لَمُوسِعُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(வானத்தை நாம் நம் வல்லமையைக் கொண்டு அமைத்தோம். நிச்சயமாக நாம் அதனை விரிவுபடுத்திக் கொண்டே இருப்பவர்கள்.) (<a href=\"qurandisp.php?sura=51&ayah=47\" class=\"link\">51:47</a>). அவர்கள் சர்வ வல்லமையுள்ளவனை வெளிப்படையாகவே எதிர்த்தனர்; <span class=\"quran-arabic-font text-success\">﴾وَكَانُواْ</span> <span class=\"quran-arabic-font text-success\">بِـَايَـتِنَا</span> <span class=\"quran-arabic-font text-success\">يَجْحَدُونَ﴿</span> அவனது அத்தாட்சிகளை மறுத்தனர்; அவனது தூதருக்கு மாறுசெய்தனர். அல்லாஹ் கூறினான்:<span class=\"quran-arabic-font text-success\">﴾فَأَرْسَلْنَا</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">رِيحاً</span> <span class=\"quran-arabic-font text-success\">صَرْصَراً﴿</span><br />\r\n<br />\r\n(எனவே, நாம் அவர்கள் மீது ஒரு 'ஸர்ஸர்' (சீறும் கடிய) காற்றை அனுப்பினோம்.) சிலர் இது பலமாக வீசும் காற்று என்றனர்; மற்றவர்கள் இது ஒரு கடும் குளிர் காற்று என்றனர். சத்தத்தை எழுப்பக்கூடிய காற்று என்றும் கூறப்பட்டது. உண்மையில், அது இவை அனைத்தையும் கொண்டிருந்தது. ஏனெனில், அது தங்களின் உடல் வலிமையைக் கண்டு ஏமாந்த அவர்களுக்குப் பொருத்தமான தண்டனையாக அமைந்த மிக பலமான காற்றாகும். மேலும் அது கடுங்குளிராகவும் இருந்தது. அல்லாஹ் கூறுவது போல:<span class=\"quran-arabic-font text-success\">﴾بِرِيحٍ</span> <span class=\"quran-arabic-font text-success\">صَرْصَرٍ</span> <span class=\"quran-arabic-font text-success\">عَاتِيَةٍ﴿</span><br />\r\n<br />\r\n('ஸர்ஸர்' காற்றுடன்!) (<a href=\"qurandisp.php?sura=69&ayah=6\" class=\"link\">69:6</a>), அதாவது மிகவும் குளிர்ந்த காற்று. அது பயங்கரமான ஒலியையும் எழுப்பியது. மேலும், கிழக்கில் 'ஸர்ஸர்' என்ற பெயரில் ஒரு புகழ்பெற்ற நதி உள்ளது. அது பாயும்போது எழுப்பும் சத்தத்தின் காரணமாகவே அவ்வாறு அழைக்கப்படுகிறது.<span class=\"quran-arabic-font text-success\">﴾فِى</span> <span class=\"quran-arabic-font text-success\">أَيَّامٍ</span> <span class=\"quran-arabic-font text-success\">نَّحِسَاتٍ﴿</span><br />\r\n<br />\r\n(துரதிர்ஷ்டவசமான நாட்களில்) அதாவது, தொடர்ச்சியான நாட்கள்.<span class=\"quran-arabic-font text-success\">﴾سَبْعَ</span> <span class=\"quran-arabic-font text-success\">لَيَالٍ</span> <span class=\"quran-arabic-font text-success\">وَثَمَـنِيَةَ</span> <span class=\"quran-arabic-font text-success\">أَيَّامٍ</span> <span class=\"quran-arabic-font text-success\">حُسُوماً﴿</span><br />\r\n<br />\r\n(தொடர்ச்சியாக ஏழு இரவுகளும் எட்டுப் பகல்களும்) (<a href=\"qurandisp.php?sura=69&ayah=7\" class=\"link\">69:7</a>). இது பின்வரும் வசனத்தைப் போன்றது:<span class=\"quran-arabic-font text-success\">﴾فِى</span> <span class=\"quran-arabic-font text-success\">يَوْمِ</span> <span class=\"quran-arabic-font text-success\">نَحْسٍ</span> <span class=\"quran-arabic-font text-success\">مُّسْتَمِرٍّ﴿</span><br />\r\n<br />\r\n(தொடர்ச்சியான ஒரு துரதிர்ஷ்டமான நாளில்) (<a href=\"qurandisp.php?sura=54&ayah=19\" class=\"link\">54:19</a>). அதாவது, அந்தத் தண்டனை அவர்களுக்கு ஒரு கெட்ட சகுனமான நாளில் தொடங்கியது. அந்தத் தீய சகுனம் அவர்களுக்குத் தொடர்ந்தது.<span class=\"quran-arabic-font text-success\">﴾سَبْعَ</span> <span class=\"quran-arabic-font text-success\">لَيَالٍ</span> <span class=\"quran-arabic-font text-success\">وَثَمَـنِيَةَ</span> <span class=\"quran-arabic-font text-success\">أَيَّامٍ</span> <span class=\"quran-arabic-font text-success\">حُسُوماً﴿</span><br />\r\n<br />\r\n(தொடர்ச்சியாக ஏழு இரவுகளும் எட்டுப் பகல்களும்) (<a href=\"qurandisp.php?sura=69&ayah=7\" class=\"link\">69:7</a>). அவர்கள் அனைவரும் முற்றிலும் அழிக்கப்படும் வரை (அது தொடர்ந்தது). இவ்வுலகில் அவர்கள் அடைந்த இழிவு, மறுமையில் அவர்கள் அனுபவிக்கப்போகும் தண்டனையுடன் இணைக்கப்பட்டது. அல்லாஹ் கூறுகிறான்:<span class=\"quran-arabic-font text-success\">﴾لِّنُذِيقَهُمْ</span> <span class=\"quran-arabic-font text-success\">عَذَابَ</span> <span class=\"quran-arabic-font text-success\">الْخِزْىِ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْحَيَوةِ</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span> <span class=\"quran-arabic-font text-success\">وَلَعَذَابُ</span> <span class=\"quran-arabic-font text-success\">الاٌّخِرَةِ</span> <span class=\"quran-arabic-font text-success\">أَخْزَى﴿</span><br />\r\n<br />\r\n(இவ்வுலக வாழ்விலேயே இழிவுபடுத்தும் வேதனையை அவர்கள் சுவைக்கும்படிச் செய்வதற்காக. ஆனால் நிச்சயமாக மறுமையின் வேதனை மிக அதிக இழிவைத் தருவதாகும்.) அதாவது, அவர்களுக்கு அது அதிக அவமானத்தைத் தரும்.<span class=\"quran-arabic-font text-success\">﴾وَهُمْ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يُنصَرُونَ﴿</span><br />\r\n<br />\r\n(மேலும் அவர்கள் உதவி செய்யப்பட மாட்டார்கள்.) அதாவது, இவ்வுலகில் அவர்களுக்கு எவ்வித உதவியும் கிடைக்காதது போலவே மறுமையிலும் உதவி கிடைக்காது. அல்லாஹ்விடமிருந்து அவர்களைப் பாதுகாப்பவரோ அல்லது அவனது தண்டனையிலிருந்து அவர்களைக் காப்பாற்றுபவரோ எவரும் இருக்க மாட்டார்கள்.<span class=\"quran-arabic-font text-success\">﴾وَأَمَّا</span> <span class=\"quran-arabic-font text-success\">ثَمُودُ</span> <span class=\"quran-arabic-font text-success\">فَهَدَيْنَـهُمْ﴿</span><br />\r\n<br />\r\n(ஸமூது சமூகத்தினருக்கோ, நாம் அவர்களுக்கு நேர்வழியைக் காட்டினோம்.) இப்னு அப்பாஸ் (ரழி), அபுல் ஆலியா, ஸயீத் பின் ஜுபைர், கதாதா, அஸ்-ஸுத்தி மற்றும் இப்னு ஸைத் ஆகியோர் இதற்கு, \"நாம் அவர்களுக்கு விளக்கினோம்\" என்று கூறினார்கள். அத்-தவ்ரி அவர்கள், \"நாம் அவர்களை அழைத்தோம்\" என்று கூறினார்கள். அல்லாஹ்வின் கூற்று;<span class=\"quran-arabic-font text-success\">﴾فَاسْتَحَبُّواْ</span> <span class=\"quran-arabic-font text-success\">الْعَمَى</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الْهُدَى﴿</span><br />\r\n<br />\r\n(ஆனால் அவர்கள் நேர்வழியை விடக் குருட்டுத்தனத்தையே (வழிகேட்டையே) விரும்பினார்கள்;) அதாவது, \"நாம் அவர்களுக்கு உண்மையை உணர்த்தினோம். அவர்களின் தூதர் ஸாலிஹ் (அலை) அவர்களின் வார்த்தைகள் மூலம் அதனைத் தெளிவுபடுத்தினோம். ஆனால் அவர்கள் அவரை எதிர்த்துப் புறக்கணித்தனர். மேலும், அவர்களின் தூதரின் உண்மைத்தன்மைக்கு ஓர் அத்தாட்சியாக அல்லாஹ் ஆக்கியிருந்த அவனது பெண் ஒட்டகத்தை அவர்கள் கொன்றனர்.\"<span class=\"quran-arabic-font text-success\">﴾فَأَخَذَتْهُمْ</span> <span class=\"quran-arabic-font text-success\">صَاعِقَةُ</span> <span class=\"quran-arabic-font text-success\">الْعَذَابِ</span> <span class=\"quran-arabic-font text-success\">الْهُونِ﴿</span><br />\r\n<br />\r\n(எனவே இழிவுபடுத்தும் வேதனையின் பேரொலி (இடி) அவர்களைப் பிடித்துக்கொண்டது.) அதாவது, அல்லாஹ் அவர்கள் மீது 'ஸய்ஹா' (பேரொலி), நிலநடுக்கம், கடுமையான இழிவு, தண்டனை மற்றும் வேதனையை அனுப்பினான்.<span class=\"quran-arabic-font text-success\">﴾بِمَا</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">يَكْسِبُونَ﴿</span><br />\r\n<br />\r\n(அவர்கள் சம்பாதித்துக் கொண்டிருந்தவற்றின் காரணமாக.) அதாவது, அவர்களின் இறைநிராகரிப்பு மற்றும் மறுப்பின் காரணமாக.<span class=\"quran-arabic-font text-success\">﴾وَنَجَّيْنَا</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ءَامَنُواْ</span> <span class=\"quran-arabic-font text-success\">وَكَانُواْ</span> <span class=\"quran-arabic-font text-success\">يَتَّقُونَ﴿</span><br />\r\n<br />\r\n(மேலும், நம்பிக்கை கொண்டவர்களை நாம் காப்பாற்றினோம்; அவர்கள் (இறைவனை) அஞ்சுவோராக இருந்தனர்.) அதாவது, \"அவர்களிடமிருந்து முஃமின்களை நாம் காப்பாற்றினோம்; அவர்களுக்கு எந்தத் தீங்கும் நேரவில்லை.\" அவர்கள் அல்லாஹ்வைப் பயந்து நடந்துகொண்டதால், அல்லாஹ் அவர்களை அவனது தூதர் ஸாலிஹ் (அலை) அவர்களோடு சேர்த்து காப்பாற்றினான்.<br />\r\n<br />","text":"நிராகரிப்பாளர்களுக்கு ஓர் எச்சரிக்கையும் ஆது மற்றும் ஸமூது கூட்டத்தாரின் வரலாற்றினைப் பற்றிய நினைவூட்டலும்\n\r\n\n\r\nஅல்லாஹ் கூறுகிறான்: \"முஹம்மது (ஸல்) அவர்களே! நீர் கொண்டு வந்த சத்தியச் செய்தியை நிராகரிக்கின்ற இந்த இணைவைப்பாளர்களிடம் கூறுவீராக: அல்லாஹ்விடமிருந்து நான் உங்களிடம் கொண்டு வந்ததை நீங்கள் புறக்கணித்தால், இறைத்தூதர்களை நிராகரித்ததற்காக முந்தைய சமுதாயத்தினர் அனுபவித்த வேதனையைப் போன்ற அல்லாஹ்வின் தண்டனையைக் குறித்து நான் உங்களை எச்சரிக்கிறேன்.\"﴾فَإِنْ أَعْرَضُواْ فَقُلْ أَنذَرْتُكُمْ صَاعِقَةً مِّثْلَ صَاعِقَةِ عَادٍ وَثَمُودَ﴿\n\r\n\n\r\n(ஆது மற்றும் ஸமூது கூட்டத்தாரைத் தாக்கிய அந்தப் பேரொலி (இடி) போன்றதொரு பேரொலி.) இவர்களைப் போன்றே செயல்பட்ட மற்ற சமுதாயத்தினரையும் அது தாக்கியது.﴾إِذْ جَآءَتْهُمُ الرُّسُلُ مِن بَيْنِ أَيْدِيهِمْ وَمِنْ خَلْفِهِمْ﴿\n\r\n\n\r\n(இறைத்தூதர்கள் அவர்களுக்கு முன்னாலும் பின்னாலும் வந்தபோது). இது பின்வரும் வசனத்தைப் போன்றதாகும்:﴾وَاذْكُرْ أَخَا عَادٍ إِذْ أَنذَرَ قَوْمَهُ بِالاٌّحْقَافِ وَقَدْ خَلَتِ النُّذُرُ مِن بَيْنِ يَدَيْهِ وَمِنْ خَلْفِهِ﴿\n\r\n\n\r\n(ஆது கூட்டத்தாரின் சகோதரரான ஹூத் (அலை) அவர்களை நினைவுகூறுவீராக! அவர் 'அஹ்காஃப்' பகுதியில் இருந்த தம் சமூகத்தாரை எச்சரித்தபோது, அவருக்கு முன்னரும் பின்னரும் எச்சரிக்கையாளர்கள் பலர் கடந்து சென்றுள்ளனர்.) (46:21). அதாவது, அண்டை ஊர்களிலும் நகரங்களிலும் அல்லாஹ் தூதர்களை அனுப்பினான். ﴾أَلاَّ تَعْبُدُواْ إِلاَّ اللَّهَ﴿ அவர்கள் இணைதுணையற்ற அல்லாஹ் ஒருவனையே வணங்குமாறு மக்களுக்குக் கட்டளையிட்டனர். மேலும் அவர்கள் நற்செய்திகளையும் எச்சரிக்கைகளையும் கொண்டு வந்தனர். அல்லாஹ் தன் எதிரிகளுக்கு வழங்கிய தண்டனையையும், தன் நேசர்களுக்கு வழங்கிய அருட்கொடைகளையும் அவர்கள் கண்டனர். இருப்பினும், அவர்கள் அத்தூதர்களை நம்பிக்கை கொள்ளவில்லை. மாறாக, அவர்களைப் பொய்யாக்கிப் புறக்கணித்தனர். மேலும் அவர்கள் கூறினார்கள்:﴾لَوْ شَآءَ رَبُّنَا لَأَنزَلَ مَلَـئِكَةً﴿\n\r\n\n\r\n(\"எங்கள் இறைவன் நாடியிருந்தால், நிச்சயமாக வானவர்களையே இறக்கியிருப்பான்.\") அதாவது, அல்லாஹ் தூதர்களை அனுப்புவதாக இருந்தால், அவர்கள் அவனிடமிருந்து அனுப்பப்பட்ட வானவர்களாகத்தான் இருந்திருப்பார்கள்.﴾فَإِنَّا بِمَآ أُرْسِلْتُمْ بِهِ كَـفِرُونَ﴿\n\r\n\n\r\n(\"எனவே, நீங்கள் எதைக் கொண்டு அனுப்பப்பட்டீர்களோ அதை நிச்சயமாக நாங்கள் நிராகரிக்கிறோம்.\") இதன் பொருள்: \"நீங்கள் ஒரு சாதாரண மனிதர்தான்; எங்களைப் போன்ற மனிதர்களாக இருப்பதால் நாங்கள் உங்களைப் பின்பற்ற மாட்டோம்\" என்பதாகும்.﴾فَأَمَّا عَادٌ فَاسْتَكْبَرُواْ فِى الاٌّرْضِ بِغَيْرِ الْحَقِّ﴿\n\r\n\n\r\n(ஆது கூட்டத்தாரோ, பூமியில் அநியாயமாகப் பெருமையடித்தார்கள்.) அதாவது, அவர்கள் ஆணவம் கொண்டும், பிடிவாதமாகவும், கீழ்ப்படியாமலும் நடந்துகொண்டனர்.﴾وَقَالُواْ مَنْ أَشَدُّ مِنَّا قُوَّةً﴿\n\r\n\n\r\n(மேலும் அவர்கள், \"வலிமையில் எங்களை விடச் சிறந்தவர் யார்?\" என்று கூறினார்கள்.) அவர்கள் தங்களின் உடல் வலிமையையும் ஆற்றலையும் குறித்துப் பெருமை பேசினார்கள். இது அல்லாஹ்வின் தண்டனையிலிருந்து தங்களைப் பாதுகாக்கும் என்று அவர்கள் எண்ணினார்கள்.﴾أَوَلَمْ يَرَوْاْ أَنَّ اللَّهَ الَّذِى خَلَقَهُمْ هُوَ أَشَدُّ مِنْهُمْ قُوَّةً﴿\n\r\n\n\r\n(அவர்களைப் படைத்த அல்லாஹ், அவர்களை விட வலிமையில் மிகச் சிறந்தவன் என்பதை அவர்கள் உணரவில்லையா?) அதாவது, அவர்கள் பகைமை காட்டும்போது, அனைத்துப் பொருட்களையும் படைத்து, அவர்களுக்கு வலிமையை வழங்கியவன் சர்வ வல்லமையுள்ள அல்லாஹ்வே என்பதையும், அவனது பிடி மிகவும் கடுமையானதாக இருக்கும் என்பதையும் அவர்கள் உணரவில்லையா? இது பின்வரும் வசனத்தைப் போன்றது:﴾وَالسَّمَآءَ بَنَيْنَـهَا بِأَيْدٍ وَإِنَّا لَمُوسِعُونَ ﴿\n\r\n\n\r\n(வானத்தை நாம் நம் வல்லமையைக் கொண்டு அமைத்தோம். நிச்சயமாக நாம் அதனை விரிவுபடுத்திக் கொண்டே இருப்பவர்கள்.) (51:47). அவர்கள் சர்வ வல்லமையுள்ளவனை வெளிப்படையாகவே எதிர்த்தனர்; ﴾وَكَانُواْ بِـَايَـتِنَا يَجْحَدُونَ﴿ அவனது அத்தாட்சிகளை மறுத்தனர்; அவனது தூதருக்கு மாறுசெய்தனர். அல்லாஹ் கூறினான்:﴾فَأَرْسَلْنَا عَلَيْهِمْ رِيحاً صَرْصَراً﴿\n\r\n\n\r\n(எனவே, நாம் அவர்கள் மீது ஒரு 'ஸர்ஸர்' (சீறும் கடிய) காற்றை அனுப்பினோம்.) சிலர் இது பலமாக வீசும் காற்று என்றனர்; மற்றவர்கள் இது ஒரு கடும் குளிர் காற்று என்றனர். சத்தத்தை எழுப்பக்கூடிய காற்று என்றும் கூறப்பட்டது. உண்மையில், அது இவை அனைத்தையும் கொண்டிருந்தது. ஏனெனில், அது தங்களின் உடல் வலிமையைக் கண்டு ஏமாந்த அவர்களுக்குப் பொருத்தமான தண்டனையாக அமைந்த மிக பலமான காற்றாகும். மேலும் அது கடுங்குளிராகவும் இருந்தது. அல்லாஹ் கூறுவது போல:﴾بِرِيحٍ صَرْصَرٍ عَاتِيَةٍ﴿\n\r\n\n\r\n('ஸர்ஸர்' காற்றுடன்!) (69:6), அதாவது மிகவும் குளிர்ந்த காற்று. அது பயங்கரமான ஒலியையும் எழுப்பியது. மேலும், கிழக்கில் 'ஸர்ஸர்' என்ற பெயரில் ஒரு புகழ்பெற்ற நதி உள்ளது. அது பாயும்போது எழுப்பும் சத்தத்தின் காரணமாகவே அவ்வாறு அழைக்கப்படுகிறது.﴾فِى أَيَّامٍ نَّحِسَاتٍ﴿\n\r\n\n\r\n(துரதிர்ஷ்டவசமான நாட்களில்) அதாவது, தொடர்ச்சியான நாட்கள்.﴾سَبْعَ لَيَالٍ وَثَمَـنِيَةَ أَيَّامٍ حُسُوماً﴿\n\r\n\n\r\n(தொடர்ச்சியாக ஏழு இரவுகளும் எட்டுப் பகல்களும்) (69:7). இது பின்வரும் வசனத்தைப் போன்றது:﴾فِى يَوْمِ نَحْسٍ مُّسْتَمِرٍّ﴿\n\r\n\n\r\n(தொடர்ச்சியான ஒரு துரதிர்ஷ்டமான நாளில்) (54:19). அதாவது, அந்தத் தண்டனை அவர்களுக்கு ஒரு கெட்ட சகுனமான நாளில் தொடங்கியது. அந்தத் தீய சகுனம் அவர்களுக்குத் தொடர்ந்தது.﴾سَبْعَ لَيَالٍ وَثَمَـنِيَةَ أَيَّامٍ حُسُوماً﴿\n\r\n\n\r\n(தொடர்ச்சியாக ஏழு இரவுகளும் எட்டுப் பகல்களும்) (69:7). அவர்கள் அனைவரும் முற்றிலும் அழிக்கப்படும் வரை (அது தொடர்ந்தது). இவ்வுலகில் அவர்கள் அடைந்த இழிவு, மறுமையில் அவர்கள் அனுபவிக்கப்போகும் தண்டனையுடன் இணைக்கப்பட்டது. அல்லாஹ் கூறுகிறான்:﴾لِّنُذِيقَهُمْ عَذَابَ الْخِزْىِ فِى الْحَيَوةِ الدُّنْيَا وَلَعَذَابُ الاٌّخِرَةِ أَخْزَى﴿\n\r\n\n\r\n(இவ்வுலக வாழ்விலேயே இழிவுபடுத்தும் வேதனையை அவர்கள் சுவைக்கும்படிச் செய்வதற்காக. ஆனால் நிச்சயமாக மறுமையின் வேதனை மிக அதிக இழிவைத் தருவதாகும்.) அதாவது, அவர்களுக்கு அது அதிக அவமானத்தைத் தரும்.﴾وَهُمْ لاَ يُنصَرُونَ﴿\n\r\n\n\r\n(மேலும் அவர்கள் உதவி செய்யப்பட மாட்டார்கள்.) அதாவது, இவ்வுலகில் அவர்களுக்கு எவ்வித உதவியும் கிடைக்காதது போலவே மறுமையிலும் உதவி கிடைக்காது. அல்லாஹ்விடமிருந்து அவர்களைப் பாதுகாப்பவரோ அல்லது அவனது தண்டனையிலிருந்து அவர்களைக் காப்பாற்றுபவரோ எவரும் இருக்க மாட்டார்கள்.﴾وَأَمَّا ثَمُودُ فَهَدَيْنَـهُمْ﴿\n\r\n\n\r\n(ஸமூது சமூகத்தினருக்கோ, நாம் அவர்களுக்கு நேர்வழியைக் காட்டினோம்.) இப்னு அப்பாஸ் (ரழி), அபுல் ஆலியா, ஸயீத் பின் ஜுபைர், கதாதா, அஸ்-ஸுத்தி மற்றும் இப்னு ஸைத் ஆகியோர் இதற்கு, \"நாம் அவர்களுக்கு விளக்கினோம்\" என்று கூறினார்கள். அத்-தவ்ரி அவர்கள், \"நாம் அவர்களை அழைத்தோம்\" என்று கூறினார்கள். அல்லாஹ்வின் கூற்று;﴾فَاسْتَحَبُّواْ الْعَمَى عَلَى الْهُدَى﴿\n\r\n\n\r\n(ஆனால் அவர்கள் நேர்வழியை விடக் குருட்டுத்தனத்தையே (வழிகேட்டையே) விரும்பினார்கள்;) அதாவது, \"நாம் அவர்களுக்கு உண்மையை உணர்த்தினோம். அவர்களின் தூதர் ஸாலிஹ் (அலை) அவர்களின் வார்த்தைகள் மூலம் அதனைத் தெளிவுபடுத்தினோம். ஆனால் அவர்கள் அவரை எதிர்த்துப் புறக்கணித்தனர். மேலும், அவர்களின் தூதரின் உண்மைத்தன்மைக்கு ஓர் அத்தாட்சியாக அல்லாஹ் ஆக்கியிருந்த அவனது பெண் ஒட்டகத்தை அவர்கள் கொன்றனர்.\"﴾فَأَخَذَتْهُمْ صَاعِقَةُ الْعَذَابِ الْهُونِ﴿\n\r\n\n\r\n(எனவே இழிவுபடுத்தும் வேதனையின் பேரொலி (இடி) அவர்களைப் பிடித்துக்கொண்டது.) அதாவது, அல்லாஹ் அவர்கள் மீது 'ஸய்ஹா' (பேரொலி), நிலநடுக்கம், கடுமையான இழிவு, தண்டனை மற்றும் வேதனையை அனுப்பினான்.﴾بِمَا كَانُواْ يَكْسِبُونَ﴿\n\r\n\n\r\n(அவர்கள் சம்பாதித்துக் கொண்டிருந்தவற்றின் காரணமாக.) அதாவது, அவர்களின் இறைநிராகரிப்பு மற்றும் மறுப்பின் காரணமாக.﴾وَنَجَّيْنَا الَّذِينَ ءَامَنُواْ وَكَانُواْ يَتَّقُونَ﴿\n\r\n\n\r\n(மேலும், நம்பிக்கை கொண்டவர்களை நாம் காப்பாற்றினோம்; அவர்கள் (இறைவனை) அஞ்சுவோராக இருந்தனர்.) அதாவது, \"அவர்களிடமிருந்து முஃமின்களை நாம் காப்பாற்றினோம்; அவர்களுக்கு எந்தத் தீங்கும் நேரவில்லை.\" அவர்கள் அல்லாஹ்வைப் பயந்து நடந்துகொண்டதால், அல்லாஹ் அவர்களை அவனது தூதர் ஸாலிஹ் (அலை) அவர்களோடு சேர்த்து காப்பாற்றினான்."},"19":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=41&ayah=24\" class=\"link\">41:24</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 41:24 ஐ பார்க்கவும்"},"20":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=41&ayah=24\" class=\"link\">41:24</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 41:24 ஐ பார்க்கவும்"},"21":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=41&ayah=24\" class=\"link\">41:24</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 41:24 ஐ பார்க்கவும்"},"22":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=41&ayah=24\" class=\"link\">41:24</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 41:24 ஐ பார்க்கவும்"},"23":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=41&ayah=24\" class=\"link\">41:24</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 41:24 ஐ பார்க்கவும்"},"24":{"html":"<strong>மறுமை நாளில் பாவிகளின் உடல் உறுப்புகள் அவர்களுக்கு எதிராகச் சாட்சியளிக்கும்</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَيَوْمَ</span> <span class=\"quran-arabic-font text-success\">يُحْشَرُ</span> <span class=\"quran-arabic-font text-success\">أَعْدَآءُ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">النَّارِ</span> <span class=\"quran-arabic-font text-success\">فَهُمْ</span> <span class=\"quran-arabic-font text-success\">يُوزَعُونَ</span><br />\r\n<br />\r\n(அல்லாஹ்வின் எதிரிகள் நரக நெருப்பை நோக்கி ஒன்றுதிரட்டப்பட்டு, பின்னர் அவர்கள் அணிவகுத்து நிறுத்தப்படும் அந்நாளை (நபியே! நீர் நினைவுகூருவீராக).) அதாவது, இந்த இணைவைப்பாளர்கள் நரக நெருப்பை நோக்கி ஒன்றுதிரட்டப்பட்டு ஓட்டிச் செல்லப்படும் அந்த நாளை அவர்களுக்கு நினைவுபடுத்துவீராக. நரகத்தின் காவலாளிகள் அவர்களின் முந்தையவர்களையும் பிந்தையவர்களையும் ஒன்று சேர்ப்பார்கள் என்பதை இது குறிக்கிறது. இதனை அல்லாஹ் வேறொரு வசனத்தில் இவ்வாறு கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَنَسُوقُ</span> <span class=\"quran-arabic-font text-success\">الْمُجْرِمِينَ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">جَهَنَّمَ</span> <span class=\"quran-arabic-font text-success\">وِرْداً</span><br />\r\n<br />\r\n(மேலும் குற்றவாளிகளைத் தாகித்த நிலையில் நரகத்திற்கு ஓட்டிச் செல்வோம்) (<a href=\"qurandisp.php?sura=19&ayah=86\" class=\"link\">19:86</a>). <br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">جَآءُوهَا</span><br />\r\n<br />\r\n(இறுதியாக, அவர்கள் அ(ந்நரகத்)தை அடையும்போது,) அதாவது அவர்கள் அதன் விளிம்பில் நின்றுகொண்டிருக்கும்போது,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">شَهِدَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">سَمْعُهُمْ</span> <span class=\"quran-arabic-font text-success\">وَأَبْصَارُهُمْ</span> <span class=\"quran-arabic-font text-success\">وَجُلُودُهُم</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">يَعْمَلُونَ</span><br />\r\n<br />\r\n(அவர்களுடைய காதுகளும், அவர்களுடைய கண்களும், அவர்களுடைய தோல்களும் அவர்கள் செய்துகொண்டிருந்தவை பற்றி அவர்களுக்கு எதிராகச் சாட்சியளிக்கும்.) அதாவது அவர்களின் முந்தைய மற்றும் பிந்தைய செயல்கள் அனைத்தும் சாட்சியமாக முன்வைக்கப்படும்; ஒரு சிறிய விஷயம் கூட மறைக்கப்படாது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَقَالُواْ</span> <span class=\"quran-arabic-font text-success\">لِجُلُودِهِمْ</span> <span class=\"quran-arabic-font text-success\">لِمَ</span> <span class=\"quran-arabic-font text-success\">شَهِدتُّمْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْنَا</span><br />\r\n<br />\r\n(மேலும் அவர்கள் தங்கள் தோல்களைப் பார்த்து, “ஏன் எங்களுக்கு எதிராகச் சாட்சியளித்தீர்கள்?” என்று கேட்பார்கள்.) தங்களுக்கு எதிராகச் சாட்சியளிக்கும்போது அவர்கள் தங்கள் உடல் உறுப்புகளையும் தோல்களையும் குறை கூறுவார்கள். அதற்கு அந்த உறுப்புகள் இவ்வாறு பதிலளிக்கும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">أَنطَقَنَا</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">أَنطَقَ</span> <span class=\"quran-arabic-font text-success\">كُلَّ</span> <span class=\"quran-arabic-font text-success\">شَىْءٍ</span> <span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">خَلَقَكُمْ</span> <span class=\"quran-arabic-font text-success\">أَوَّلَ</span> <span class=\"quran-arabic-font text-success\">مَرَّةٍ</span> <span class=\"quran-arabic-font text-success\">وَإِلَيْهِ</span> <span class=\"quran-arabic-font text-success\">تُرْجَعُونَ</span><br />\r\n<br />\r\n(அதற்கு அவை, “எல்லாப் பொருட்களையும் பேச வைக்கும் அல்லாஹ்வே எங்களையும் பேச வைத்தான். அவன்தான் உங்களை முதல் முறையும் படைத்தான்; மேலும் அவனிடமே நீங்கள் திரும்பக் கொண்டுவரப்படுவீர்கள்” என்று கூறும்.) அதாவது, அல்லாஹ்வை யாராலும் எதிர்க்கவோ தடுக்கவோ முடியாது. அவனிடமே நீங்கள் அனைவரும் திரும்பச் செல்வீர்கள். அனஸ் பின் மாலிக் (ரழி) அவர்கள் அறிவித்ததாக அல்-ஹாஃபிழ் அபூ பக்ர் அல்-பஸ்ஸார் குறிப்பிடுகிறார்கள்: ஒருமுறை அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் சிரித்துவிட்டுப் புன்னகையோடு கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أَلَا</span> <span class=\"quran-arabic-font text-success\">تَسْأَلُونِّي</span> <span class=\"quran-arabic-font text-success\">عَنْ</span> <span class=\"quran-arabic-font text-success\">أَيِّ</span> <span class=\"quran-arabic-font text-success\">شَيْءٍ</span> <span class=\"quran-arabic-font text-success\">ضَحِكْتُ؟</span>»<br />\r\n<br />\r\n(“நான் ஏன் சிரித்தேன் என்று நீங்கள் என்னிடம் கேட்க மாட்டீர்களா?”) மக்கள், “அல்லாஹ்வின் தூதரே! தாங்கள் ஏன் சிரித்தீர்கள்?” என்று கேட்டார்கள். அதற்கு அவர்கள் (ஸல்) கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">عَجِبْتُ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">مُجَادَلَةِ</span> <span class=\"quran-arabic-font text-success\">الْعَبْدِ</span> <span class=\"quran-arabic-font text-success\">رَبَّهُ</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">الْقِيَامَةِ</span> <span class=\"quran-arabic-font text-success\">يَقُولُ</span>: <span class=\"quran-arabic-font text-success\">أَيْ</span> <span class=\"quran-arabic-font text-success\">رَبِّي</span> <span class=\"quran-arabic-font text-success\">أَلَيْسَ</span> <span class=\"quran-arabic-font text-success\">وَعَدْتَنِي</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">تَظْلِمَنِي،</span> <span class=\"quran-arabic-font text-success\">قَالَ</span>: <span class=\"quran-arabic-font text-success\">بَلَى،</span> <span class=\"quran-arabic-font text-success\">فَيَقُولُ</span>: <span class=\"quran-arabic-font text-success\">فَإِنِّي</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">أَقْبَلُ</span> <span class=\"quran-arabic-font text-success\">عَلَيَّ</span> <span class=\"quran-arabic-font text-success\">شَاهِدًا</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">نَفْسِي،</span> <span class=\"quran-arabic-font text-success\">فَيَقُولُ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">تَبَارَكَ</span> <span class=\"quran-arabic-font text-success\">وَتَعَالَى</span>: <span class=\"quran-arabic-font text-success\">أَوَلَيْسَ</span> <span class=\"quran-arabic-font text-success\">كَفَى</span> <span class=\"quran-arabic-font text-success\">بِي</span> <span class=\"quran-arabic-font text-success\">شَهِيدًا</span> <span class=\"quran-arabic-font text-success\">وَبِالْمَلَائِكَةِ</span> <span class=\"quran-arabic-font text-success\">الْكِرَام</span> <span class=\"quran-arabic-font text-success\">الْكَاتِبِينَ</span> <span class=\"quran-arabic-font text-success\">قال</span> : <span class=\"quran-arabic-font text-success\">فَيُرَدِّدُ</span> <span class=\"quran-arabic-font text-success\">هذَا</span> <span class=\"quran-arabic-font text-success\">الْكَلَامَ</span> <span class=\"quran-arabic-font text-success\">مِرَارًا</span> <span class=\"quran-arabic-font text-success\">قال</span> : <span class=\"quran-arabic-font text-success\">فَيُخْتَمُ</span> <span class=\"quran-arabic-font text-success\">عَلى</span> <span class=\"quran-arabic-font text-success\">فِيهِ</span> <span class=\"quran-arabic-font text-success\">وَتَتَكَلَّمُ</span> <span class=\"quran-arabic-font text-success\">أَرْكَانُهُ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">يَعْمَلُ،</span> <span class=\"quran-arabic-font text-success\">فَيَقُولُ</span>: <span class=\"quran-arabic-font text-success\">بُعْدًا</span> <span class=\"quran-arabic-font text-success\">لَكُنَّ</span> <span class=\"quran-arabic-font text-success\">وَسُحْقًا،</span> <span class=\"quran-arabic-font text-success\">عَنْكُنَّ</span> <span class=\"quran-arabic-font text-success\">كُنْتُ</span> <span class=\"quran-arabic-font text-success\">أُجَادِل</span>»<br />\r\n<br />\r\n(மறுமை நாளில் ஓர் அடியான் தன் இறைவனிடம் விவாதம் செய்வதைக் கண்டு நான் வியப்படைந்தேன். அவன், “என் இறைவனே! எனக்கு அநீதி இழைக்கப்பட மாட்டாது என்று நீ எனக்கு வாக்குறுதி அளிக்கவில்லையா?” என்று கேட்பான். அல்லாஹ், “ஆம்” என்று கூறுவான். அதற்கு அந்த மனிதன், “எனக்கு எதிராக என்னிடமிருந்தே தவிர வேறு எவரது சாட்சியத்தையும் நான் ஏற்கமாட்டேன்” என்பான். அதற்கு அல்லாஹ், “நானும், கண்ணியமிக்க எழுத்தர்களான வானவர்களும் உனக்குச் சாட்சியாளர்களாக இருப்பது போதாதா?” என்று கேட்பான். இந்த வார்த்தைகள் பலமுறை திரும்பத் திரும்பக் கூறப்படும். பின்னர் அவனது வாய் முத்திரையிடப்படும். அவன் செய்துகொண்டிருந்த செயல்களைப் பற்றி அவனது உடல் உறுப்புகள் பேசும். அப்போது அவன் தன் உறுப்புகளைப் பார்த்து, “உங்களுக்குக் கேடு உண்டாகட்டும்! உங்களுக்காகத்தானே நான் (இறைவனிடம்) வாதிட்டேன்!” என்று கூறுவான்.) இதனை அல்-பஸ்ஸார் மற்றும் இப்னு அபீ ஹாதிம் பதிவு செய்துள்ளனர். மேலும் இமாம் முஸ்லிம் மற்றும் இமாம் அந்-நஸாயீ ஆகியோரும் இதனைப் பதிவு செய்துள்ளனர்.<br />\r\n<br />\r\nஅபூ மூஸா (ரழி) அவர்கள் கூறியதாக அபூ புர்தா அறிவித்ததை இப்னு அபீ ஹாதிம் பதிவு செய்துள்ளார்: “நிராகரிப்பாளன் அல்லது நயவஞ்சகன் விசாரணைக்காக அழைக்கப்படுவான். அவனது செயல்களை இறைவன் அவனுக்குக் காட்டுவான். ஆனால் அவன் அவற்றை மறுத்து, ‘என் இறைவனே! உன் கண்ணியத்தின் மீது ஆணையாக, நான் செய்யாத ஒன்றை இந்த வானவர் எனக்கு எதிராக எழுதியுள்ளார்’ என்பான். அதற்கு அந்த வானவர், ‘நீ இன்ன நாளில், இன்ன இடத்தில், இன்ன காரியத்தைச் செய்யவில்லையா?’ என்று கேட்பார். அதற்கு அவன், ‘இல்லை, உன் கண்ணியத்தின் மீது ஆணையாக! இறைவனே, நான் அதைச் செய்யவே இல்லை’ என்பான். அவன் இவ்வாறு (பொய்) கூறும்போது அவனது வாய் முத்திரையிடப்படும்.” அல்-அஷ்அரீ (ரழி) அவர்கள் கூறுகிறார்கள்: “அவனது உடலில் முதலாவதாகப் பேசும் உறுப்பு அவனது வலது தொடையாக இருக்கும் என்று நான் நினைக்கிறேன்.”<br />\r\n<br />\r\nஅல்லாஹ்வின் கூற்று:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">كُنتُمْ</span> <span class=\"quran-arabic-font text-success\">تَسْتَتِرُونَ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يَشْهَدَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكُمْ</span> <span class=\"quran-arabic-font text-success\">سَمْعُكُمْ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">أَبْصَارُكُمْ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">جُلُودُكُمْ</span><br />\r\n<br />\r\n(உங்கள் காதுகளும், உங்கள் கண்களும், உங்கள் தோல்களும் உங்களுக்கு எதிராகச் சாட்சியளிக்கும் என்பதை (மனதிற்கொண்டு உலகத்தில்) நீங்கள் உங்களை மறைத்துக்கொள்ளவில்லை.) அதாவது, தங்களுக்கு எதிராகச் சாட்சியளித்ததற்காக அவர்கள் தங்கள் உடல் உறுப்புகளைக் குறை கூறும்போது, அந்த உறுப்புகள் அவர்களிடம் கூறும்: 'நீங்கள் செய்தவற்றை எங்களிடமிருந்து மறைக்க முயலவில்லை. மாறாக, நீங்கள் பகிரங்கமாக நிராகரிப்பிலும் பாவத்திலும் ஈடுபட்டீர்கள். அல்லாஹ் உங்கள் செயல்களை அறிந்துகொள்ள மாட்டான் என்று எண்ணியதால் எதைப் பற்றியும் நீங்கள் கவலைப்படவில்லை.' அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَـكِن</span> <span class=\"quran-arabic-font text-success\">ظَنَنتُمْ</span> <span class=\"quran-arabic-font text-success\">أَنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَعْلَمُ</span> <span class=\"quran-arabic-font text-success\">كَثِيراً</span> <span class=\"quran-arabic-font text-success\">مِّمَّا</span> <span class=\"quran-arabic-font text-success\">تَعْمَلُونَ</span> <span class=\"quran-arabic-font text-success\">وَذَلِكُمْ</span> <span class=\"quran-arabic-font text-success\">ظَنُّكُمُ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">ظَنَنتُم</span> <span class=\"quran-arabic-font text-success\">بِرَبِّكُمْ</span> <span class=\"quran-arabic-font text-success\">أَرْدَاكُمْ</span><br />\r\n<br />\r\n(மாறாக, நீங்கள் செய்துகொண்டிருப்பவற்றில் பெரும்பாலானவற்றை அல்லாஹ் அறியமாட்டான் என்று நீங்கள் எண்ணினீர்கள். உங்கள் இறைவனைப் பற்றி நீங்கள் கொண்டிருந்த அந்த (தவறான) எண்ணம்தான் உங்களை அழிவில் வீழ்த்தியது.) அதாவது, 'அல்லாஹ் உங்கள் செயல்களை அறியமாட்டான் என்ற உங்கள் தீய எண்ணமே நீங்கள் அழிவதற்கும், உங்கள் இறைவனிடம் நஷ்டவாளிகளாக மாறுவதற்கும் காரணமாக அமைந்தது.'<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَأَصْبَحْتُمْ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْخَاسِرِينَ</span><br />\r\n<br />\r\n(இதனால் நீங்கள் நஷ்டமடைந்தோரில் ஆகிவிட்டீர்கள்!) அதாவது, 'மறுமை நாளில் நீங்கள் உங்களையும் உங்கள் குடும்பத்தாரையும் இழந்துவிட்டீர்கள்.'<br />\r\n<br />\r\nஇமாம் அஹ்மத் பதிவு செய்துள்ளார்கள்: அப்துல்லாஹ் பின் மஸ்ஊத் (ரழி) அவர்கள் கூறுகிறார்கள்: நான் கஅபாவின் திரைக்குப் பின்னால் மறைந்திருந்தேன். அப்போது மூன்று பேர் அங்கு வந்தார்கள். அவர்கள் குறைஷி குலத்தைச் சேர்ந்த ஒருவரும் ஸகீஃப் குலத்தைச் சேர்ந்த அவரது இரண்டு மைத்துனர்களும் ஆவர் (அல்லது ஸகீஃப் குலத்தைச் சேர்ந்த ஒருவரும் குறைஷி குலத்தைச் சேர்ந்த அவரது இரண்டு மைத்துனர்களும்). அவர்கள் பருத்த உடலமைப்பைக் கொண்டிருந்தனர், ஆனால் அவர்களுக்கு மார்க்க ஞானம் குறைவாகவே இருந்தது. அவர்கள் பேசிய சில வார்த்தைகள் என் காதுகளில் விழவில்லை. பிறகு அவர்களில் ஒருவன், 'நாம் இப்போது பேசுவதை அல்லாஹ் கேட்பான் என்று நினைக்கிறாயா?' என்று கேட்டான். அதற்கு மற்றொருவன், 'நாம் உரக்கப் பேசினால் அவன் கேட்பான், மெதுவாகப் பேசினால் கேட்கமாட்டான்' என்றான். அதற்கு மூன்றாமவன், 'அவன் ஒரு விஷயத்தைக் கேட்கிறான் என்றால், எல்லாவற்றையும் கேட்கவே செய்வான்' என்றான். நான் இதனை நபி (ஸல்) அவர்களிடம் தெரிவித்தேன். அப்போது அல்லாஹ் இந்த வசனங்களை வஹீயாக (இறைச்செய்தியாக) அருளினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">كُنتُمْ</span> <span class=\"quran-arabic-font text-success\">تَسْتَتِرُونَ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يَشْهَدَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكُمْ</span> <span class=\"quran-arabic-font text-success\">سَمْعُكُمْ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">أَبْصَارُكُمْ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">جُلُودُكُمْ</span><br />\r\n<br />\r\n(உங்கள் காதுகளும், உங்கள் கண்களும், உங்கள் தோல்களும் உங்களுக்கு எதிராகச் சாட்சியளிக்கும் என்பதை (மனதிற்கொண்டு உலகத்தில்) நீங்கள் உங்களை மறைத்துக்கொள்ளவில்லை) என்பது முதல்;<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْخَاسِرِينَ</span><br />\r\n<br />\r\n(நஷ்டமடைந்தோரில்!) என்பது வரை. இதனை அத்-திர்மிதி பதிவு செய்துள்ளார். இதே போன்ற ஒரு செய்தி அஹ்மத் (வேறு அறிவிப்பாளர் தொடர் வழியாக), முஸ்லிம், அத்-திர்மிதி மற்றும் புகாரி ஆகியோரால் பதிவு செய்யப்பட்டுள்ளது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَإِن</span> <span class=\"quran-arabic-font text-success\">يَصْبِرُواْ</span> <span class=\"quran-arabic-font text-success\">فَالنَّارُ</span> <span class=\"quran-arabic-font text-success\">مَثْوًى</span> <span class=\"quran-arabic-font text-success\">لَّهُمْ</span> <span class=\"quran-arabic-font text-success\">وَإِن</span> <span class=\"quran-arabic-font text-success\">يَسْتَعْتِبُواْ</span> <span class=\"quran-arabic-font text-success\">فَمَا</span> <span class=\"quran-arabic-font text-success\">هُم</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">الْمُعْتَبِينَ</span><br />\r\n<br />\r\n(எனவே அவர்கள் பொறுமையாக இருந்தாலும் நரகமே அவர்களுக்குத் தங்குமிடமாகும். அவர்கள் (அல்லாஹ்வின்) மன்னிப்பைக் கோரினாலும் அவர்கள் மன்னிக்கப்பட மாட்டார்கள்.) அதாவது, அவர்கள் பொறுமையாக இருந்தாலும் இல்லாவிட்டாலும் அவர்கள் நரகத்தில்தான் இருப்பார்கள். அதிலிருந்து தப்பிக்க அவர்களுக்கு வழியே இல்லை. அவர்கள் சாக்குப்போக்குகளைக் கூறி அல்லாஹ்வைத் திருப்திப்படுத்த முயன்றாலும், அவை ஏற்றுக்கொள்ளப்பட மாட்டாது. இப்னு ஜரீர் அவர்கள் கூறுகிறார்கள்: '(அவர்கள் மன்னிப்பைக் கோரினாலும்) என்பதன் பொருள், அவர்கள் மீண்டும் உலகிற்குத் திரும்பிச் செல்ல அனுமதி கேட்பார்கள்; ஆனால் அவர்களின் கோரிக்கை நிராகரிக்கப்படும். இது பின்வரும் வசனத்தைப் போன்றது:'<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">رَبَّنَا</span> <span class=\"quran-arabic-font text-success\">غَلَبَتْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْنَا</span> <span class=\"quran-arabic-font text-success\">شِقْوَتُنَا</span> <span class=\"quran-arabic-font text-success\">وَكُنَّا</span> <span class=\"quran-arabic-font text-success\">قَوْماً</span> <span class=\"quran-arabic-font text-success\">ضَآلِّينَ</span> - <span class=\"quran-arabic-font text-success\">رَبَّنَآ</span> <span class=\"quran-arabic-font text-success\">أَخْرِجْنَا</span> <span class=\"quran-arabic-font text-success\">مِنْهَا</span> <span class=\"quran-arabic-font text-success\">فَإِنْ</span> <span class=\"quran-arabic-font text-success\">عُدْنَا</span> <span class=\"quran-arabic-font text-success\">فَإِنَّا</span> <span class=\"quran-arabic-font text-success\">ظَـلِمُونَ</span> - <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">اخْسَئُواْ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تُكَلِّمُونِ</span><br />\r\n<br />\r\n(அவர்கள் கூறுவார்கள்: 'எங்கள் இறைவனே! எங்களது துரதிர்ஷ்டம் எங்களை மிகைத்துவிட்டது. நாங்கள் வழிதவறிய சமூகமாக இருந்தோம். எங்கள் இறைவனே! எங்களை இதிலிருந்து வெளியேற்றுவாயாக! நாங்கள் மீண்டும் (தீமைக்குத்) திரும்பினால் நிச்சயமாக நாங்கள் அநியாயக்காரர்களாகிவிடுவோம்.' அதற்கு அவன் கூறுவான்: 'இழிவடைந்த நிலையில் இதிலேயே தங்கியிருங்கள்! என்னிடம் பேசாதீர்கள்!') (<a href=\"qurandisp.php?sura=23&ayah=106\" class=\"link\">23:106</a>-108).<br />\r\n<br />","text":"மறுமை நாளில் பாவிகளின் உடல் உறுப்புகள் அவர்களுக்கு எதிராகச் சாட்சியளிக்கும்\n\r\n\n\r\nوَيَوْمَ يُحْشَرُ أَعْدَآءُ اللَّهِ إِلَى النَّارِ فَهُمْ يُوزَعُونَ\n\r\n\n\r\n(அல்லாஹ்வின் எதிரிகள் நரக நெருப்பை நோக்கி ஒன்றுதிரட்டப்பட்டு, பின்னர் அவர்கள் அணிவகுத்து நிறுத்தப்படும் அந்நாளை (நபியே! நீர் நினைவுகூருவீராக).) அதாவது, இந்த இணைவைப்பாளர்கள் நரக நெருப்பை நோக்கி ஒன்றுதிரட்டப்பட்டு ஓட்டிச் செல்லப்படும் அந்த நாளை அவர்களுக்கு நினைவுபடுத்துவீராக. நரகத்தின் காவலாளிகள் அவர்களின் முந்தையவர்களையும் பிந்தையவர்களையும் ஒன்று சேர்ப்பார்கள் என்பதை இது குறிக்கிறது. இதனை அல்லாஹ் வேறொரு வசனத்தில் இவ்வாறு கூறுகிறான்:\n\r\n\n\r\nوَنَسُوقُ الْمُجْرِمِينَ إِلَى جَهَنَّمَ وِرْداً\n\r\n\n\r\n(மேலும் குற்றவாளிகளைத் தாகித்த நிலையில் நரகத்திற்கு ஓட்டிச் செல்வோம்) (19:86).\n\r\n\n\r\nحَتَّى إِذَا مَا جَآءُوهَا\n\r\n\n\r\n(இறுதியாக, அவர்கள் அ(ந்நரகத்)தை அடையும்போது,) அதாவது அவர்கள் அதன் விளிம்பில் நின்றுகொண்டிருக்கும்போது,\n\r\n\n\r\nشَهِدَ عَلَيْهِمْ سَمْعُهُمْ وَأَبْصَارُهُمْ وَجُلُودُهُم بِمَا كَانُواْ يَعْمَلُونَ\n\r\n\n\r\n(அவர்களுடைய காதுகளும், அவர்களுடைய கண்களும், அவர்களுடைய தோல்களும் அவர்கள் செய்துகொண்டிருந்தவை பற்றி அவர்களுக்கு எதிராகச் சாட்சியளிக்கும்.) அதாவது அவர்களின் முந்தைய மற்றும் பிந்தைய செயல்கள் அனைத்தும் சாட்சியமாக முன்வைக்கப்படும்; ஒரு சிறிய விஷயம் கூட மறைக்கப்படாது.\n\r\n\n\r\nوَقَالُواْ لِجُلُودِهِمْ لِمَ شَهِدتُّمْ عَلَيْنَا\n\r\n\n\r\n(மேலும் அவர்கள் தங்கள் தோல்களைப் பார்த்து, “ஏன் எங்களுக்கு எதிராகச் சாட்சியளித்தீர்கள்?” என்று கேட்பார்கள்.) தங்களுக்கு எதிராகச் சாட்சியளிக்கும்போது அவர்கள் தங்கள் உடல் உறுப்புகளையும் தோல்களையும் குறை கூறுவார்கள். அதற்கு அந்த உறுப்புகள் இவ்வாறு பதிலளிக்கும்:\n\r\n\n\r\nقَالُواْ أَنطَقَنَا اللَّهُ الَّذِى أَنطَقَ كُلَّ شَىْءٍ وَهُوَ خَلَقَكُمْ أَوَّلَ مَرَّةٍ وَإِلَيْهِ تُرْجَعُونَ\n\r\n\n\r\n(அதற்கு அவை, “எல்லாப் பொருட்களையும் பேச வைக்கும் அல்லாஹ்வே எங்களையும் பேச வைத்தான். அவன்தான் உங்களை முதல் முறையும் படைத்தான்; மேலும் அவனிடமே நீங்கள் திரும்பக் கொண்டுவரப்படுவீர்கள்” என்று கூறும்.) அதாவது, அல்லாஹ்வை யாராலும் எதிர்க்கவோ தடுக்கவோ முடியாது. அவனிடமே நீங்கள் அனைவரும் திரும்பச் செல்வீர்கள். அனஸ் பின் மாலிக் (ரழி) அவர்கள் அறிவித்ததாக அல்-ஹாஃபிழ் அபூ பக்ர் அல்-பஸ்ஸார் குறிப்பிடுகிறார்கள்: ஒருமுறை அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் சிரித்துவிட்டுப் புன்னகையோடு கூறினார்கள்:\n\r\n\n\r\n«أَلَا تَسْأَلُونِّي عَنْ أَيِّ شَيْءٍ ضَحِكْتُ؟»\n\r\n\n\r\n(“நான் ஏன் சிரித்தேன் என்று நீங்கள் என்னிடம் கேட்க மாட்டீர்களா?”) மக்கள், “அல்லாஹ்வின் தூதரே! தாங்கள் ஏன் சிரித்தீர்கள்?” என்று கேட்டார்கள். அதற்கு அவர்கள் (ஸல்) கூறினார்கள்:\n\r\n\n\r\n«عَجِبْتُ مِنْ مُجَادَلَةِ الْعَبْدِ رَبَّهُ يَوْمَ الْقِيَامَةِ يَقُولُ: أَيْ رَبِّي أَلَيْسَ وَعَدْتَنِي أَنْ لَا تَظْلِمَنِي، قَالَ: بَلَى، فَيَقُولُ: فَإِنِّي لَا أَقْبَلُ عَلَيَّ شَاهِدًا إِلَّا مِنْ نَفْسِي، فَيَقُولُ اللهُ تَبَارَكَ وَتَعَالَى: أَوَلَيْسَ كَفَى بِي شَهِيدًا وَبِالْمَلَائِكَةِ الْكِرَام الْكَاتِبِينَ قال : فَيُرَدِّدُ هذَا الْكَلَامَ مِرَارًا قال : فَيُخْتَمُ عَلى فِيهِ وَتَتَكَلَّمُ أَرْكَانُهُ بِمَا كَانَ يَعْمَلُ، فَيَقُولُ: بُعْدًا لَكُنَّ وَسُحْقًا، عَنْكُنَّ كُنْتُ أُجَادِل»\n\r\n\n\r\n(மறுமை நாளில் ஓர் அடியான் தன் இறைவனிடம் விவாதம் செய்வதைக் கண்டு நான் வியப்படைந்தேன். அவன், “என் இறைவனே! எனக்கு அநீதி இழைக்கப்பட மாட்டாது என்று நீ எனக்கு வாக்குறுதி அளிக்கவில்லையா?” என்று கேட்பான். அல்லாஹ், “ஆம்” என்று கூறுவான். அதற்கு அந்த மனிதன், “எனக்கு எதிராக என்னிடமிருந்தே தவிர வேறு எவரது சாட்சியத்தையும் நான் ஏற்கமாட்டேன்” என்பான். அதற்கு அல்லாஹ், “நானும், கண்ணியமிக்க எழுத்தர்களான வானவர்களும் உனக்குச் சாட்சியாளர்களாக இருப்பது போதாதா?” என்று கேட்பான். இந்த வார்த்தைகள் பலமுறை திரும்பத் திரும்பக் கூறப்படும். பின்னர் அவனது வாய் முத்திரையிடப்படும். அவன் செய்துகொண்டிருந்த செயல்களைப் பற்றி அவனது உடல் உறுப்புகள் பேசும். அப்போது அவன் தன் உறுப்புகளைப் பார்த்து, “உங்களுக்குக் கேடு உண்டாகட்டும்! உங்களுக்காகத்தானே நான் (இறைவனிடம்) வாதிட்டேன்!” என்று கூறுவான்.) இதனை அல்-பஸ்ஸார் மற்றும் இப்னு அபீ ஹாதிம் பதிவு செய்துள்ளனர். மேலும் இமாம் முஸ்லிம் மற்றும் இமாம் அந்-நஸாயீ ஆகியோரும் இதனைப் பதிவு செய்துள்ளனர்.\n\r\n\n\r\nஅபூ மூஸா (ரழி) அவர்கள் கூறியதாக அபூ புர்தா அறிவித்ததை இப்னு அபீ ஹாதிம் பதிவு செய்துள்ளார்: “நிராகரிப்பாளன் அல்லது நயவஞ்சகன் விசாரணைக்காக அழைக்கப்படுவான். அவனது செயல்களை இறைவன் அவனுக்குக் காட்டுவான். ஆனால் அவன் அவற்றை மறுத்து, ‘என் இறைவனே! உன் கண்ணியத்தின் மீது ஆணையாக, நான் செய்யாத ஒன்றை இந்த வானவர் எனக்கு எதிராக எழுதியுள்ளார்’ என்பான். அதற்கு அந்த வானவர், ‘நீ இன்ன நாளில், இன்ன இடத்தில், இன்ன காரியத்தைச் செய்யவில்லையா?’ என்று கேட்பார். அதற்கு அவன், ‘இல்லை, உன் கண்ணியத்தின் மீது ஆணையாக! இறைவனே, நான் அதைச் செய்யவே இல்லை’ என்பான். அவன் இவ்வாறு (பொய்) கூறும்போது அவனது வாய் முத்திரையிடப்படும்.” அல்-அஷ்அரீ (ரழி) அவர்கள் கூறுகிறார்கள்: “அவனது உடலில் முதலாவதாகப் பேசும் உறுப்பு அவனது வலது தொடையாக இருக்கும் என்று நான் நினைக்கிறேன்.”\n\r\n\n\r\nஅல்லாஹ்வின் கூற்று:\n\r\n\n\r\nوَمَا كُنتُمْ تَسْتَتِرُونَ أَن يَشْهَدَ عَلَيْكُمْ سَمْعُكُمْ وَلاَ أَبْصَارُكُمْ وَلاَ جُلُودُكُمْ\n\r\n\n\r\n(உங்கள் காதுகளும், உங்கள் கண்களும், உங்கள் தோல்களும் உங்களுக்கு எதிராகச் சாட்சியளிக்கும் என்பதை (மனதிற்கொண்டு உலகத்தில்) நீங்கள் உங்களை மறைத்துக்கொள்ளவில்லை.) அதாவது, தங்களுக்கு எதிராகச் சாட்சியளித்ததற்காக அவர்கள் தங்கள் உடல் உறுப்புகளைக் குறை கூறும்போது, அந்த உறுப்புகள் அவர்களிடம் கூறும்: 'நீங்கள் செய்தவற்றை எங்களிடமிருந்து மறைக்க முயலவில்லை. மாறாக, நீங்கள் பகிரங்கமாக நிராகரிப்பிலும் பாவத்திலும் ஈடுபட்டீர்கள். அல்லாஹ் உங்கள் செயல்களை அறிந்துகொள்ள மாட்டான் என்று எண்ணியதால் எதைப் பற்றியும் நீங்கள் கவலைப்படவில்லை.' அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَلَـكِن ظَنَنتُمْ أَنَّ اللَّهَ لاَ يَعْلَمُ كَثِيراً مِّمَّا تَعْمَلُونَ وَذَلِكُمْ ظَنُّكُمُ الَّذِى ظَنَنتُم بِرَبِّكُمْ أَرْدَاكُمْ\n\r\n\n\r\n(மாறாக, நீங்கள் செய்துகொண்டிருப்பவற்றில் பெரும்பாலானவற்றை அல்லாஹ் அறியமாட்டான் என்று நீங்கள் எண்ணினீர்கள். உங்கள் இறைவனைப் பற்றி நீங்கள் கொண்டிருந்த அந்த (தவறான) எண்ணம்தான் உங்களை அழிவில் வீழ்த்தியது.) அதாவது, 'அல்லாஹ் உங்கள் செயல்களை அறியமாட்டான் என்ற உங்கள் தீய எண்ணமே நீங்கள் அழிவதற்கும், உங்கள் இறைவனிடம் நஷ்டவாளிகளாக மாறுவதற்கும் காரணமாக அமைந்தது.'\n\r\n\n\r\nفَأَصْبَحْتُمْ مِنَ الْخَاسِرِينَ\n\r\n\n\r\n(இதனால் நீங்கள் நஷ்டமடைந்தோரில் ஆகிவிட்டீர்கள்!) அதாவது, 'மறுமை நாளில் நீங்கள் உங்களையும் உங்கள் குடும்பத்தாரையும் இழந்துவிட்டீர்கள்.'\n\r\n\n\r\nஇமாம் அஹ்மத் பதிவு செய்துள்ளார்கள்: அப்துல்லாஹ் பின் மஸ்ஊத் (ரழி) அவர்கள் கூறுகிறார்கள்: நான் கஅபாவின் திரைக்குப் பின்னால் மறைந்திருந்தேன். அப்போது மூன்று பேர் அங்கு வந்தார்கள். அவர்கள் குறைஷி குலத்தைச் சேர்ந்த ஒருவரும் ஸகீஃப் குலத்தைச் சேர்ந்த அவரது இரண்டு மைத்துனர்களும் ஆவர் (அல்லது ஸகீஃப் குலத்தைச் சேர்ந்த ஒருவரும் குறைஷி குலத்தைச் சேர்ந்த அவரது இரண்டு மைத்துனர்களும்). அவர்கள் பருத்த உடலமைப்பைக் கொண்டிருந்தனர், ஆனால் அவர்களுக்கு மார்க்க ஞானம் குறைவாகவே இருந்தது. அவர்கள் பேசிய சில வார்த்தைகள் என் காதுகளில் விழவில்லை. பிறகு அவர்களில் ஒருவன், 'நாம் இப்போது பேசுவதை அல்லாஹ் கேட்பான் என்று நினைக்கிறாயா?' என்று கேட்டான். அதற்கு மற்றொருவன், 'நாம் உரக்கப் பேசினால் அவன் கேட்பான், மெதுவாகப் பேசினால் கேட்கமாட்டான்' என்றான். அதற்கு மூன்றாமவன், 'அவன் ஒரு விஷயத்தைக் கேட்கிறான் என்றால், எல்லாவற்றையும் கேட்கவே செய்வான்' என்றான். நான் இதனை நபி (ஸல்) அவர்களிடம் தெரிவித்தேன். அப்போது அல்லாஹ் இந்த வசனங்களை வஹீயாக (இறைச்செய்தியாக) அருளினான்:\n\r\n\n\r\nوَمَا كُنتُمْ تَسْتَتِرُونَ أَن يَشْهَدَ عَلَيْكُمْ سَمْعُكُمْ وَلاَ أَبْصَارُكُمْ وَلاَ جُلُودُكُمْ\n\r\n\n\r\n(உங்கள் காதுகளும், உங்கள் கண்களும், உங்கள் தோல்களும் உங்களுக்கு எதிராகச் சாட்சியளிக்கும் என்பதை (மனதிற்கொண்டு உலகத்தில்) நீங்கள் உங்களை மறைத்துக்கொள்ளவில்லை) என்பது முதல்;\n\r\n\n\r\nمِنَ الْخَاسِرِينَ\n\r\n\n\r\n(நஷ்டமடைந்தோரில்!) என்பது வரை. இதனை அத்-திர்மிதி பதிவு செய்துள்ளார். இதே போன்ற ஒரு செய்தி அஹ்மத் (வேறு அறிவிப்பாளர் தொடர் வழியாக), முஸ்லிம், அத்-திர்மிதி மற்றும் புகாரி ஆகியோரால் பதிவு செய்யப்பட்டுள்ளது.\n\r\n\n\r\nفَإِن يَصْبِرُواْ فَالنَّارُ مَثْوًى لَّهُمْ وَإِن يَسْتَعْتِبُواْ فَمَا هُم مِّنَ الْمُعْتَبِينَ\n\r\n\n\r\n(எனவே அவர்கள் பொறுமையாக இருந்தாலும் நரகமே அவர்களுக்குத் தங்குமிடமாகும். அவர்கள் (அல்லாஹ்வின்) மன்னிப்பைக் கோரினாலும் அவர்கள் மன்னிக்கப்பட மாட்டார்கள்.) அதாவது, அவர்கள் பொறுமையாக இருந்தாலும் இல்லாவிட்டாலும் அவர்கள் நரகத்தில்தான் இருப்பார்கள். அதிலிருந்து தப்பிக்க அவர்களுக்கு வழியே இல்லை. அவர்கள் சாக்குப்போக்குகளைக் கூறி அல்லாஹ்வைத் திருப்திப்படுத்த முயன்றாலும், அவை ஏற்றுக்கொள்ளப்பட மாட்டாது. இப்னு ஜரீர் அவர்கள் கூறுகிறார்கள்: '(அவர்கள் மன்னிப்பைக் கோரினாலும்) என்பதன் பொருள், அவர்கள் மீண்டும் உலகிற்குத் திரும்பிச் செல்ல அனுமதி கேட்பார்கள்; ஆனால் அவர்களின் கோரிக்கை நிராகரிக்கப்படும். இது பின்வரும் வசனத்தைப் போன்றது:'\n\r\n\n\r\nقَالُواْ رَبَّنَا غَلَبَتْ عَلَيْنَا شِقْوَتُنَا وَكُنَّا قَوْماً ضَآلِّينَ - رَبَّنَآ أَخْرِجْنَا مِنْهَا فَإِنْ عُدْنَا فَإِنَّا ظَـلِمُونَ - قَالَ اخْسَئُواْ فِيهَا وَلاَ تُكَلِّمُونِ\n\r\n\n\r\n(அவர்கள் கூறுவார்கள்: 'எங்கள் இறைவனே! எங்களது துரதிர்ஷ்டம் எங்களை மிகைத்துவிட்டது. நாங்கள் வழிதவறிய சமூகமாக இருந்தோம். எங்கள் இறைவனே! எங்களை இதிலிருந்து வெளியேற்றுவாயாக! நாங்கள் மீண்டும் (தீமைக்குத்) திரும்பினால் நிச்சயமாக நாங்கள் அநியாயக்காரர்களாகிவிடுவோம்.' அதற்கு அவன் கூறுவான்: 'இழிவடைந்த நிலையில் இதிலேயே தங்கியிருங்கள்! என்னிடம் பேசாதீர்கள்!') (23:106-108)."},"25":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=41&ayah=29\" class=\"link\">41:29</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 41:29 ஐ பார்க்கவும்"},"26":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=41&ayah=29\" class=\"link\">41:29</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 41:29 ஐ பார்க்கவும்"},"27":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=41&ayah=29\" class=\"link\">41:29</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 41:29 ஐ பார்க்கவும்"},"28":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=41&ayah=29\" class=\"link\">41:29</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 41:29 ஐ பார்க்கவும்"},"29":{"html":"<strong>இணைவைப்பாளர்களின் நெருங்கிய கூட்டாளிகள் அவர்களுக்குத் தீய செயல்களை அழகாக்கிக் காட்டுகின்றனர்</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَقَيَّضْنَا</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">قُرَنَآءَ</span><br />\r\n<br />\r\n(மேலும், நாம் அவர்களுக்கு (ஷைத்தான்களிலிருந்து) கூட்டாளிகளை நியமித்தோம்.)<br />\r\n<br />\r\nஇணைவைப்பாளர்களை வழிகெடுப்பவன் அல்லாஹ்வே என்றும், இது அவனது நாட்டப்படியும் விதியின்படியுமே நடக்கிறது என்றும் அல்லாஹ் கூறுகிறான். மனிதர்கள் மற்றும் ஜின்களிலுள்ள ஷைத்தான்களை அவர்களுக்கு நெருங்கிய கூட்டாளிகளாக அவன் நியமிக்கும்போது, அவன் தனது செயல்களில் மகா ஞானவானாக இருக்கிறான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَزَيَّنُواْ</span> <span class=\"quran-arabic-font text-success\">لَهُم</span> <span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">بَيْنَ</span> <span class=\"quran-arabic-font text-success\">أَيْدِيهِمْ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">خَلْفَهُمْ</span><br />\r\n<br />\r\n(அவர்களுக்கு முன்னிருப்பதையும் அவர்களுக்குப் பின்னிருப்பதையும் அவர்களுக்கு அவர்கள் அழகாக்கிக் காட்டினர்.) அதாவது, கடந்த காலத்தில் அவர்கள் செய்த செயல்களை அவர்களுக்குக் கவர்ச்சிகரமானதாக அவர்கள் காட்டினார்கள். எதிர்காலத்தைப் பொறுத்தவரை, தாங்கள் நன்மையையே செய்வதாக அவர்கள் கருதுகிறார்கள். அல்லாஹ் கூறுவது போல்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">يَعْشُ</span> <span class=\"quran-arabic-font text-success\">عَن</span> <span class=\"quran-arabic-font text-success\">ذِكْرِ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَـنِ</span> <span class=\"quran-arabic-font text-success\">نُقَيِّضْ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">شَيْطَاناً</span> <span class=\"quran-arabic-font text-success\">فَهُوَ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">قَرِينٌ</span> - <span class=\"quran-arabic-font text-success\">وَإِنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">لَيَصُدُّونَهُمْ</span> <span class=\"quran-arabic-font text-success\">عَنِ</span> <span class=\"quran-arabic-font text-success\">السَّبِيلِ</span> <span class=\"quran-arabic-font text-success\">وَيَحْسَبُونَ</span> <span class=\"quran-arabic-font text-success\">أَنَّهُم</span> <span class=\"quran-arabic-font text-success\">مُّهْتَدُونَ</span><br />\r\n<br />\r\n(அளவற்ற அருளாளனின் நினைவை விட்டும் எவர் புறக்கணிக்கிறாரோ, அவருக்கு நாம் ஒரு ஷைத்தானைத் தோழனாக நியமிக்கிறோம். நிச்சயமாக, அவர்கள் அவர்களை நேர்வழியிலிருந்து தடுக்கிறார்கள்; ஆனால் தாங்கள் நேர்வழியில் இருப்பதாகவே அவர்கள் எண்ணுகிறார்கள்!) (<a href=\"qurandisp.php?sura=43&ayah=36\" class=\"link\">43:36</a>-37)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَحَقَّ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمُ</span> <span class=\"quran-arabic-font text-success\">الْقَوْلُ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">أُمَمٍ</span> <span class=\"quran-arabic-font text-success\">قَدْ</span> <span class=\"quran-arabic-font text-success\">خَلَتْ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَبْلِهِم</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">الْجِنِّ</span> <span class=\"quran-arabic-font text-success\">وَالإِنسِ</span><br />\r\n<br />\r\n(அவர்களுக்கு எதிராக வாக்கு உண்மையானது ; ஜின்களிலும் மனிதர்களிலும் அவர்களுக்கு முன் சென்று போன சமூகத்தாருடன் (இவர்களும் சேர்ந்துகொண்டனர்).) இதன் பொருள் வேதனையின் வாக்கு என்பதாகும். தங்களைப் போலவே செயல்பட்ட கடந்த கால மனித மற்றும் ஜின் சமூகங்களுக்கு எதிராக அது உண்மையானது போன்றதே இதுவும் ஆகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">خَـسِرِينَ</span><br />\r\n<br />\r\n(நிச்சயமாக அவர்கள் (அனைவரும்) நஷ்டமடைந்தவர்களாக இருந்தனர்.) அதாவது, அவர்கள் அனைவரும் நஷ்டத்திலும் அழிவிலும் சமமானவர்கள்.<br />\r\n<br />\r\n<strong>குர்ஆனைச் செவிமடுக்க வேண்டாம் என்று நிராகரிப்பாளர்கள் ஒருவருக்கொருவர் அறிவுறுத்தியதும், அதற்கான தண்டனையும்</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَقَالَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُواْ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">تَسْمَعُواْ</span> <span class=\"quran-arabic-font text-success\">لِهَـذَا</span> <span class=\"quran-arabic-font text-success\">الْقُرْءَانِ</span><br />\r\n<br />\r\n(நிராகரிப்பாளர்கள் கூறுகிறார்கள்: \"இந்த குர்ஆனைச் செவிமடுக்காதீர்கள்...\") அதாவது, குர்ஆனைக் கவனிக்க வேண்டாம் என்றும் அதன் கட்டளைகளுக்குக் கீழ்ப்படிய வேண்டாம் என்றும் அவர்கள் ஒருவருக்கொருவர் அறிவுறுத்திக்கொண்டார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالْغَوْاْ</span> <span class=\"quran-arabic-font text-success\">فِيهِ</span><br />\r\n<br />\r\n(அதன் மத்தியில் கூச்சலிடுங்கள்) இதன் பொருள், குர்ஆன் ஓதப்படும்போது அதைக் கேட்காதீர்கள் என்பதாகும். இது முஜாஹித் அவர்களின் கருத்தாகும். \"அதன் (ஓதுதலின்) போது கூச்சலிடுங்கள்\" என்பது, அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் குர்ஆன் ஓதும்போது, அவர்களைக் குழப்புவதற்காக விசில் அடிப்பதையும் சத்தம் போடுவதையும் குறிக்கும்; இதையே குறைஷிகள் செய்து வந்தனர்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَعَلَّكُمْ</span> <span class=\"quran-arabic-font text-success\">تَغْلِبُونَ</span><br />\r\n<br />\r\n(அதன் மூலம் நீங்கள் வெற்றி பெறலாம்.) இதன் பொருள், இந்த அறியாமையிலுள்ள நிராகரிப்பாளர்களும் அவர்களைப் பின்பற்றுபவர்களும் குர்ஆனைக் கேட்கும்போது கடைபிடிக்கும் வழக்கம் இதுவாகும். அல்லாஹ் இதிலிருந்து மாறுபட்டு இருக்குமாறு நமக்குக் கட்டளையிட்டு இவ்வாறு கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِذَا</span> <span class=\"quran-arabic-font text-success\">قُرِىءَ</span> <span class=\"quran-arabic-font text-success\">الْقُرْءَانُ</span> <span class=\"quran-arabic-font text-success\">فَاسْتَمِعُواْ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">وَأَنصِتُواْ</span> <span class=\"quran-arabic-font text-success\">لَعَلَّكُمْ</span> <span class=\"quran-arabic-font text-success\">تُرْحَمُونَ</span><br />\r\n<br />\r\n(குர்ஆன் ஓதப்பட்டால், அதனைச் செவிமடுங்கள்; இன்னும் மௌனமாக இருங்கள்; அதன் மூலம் நீங்கள் கிருபை செய்யப்படுவீர்கள்.) (<a href=\"qurandisp.php?sura=7&ayah=204\" class=\"link\">7:204</a>). பின்னர் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَلَنُذِيقَنَّ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُواْ</span> <span class=\"quran-arabic-font text-success\">عَذَاباً</span> <span class=\"quran-arabic-font text-success\">شَدِيداً</span><br />\r\n<br />\r\n(ஆனால் நிச்சயமாக, நிராகரித்தவர்களைக் கடுமையான வேதனையைச் சுவைக்கச் செய்வோம்.) அதாவது, அவர்கள் குர்ஆனைக் கேட்கும்போது செய்த செயல்களுக்குப் பகரமாக.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَنَجْزِيَنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">أَسْوَأَ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">يَعْمَلُونَ</span><br />\r\n<br />\r\n(நிச்சயமாக, அவர்கள் செய்துகொண்டிருந்தவற்றில் மிக மோசமானவற்றிற்கு நாம் அவர்களுக்குக் கூலி கொடுப்போம்.) அதாவது, அவர்களின் தீய செயல்களுக்காக.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">جَزَآءُ</span> <span class=\"quran-arabic-font text-success\">أَعْدَآءِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">النَّارُ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">دَارُ</span> <span class=\"quran-arabic-font text-success\">الخُلْدِ</span> <span class=\"quran-arabic-font text-success\">جَزَآءً</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">كَانُوا</span> <span class=\"quran-arabic-font text-success\">بِآيَاتِنَا</span> <span class=\"quran-arabic-font text-success\">يَجْحَدُون</span> - <span class=\"quran-arabic-font text-success\">وَقَالَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُواْ</span> <span class=\"quran-arabic-font text-success\">رَبَّنَآ</span> <span class=\"quran-arabic-font text-success\">أَرِنَا</span> <span class=\"quran-arabic-font text-success\">اللَّذَيْنِ</span> <span class=\"quran-arabic-font text-success\">أَضَلَّانَا</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْجِنِّ</span> <span class=\"quran-arabic-font text-success\">وَالإِنسِ</span> <span class=\"quran-arabic-font text-success\">نَجْعَلْهُمَا</span> <span class=\"quran-arabic-font text-success\">تَحْتَ</span> <span class=\"quran-arabic-font text-success\">أَقْدَامِنَا</span> <span class=\"quran-arabic-font text-success\">لِيَكُونَا</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الاٌّسْفَلِينَ</span><br />\r\n<br />\r\n(அதுதான் அல்லாஹ்வின் எதிரிகளுக்குரிய கூலியாகும்; அதுதான் நரகம். அதில் அவர்களுக்கு நிரந்தரமான இல்லம் உண்டு. இது அவர்கள் நமது வசனங்களை மறுத்துக் கொண்டிருந்ததற்கான கூலியாகும். மேலும், நிராகரித்தவர்கள் கூறுவார்கள்: \"எங்கள் இறைவா! ஜின்களிலும் மனிதர்களிலும் எங்களை வழிதவறச் செய்த இருவரையும் எங்களுக்குக் காட்டுவாயாக; அவர்கள் மிகவும் தாழ்ந்தவர்களாக ஆவதற்காக, அவர்களை நாங்கள் எங்கள் கால்களுக்குக் கீழே ஆக்கிக் கொள்கிறோம்.\") பின்வரும் சொற்றொடரைப் பற்றி அலி (ரழி) அவர்கள் கூறியதாக அறிவிக்கப்பட்டுள்ளது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">اللَّذَيْنِ</span> <span class=\"quran-arabic-font text-success\">أَضَلَّانَا</span><br />\r\n<br />\r\n(எங்களை வழிதவறச் செய்த அந்த இருவர்): \"அவர்கள் இப்லீஸும், தனது சகோதரனைக் கொன்ற ஆதமின் மகனும் ஆவர்.\" அலி (ரழி) அவர்கள் கூறியதாக அஸ்-ஸுத்தி அறிவிக்கிறார்: \"ஷிர்க் (இணைவைப்பு) செய்யும் ஒவ்வொருவரும் இப்லீஸைப் பின்பற்றுகிறார்கள். பெரும் பாவம் செய்யும் ஒவ்வொருவரும் ஆதமின் மகனைப் பின்பற்றுகிறார்கள். எனவே, ஷிர்க் மற்றும் சிறிய பாவங்கள் போன்ற அனைத்துத் தீய காரியங்களுக்கும் இப்லீஸ் மக்களை அழைக்கிறான்.\" ஆதமின் முதல் மகனைப் பொறுத்தவரை, ஹதீஸில் உறுதிப்படுத்தப்பட்டுள்ளவாறு:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">قُتِلَتْ</span> <span class=\"quran-arabic-font text-success\">نَفْسٌ</span> <span class=\"quran-arabic-font text-success\">ظُلْمًا</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">ابْنِ</span> <span class=\"quran-arabic-font text-success\">آدَمَ</span> <span class=\"quran-arabic-font text-success\">الْأَوَّلِ</span> <span class=\"quran-arabic-font text-success\">كِفْلٌ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">دَمِهَا،لِأَنَّهُ</span> <span class=\"quran-arabic-font text-success\">أَوَّلُ</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">سَنَّ</span> <span class=\"quran-arabic-font text-success\">الْقَتْل</span>»<br />\r\n<br />\r\n(அநியாயமாக எந்தவொரு உயிர் கொல்லப்பட்டாலும், அதன் இரத்தப் பழியில் ஒரு பங்கு ஆதமின் முதல் மகனுக்கும் உண்டு. ஏனெனில் அவர்தான் கொலை செய்யும் முறையை முதன்முதலில் ஏற்படுத்தியவர் ஆவார்.)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">نَجْعَلْهُمَا</span> <span class=\"quran-arabic-font text-success\">تَحْتَ</span> <span class=\"quran-arabic-font text-success\">أَقْدَامِنَا</span><br />\r\n<br />\r\n(அவர்களை எங்கள் கால்களுக்குக் கீழே ஆக்கிக் கொள்கிறோம்) இதன் பொருள், 'வேதனையில் அவர்களை எங்களுக்குக் கீழே ஆக்குவாயாக; அப்போது அவர்கள் எங்களை விடக் கடுமையாகத் தண்டிக்கப்படுவார்கள்' என்பதாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لِيَكُونَا</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الاٌّسْفَلِينَ</span><br />\r\n<br />\r\n(அதன் மூலம் அவர்கள் மிகவும் தாழ்ந்தவர்களாக ஆவார்கள்.) இதன் பொருள் நரகத்தின் மிகக் கீழ் மட்டத்தில் இருப்பார்கள் என்பதாகும். இது குறித்து அல்-அஃராஃப் அத்தியாயத்தில் ஏற்கனவே குறிப்பிடப்பட்டுள்ளது; அங்கே பின்பற்றுபவர்கள் தங்கள் தலைவர்களுக்கான வேதனையை இரட்டிப்பாக்குமாறு அல்லாஹ்விடம் கேட்பார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">لِكُلٍّ</span> <span class=\"quran-arabic-font text-success\">ضِعْفٌ</span> <span class=\"quran-arabic-font text-success\">وَلَـكِن</span> <span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">تَعْلَمُونَ</span><br />\r\n<br />\r\n((அல்லாஹ்) கூறினான்: \"ஒவ்வொருவருக்கும் இரட்டிப்பு (வேதனை) உண்டு; ஆனால் நீங்கள் அறிய மாட்டீர்கள்.\") (<a href=\"qurandisp.php?sura=7&ayah=38\" class=\"link\">7:38</a>) அதாவது, அல்லாஹ் அவர்கள் ஒவ்வொருவருக்கும் அவர்களின் செயல்களுக்குத் தகுதியான வேதனையையும் தண்டனையையும் வழங்குவான். இது பின்வரும் வசனத்தைப் போன்றதாகும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُواْ</span> <span class=\"quran-arabic-font text-success\">وَصَدُّواْ</span> <span class=\"quran-arabic-font text-success\">عَن</span> <span class=\"quran-arabic-font text-success\">سَبِيلِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">زِدْنَـهُمْ</span> <span class=\"quran-arabic-font text-success\">عَذَابًا</span> <span class=\"quran-arabic-font text-success\">فَوْقَ</span> <span class=\"quran-arabic-font text-success\">الْعَذَابِ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">يُفْسِدُونَ</span><br />\r\n<br />\r\n(நிராகரித்து, அல்லாஹ்வின் பாதையிலிருந்து (மக்களைத்) தடுத்தவர்களுக்கு, அவர்கள் குழப்பம் விளைவித்துக் கொண்டிருந்த காரணத்தால், வேதனைக்கு மேல் வேதனையை நாம் அவர்களுக்கு அதிகப்படுத்துவோம்.) (<a href=\"qurandisp.php?sura=16&ayah=88\" class=\"link\">16:88</a>).<br />\r\n<br />","text":"இணைவைப்பாளர்களின் நெருங்கிய கூட்டாளிகள் அவர்களுக்குத் தீய செயல்களை அழகாக்கிக் காட்டுகின்றனர்\n\r\n\n\r\nوَقَيَّضْنَا لَهُمْ قُرَنَآءَ\n\r\n\n\r\n(மேலும், நாம் அவர்களுக்கு (ஷைத்தான்களிலிருந்து) கூட்டாளிகளை நியமித்தோம்.)\n\r\n\n\r\nஇணைவைப்பாளர்களை வழிகெடுப்பவன் அல்லாஹ்வே என்றும், இது அவனது நாட்டப்படியும் விதியின்படியுமே நடக்கிறது என்றும் அல்லாஹ் கூறுகிறான். மனிதர்கள் மற்றும் ஜின்களிலுள்ள ஷைத்தான்களை அவர்களுக்கு நெருங்கிய கூட்டாளிகளாக அவன் நியமிக்கும்போது, அவன் தனது செயல்களில் மகா ஞானவானாக இருக்கிறான்.\n\r\n\n\r\nفَزَيَّنُواْ لَهُم مَّا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ\n\r\n\n\r\n(அவர்களுக்கு முன்னிருப்பதையும் அவர்களுக்குப் பின்னிருப்பதையும் அவர்களுக்கு அவர்கள் அழகாக்கிக் காட்டினர்.) அதாவது, கடந்த காலத்தில் அவர்கள் செய்த செயல்களை அவர்களுக்குக் கவர்ச்சிகரமானதாக அவர்கள் காட்டினார்கள். எதிர்காலத்தைப் பொறுத்தவரை, தாங்கள் நன்மையையே செய்வதாக அவர்கள் கருதுகிறார்கள். அல்லாஹ் கூறுவது போல்:\n\r\n\n\r\nوَمَن يَعْشُ عَن ذِكْرِ الرَّحْمَـنِ نُقَيِّضْ لَهُ شَيْطَاناً فَهُوَ لَهُ قَرِينٌ - وَإِنَّهُمْ لَيَصُدُّونَهُمْ عَنِ السَّبِيلِ وَيَحْسَبُونَ أَنَّهُم مُّهْتَدُونَ\n\r\n\n\r\n(அளவற்ற அருளாளனின் நினைவை விட்டும் எவர் புறக்கணிக்கிறாரோ, அவருக்கு நாம் ஒரு ஷைத்தானைத் தோழனாக நியமிக்கிறோம். நிச்சயமாக, அவர்கள் அவர்களை நேர்வழியிலிருந்து தடுக்கிறார்கள்; ஆனால் தாங்கள் நேர்வழியில் இருப்பதாகவே அவர்கள் எண்ணுகிறார்கள்!) (43:36-37)\n\r\n\n\r\nوَحَقَّ عَلَيْهِمُ الْقَوْلُ فِى أُمَمٍ قَدْ خَلَتْ مِن قَبْلِهِم مِّنَ الْجِنِّ وَالإِنسِ\n\r\n\n\r\n(அவர்களுக்கு எதிராக வாக்கு உண்மையானது ; ஜின்களிலும் மனிதர்களிலும் அவர்களுக்கு முன் சென்று போன சமூகத்தாருடன் (இவர்களும் சேர்ந்துகொண்டனர்).) இதன் பொருள் வேதனையின் வாக்கு என்பதாகும். தங்களைப் போலவே செயல்பட்ட கடந்த கால மனித மற்றும் ஜின் சமூகங்களுக்கு எதிராக அது உண்மையானது போன்றதே இதுவும் ஆகும்.\n\r\n\n\r\nإِنَّهُمْ كَانُواْ خَـسِرِينَ\n\r\n\n\r\n(நிச்சயமாக அவர்கள் (அனைவரும்) நஷ்டமடைந்தவர்களாக இருந்தனர்.) அதாவது, அவர்கள் அனைவரும் நஷ்டத்திலும் அழிவிலும் சமமானவர்கள்.\n\r\n\n\r\nகுர்ஆனைச் செவிமடுக்க வேண்டாம் என்று நிராகரிப்பாளர்கள் ஒருவருக்கொருவர் அறிவுறுத்தியதும், அதற்கான தண்டனையும்\n\r\n\n\r\nوَقَالَ الَّذِينَ كَفَرُواْ لاَ تَسْمَعُواْ لِهَـذَا الْقُرْءَانِ\n\r\n\n\r\n(நிராகரிப்பாளர்கள் கூறுகிறார்கள்: \"இந்த குர்ஆனைச் செவிமடுக்காதீர்கள்...\") அதாவது, குர்ஆனைக் கவனிக்க வேண்டாம் என்றும் அதன் கட்டளைகளுக்குக் கீழ்ப்படிய வேண்டாம் என்றும் அவர்கள் ஒருவருக்கொருவர் அறிவுறுத்திக்கொண்டார்கள்.\n\r\n\n\r\nوَالْغَوْاْ فِيهِ\n\r\n\n\r\n(அதன் மத்தியில் கூச்சலிடுங்கள்) இதன் பொருள், குர்ஆன் ஓதப்படும்போது அதைக் கேட்காதீர்கள் என்பதாகும். இது முஜாஹித் அவர்களின் கருத்தாகும். \"அதன் (ஓதுதலின்) போது கூச்சலிடுங்கள்\" என்பது, அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் குர்ஆன் ஓதும்போது, அவர்களைக் குழப்புவதற்காக விசில் அடிப்பதையும் சத்தம் போடுவதையும் குறிக்கும்; இதையே குறைஷிகள் செய்து வந்தனர்.\n\r\n\n\r\nلَعَلَّكُمْ تَغْلِبُونَ\n\r\n\n\r\n(அதன் மூலம் நீங்கள் வெற்றி பெறலாம்.) இதன் பொருள், இந்த அறியாமையிலுள்ள நிராகரிப்பாளர்களும் அவர்களைப் பின்பற்றுபவர்களும் குர்ஆனைக் கேட்கும்போது கடைபிடிக்கும் வழக்கம் இதுவாகும். அல்லாஹ் இதிலிருந்து மாறுபட்டு இருக்குமாறு நமக்குக் கட்டளையிட்டு இவ்வாறு கூறுகிறான்:\n\r\n\n\r\nوَإِذَا قُرِىءَ الْقُرْءَانُ فَاسْتَمِعُواْ لَهُ وَأَنصِتُواْ لَعَلَّكُمْ تُرْحَمُونَ\n\r\n\n\r\n(குர்ஆன் ஓதப்பட்டால், அதனைச் செவிமடுங்கள்; இன்னும் மௌனமாக இருங்கள்; அதன் மூலம் நீங்கள் கிருபை செய்யப்படுவீர்கள்.) (7:204). பின்னர் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nفَلَنُذِيقَنَّ الَّذِينَ كَفَرُواْ عَذَاباً شَدِيداً\n\r\n\n\r\n(ஆனால் நிச்சயமாக, நிராகரித்தவர்களைக் கடுமையான வேதனையைச் சுவைக்கச் செய்வோம்.) அதாவது, அவர்கள் குர்ஆனைக் கேட்கும்போது செய்த செயல்களுக்குப் பகரமாக.\n\r\n\n\r\nوَلَنَجْزِيَنَّهُمْ أَسْوَأَ الَّذِى كَانُواْ يَعْمَلُونَ\n\r\n\n\r\n(நிச்சயமாக, அவர்கள் செய்துகொண்டிருந்தவற்றில் மிக மோசமானவற்றிற்கு நாம் அவர்களுக்குக் கூலி கொடுப்போம்.) அதாவது, அவர்களின் தீய செயல்களுக்காக.\n\r\n\n\r\nذَلِكَ جَزَآءُ أَعْدَآءِ اللَّهِ النَّارُ لَهُمْ فِيهَا دَارُ الخُلْدِ جَزَآءً بِمَا كَانُوا بِآيَاتِنَا يَجْحَدُون - وَقَالَ الَّذِينَ كَفَرُواْ رَبَّنَآ أَرِنَا اللَّذَيْنِ أَضَلَّانَا مِنَ الْجِنِّ وَالإِنسِ نَجْعَلْهُمَا تَحْتَ أَقْدَامِنَا لِيَكُونَا مِنَ الاٌّسْفَلِينَ\n\r\n\n\r\n(அதுதான் அல்லாஹ்வின் எதிரிகளுக்குரிய கூலியாகும்; அதுதான் நரகம். அதில் அவர்களுக்கு நிரந்தரமான இல்லம் உண்டு. இது அவர்கள் நமது வசனங்களை மறுத்துக் கொண்டிருந்ததற்கான கூலியாகும். மேலும், நிராகரித்தவர்கள் கூறுவார்கள்: \"எங்கள் இறைவா! ஜின்களிலும் மனிதர்களிலும் எங்களை வழிதவறச் செய்த இருவரையும் எங்களுக்குக் காட்டுவாயாக; அவர்கள் மிகவும் தாழ்ந்தவர்களாக ஆவதற்காக, அவர்களை நாங்கள் எங்கள் கால்களுக்குக் கீழே ஆக்கிக் கொள்கிறோம்.\") பின்வரும் சொற்றொடரைப் பற்றி அலி (ரழி) அவர்கள் கூறியதாக அறிவிக்கப்பட்டுள்ளது:\n\r\n\n\r\nاللَّذَيْنِ أَضَلَّانَا\n\r\n\n\r\n(எங்களை வழிதவறச் செய்த அந்த இருவர்): \"அவர்கள் இப்லீஸும், தனது சகோதரனைக் கொன்ற ஆதமின் மகனும் ஆவர்.\" அலி (ரழி) அவர்கள் கூறியதாக அஸ்-ஸுத்தி அறிவிக்கிறார்: \"ஷிர்க் (இணைவைப்பு) செய்யும் ஒவ்வொருவரும் இப்லீஸைப் பின்பற்றுகிறார்கள். பெரும் பாவம் செய்யும் ஒவ்வொருவரும் ஆதமின் மகனைப் பின்பற்றுகிறார்கள். எனவே, ஷிர்க் மற்றும் சிறிய பாவங்கள் போன்ற அனைத்துத் தீய காரியங்களுக்கும் இப்லீஸ் மக்களை அழைக்கிறான்.\" ஆதமின் முதல் மகனைப் பொறுத்தவரை, ஹதீஸில் உறுதிப்படுத்தப்பட்டுள்ளவாறு:\n\r\n\n\r\n«مَا قُتِلَتْ نَفْسٌ ظُلْمًا إِلَّا كَانَ عَلَى ابْنِ آدَمَ الْأَوَّلِ كِفْلٌ مِنْ دَمِهَا،لِأَنَّهُ أَوَّلُ مَنْ سَنَّ الْقَتْل»\n\r\n\n\r\n(அநியாயமாக எந்தவொரு உயிர் கொல்லப்பட்டாலும், அதன் இரத்தப் பழியில் ஒரு பங்கு ஆதமின் முதல் மகனுக்கும் உண்டு. ஏனெனில் அவர்தான் கொலை செய்யும் முறையை முதன்முதலில் ஏற்படுத்தியவர் ஆவார்.)\n\r\n\n\r\nنَجْعَلْهُمَا تَحْتَ أَقْدَامِنَا\n\r\n\n\r\n(அவர்களை எங்கள் கால்களுக்குக் கீழே ஆக்கிக் கொள்கிறோம்) இதன் பொருள், 'வேதனையில் அவர்களை எங்களுக்குக் கீழே ஆக்குவாயாக; அப்போது அவர்கள் எங்களை விடக் கடுமையாகத் தண்டிக்கப்படுவார்கள்' என்பதாகும்.\n\r\n\n\r\nلِيَكُونَا مِنَ الاٌّسْفَلِينَ\n\r\n\n\r\n(அதன் மூலம் அவர்கள் மிகவும் தாழ்ந்தவர்களாக ஆவார்கள்.) இதன் பொருள் நரகத்தின் மிகக் கீழ் மட்டத்தில் இருப்பார்கள் என்பதாகும். இது குறித்து அல்-அஃராஃப் அத்தியாயத்தில் ஏற்கனவே குறிப்பிடப்பட்டுள்ளது; அங்கே பின்பற்றுபவர்கள் தங்கள் தலைவர்களுக்கான வேதனையை இரட்டிப்பாக்குமாறு அல்லாஹ்விடம் கேட்பார்கள்:\n\r\n\n\r\nقَالَ لِكُلٍّ ضِعْفٌ وَلَـكِن لاَّ تَعْلَمُونَ\n\r\n\n\r\n((அல்லாஹ்) கூறினான்: \"ஒவ்வொருவருக்கும் இரட்டிப்பு (வேதனை) உண்டு; ஆனால் நீங்கள் அறிய மாட்டீர்கள்.\") (7:38) அதாவது, அல்லாஹ் அவர்கள் ஒவ்வொருவருக்கும் அவர்களின் செயல்களுக்குத் தகுதியான வேதனையையும் தண்டனையையும் வழங்குவான். இது பின்வரும் வசனத்தைப் போன்றதாகும்:\n\r\n\n\r\nالَّذِينَ كَفَرُواْ وَصَدُّواْ عَن سَبِيلِ اللَّهِ زِدْنَـهُمْ عَذَابًا فَوْقَ الْعَذَابِ بِمَا كَانُواْ يُفْسِدُونَ\n\r\n\n\r\n(நிராகரித்து, அல்லாஹ்வின் பாதையிலிருந்து (மக்களைத்) தடுத்தவர்களுக்கு, அவர்கள் குழப்பம் விளைவித்துக் கொண்டிருந்த காரணத்தால், வேதனைக்கு மேல் வேதனையை நாம் அவர்களுக்கு அதிகப்படுத்துவோம்.) (16:88)."},"30":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=41&ayah=32\" class=\"link\">41:32</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 41:32 ஐ பார்க்கவும்"},"31":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=41&ayah=32\" class=\"link\">41:32</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 41:32 ஐ பார்க்கவும்"},"32":{"html":"<strong>அல்லாஹ்வை மட்டும் நம்பி, (நேர்வழியில்) உறுதியாக இருப்பவர்களுக்கு நற்செய்தி</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">رَبُّنَا</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">اسْتَقَـمُواْ</span><br />\r\n(நிச்சயமாக, எவர்கள் \"எங்கள் இறைவன் அல்லாஹ்தான்\" என்று கூறி, பின்னர் (அதில்) உறுதியாக நிலைத்திருக்கிறார்களோ,) இதன் பொருள், அவர்கள் நற்செயல்களை அல்லாஹ்வின் திருப்திக்காகத் தூய எண்ணத்துடன் செய்கிறார்கள்; மேலும் அல்லாஹ் தங்களுக்குக் கடமையாக்கியவற்றைச் செய்து அவனுக்குக் கீழ்ப்படிகிறார்கள் என்பதாகும். ஸயீத் பின் இம்ரான் (ரஹ்) கூறினார்கள்: \"நான் இந்த வசனத்தை அபூபக்ர் அஸ்-ஸித்தீக் (ரழி) அவர்களிடம் ஓதிக் காட்டினேன்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">رَبُّنَا</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">اسْتَقَـمُواْ</span><br />\r\n(நிச்சயமாக, எவர்கள் \"எங்கள் இறைவன் அல்லாஹ்தான்\" என்று கூறி, பின்னர் (அதில்) உறுதியாக நிலைத்திருக்கிறார்களோ,) அதற்கு அவர்கள், 'இவர்கள் அல்லாஹ்வுக்கு எதையும் இணையாக்காதவர்கள்' என்று கூறினார்கள்.\" பின்னர் அவர் அல்-அஸ்வத் பின் ஹிலால் அவர்களின் அறிவிப்பைக் குறிப்பிடுகிறார். அதில் அபூபக்ர் அஸ்-ஸித்தீக் (ரழி) அவர்கள், \"இந்த வசனத்தைப் பற்றி நீங்கள் என்ன கருதுகிறீர்கள்?\" என்று கேட்டார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">رَبُّنَا</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">اسْتَقَـمُواْ</span><br />\r\n(நிச்சயமாக, எவர்கள் \"எங்கள் இறைவன் அல்லாஹ்தான்\" என்று கூறி, பின்னர் (அதில்) உறுதியாக நிலைத்திருக்கிறார்களோ,)\" அவர்கள் பதிலளித்தார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">رَبُّنَا</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">اسْتَقَـمُواْ</span><br />\r\n(\"எங்கள் இறைவன் அல்லாஹ்தான்,\" பின்னர் அவர்கள் உறுதியாக நிற்கிறார்கள்,) 'அவர்கள் பாவங்களைத் தவிர்க்கிறார்கள்.' அதற்கு அபூபக்ர் (ரழி) அவர்கள், ' நீங்கள் இதை (முறையாக) விளங்கிக் கொள்ளவில்லை. இவர்கள் 'எங்கள் இறைவன் அல்லாஹ்தான்' என்று கூறி, பின்னர் அதில் உறுதியாக நிலைத்திருந்து, அவனைத் தவிர வேறு எவரையும் வணங்காமல் இருப்பவர்களையே இது குறிக்கிறது' என்று கூறினார்கள்.\" இதுவே முஜாஹித், இக்ரிமா, அஸ்-ஸுத்தீ மற்றும் பிறரின் கருத்தாகவும் இருந்தது.<br />\r\n<br />\r\nஉமர் (ரழி) அவர்கள் மிம்பரின் மீதிருந்தவாறு இந்த வசனத்தை ஓதி, \"அல்லாஹ்வின் மீது ஆணையாக! அவர்கள் அல்லாஹ்வுக்குக் கீழ்ப்படிவதில் உறுதியாக இருந்தார்கள்; நரிகள் தந்திரம் செய்வது போன்று அவர்கள் தந்திரம் செய்யவில்லை\" என்று கூறினார்கள்.<br />\r\n<br />\r\nஸுஃப்யான் பின் அப்துல்லாஹ் அஸ்-ஸகஃபீ (ரழி) அவர்கள் கூறினார்கள்: \"நான், 'அல்லாஹ்வின் தூதரே, நான் பற்றிப் பிடித்துக் கொள்ள வேண்டிய ஒரு விஷயத்தை எனக்குச் சொல்லுங்கள்' என்று கேட்டேன். அதற்கு அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">قُلْ</span>: <span class=\"quran-arabic-font text-success\">رَبِّيَ</span> <span class=\"quran-arabic-font text-success\">اللهُ،</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">اسْتَقِم</span>»<br />\r\n(எனது இறைவன் அல்லாஹ்தான் என்று கூறி, பின்னர் உறுதியாக நிலைத்திருப்பீராக!) நான், 'அல்லாஹ்வின் தூதரே, எனக்காக நீங்கள் மிகவும் அஞ்சுவது எது?' என்று கேட்டேன். அதற்கு அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் தங்களின் நாவின் நுனியைப் பிடித்துக் கொண்டு,<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">هذَا</span>»<br />\r\n(இதனைத்தான்) என்று கூறினார்கள்.\" இதனை அத்-திர்மிதீ மற்றும் இப்னு மாஜா ஆகியோர் பதிவு செய்துள்ளனர்; அத்-திர்மிதீ இதனை \"ஹஸன் ஸஹீஹ்\" என்று குறிப்பிட்டுள்ளார். முஸ்லிம் அவர்களும் தனது ஸஹீஹ் நூலில் இதனைப் பதிவு செய்துள்ளார். அன்-நஸாயீ அவர்கள் பதிவு செய்துள்ள அறிவிப்பில், ஸுஃப்யான் பின் அப்துல்லாஹ் அஸ்-ஸகஃபீ (ரழி) அவர்கள் கூறியதாவது: \"நான், 'அல்லாஹ்வின் தூதரே! இஸ்லாத்தைப் பற்றி எனக்கு ஒரு செய்தியைக் கூறுங்கள். அது குறித்து உங்களுக்குப் பின் நான் வேறு யாரிடமும் கேட்கத் தேவையில்லாத அளவில் அது இருக்கட்டும்' என்று கேட்டேன்.\" அதற்கு அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">قُلْ</span>: <span class=\"quran-arabic-font text-success\">آمَنْتُ</span> <span class=\"quran-arabic-font text-success\">بِاللهِ</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">اسْتَقِم</span>»<br />\r\n(நான் அல்லாஹ்வை நம்பிக்கை கொண்டேன் என்று கூறி, பின்னர் உறுதியாக நிலைத்திருப்பீராக!)\" -- பின்னர் அவர் மீதமுள்ள ஹதீஸைக் குறிப்பிட்டார்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">تَتَنَزَّلُ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمُ</span> <span class=\"quran-arabic-font text-success\">الْمَلَـئِكَةُ</span><br />\r\n(அவர்கள் மீது வானவர்கள் இறங்குவார்கள்). முஜாஹித், அஸ்-ஸுத்தீ, ஸைத் பின் அஸ்லம் மற்றும் அவரது புதல்வர் ஆகியோர், \"இது மரண வேளையில் நிகழும்; அப்போது அவர்கள் (வானவர்கள்) கூறுவார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَلاَّ</span> <span class=\"quran-arabic-font text-success\">تَخَافُواْ</span><br />\r\n(அஞ்சாதீர்கள்).\" முஜாஹித், இக்ரிமா மற்றும் ஸைத் பின் அஸ்லம் ஆகியோர், \"மறுமையில் நீங்கள் எதிர்கொள்ளப் போவதைக் குறித்து அஞ்சாதீர்கள் என்பது இதன் பொருள்\" எனக் கூறினர்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَحْزَنُواْ</span><br />\r\n(கவலைப்படாதீர்கள்!) \"உலகில் நீங்கள் விட்டுச் செல்லும் பிள்ளைகள், குடும்பம், செல்வம் மற்றும் கடன்கள் குறித்துக் கவலைப்படாதீர்கள்; அவற்றை நாங்கள் உங்களுக்காகப் பார்த்துக் கொள்வோம்.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَبْشِرُواْ</span> <span class=\"quran-arabic-font text-success\">بِالْجَنَّةِ</span> <span class=\"quran-arabic-font text-success\">الَّتِى</span> <span class=\"quran-arabic-font text-success\">كُنتُمْ</span> <span class=\"quran-arabic-font text-success\">تُوعَدُونَ</span><br />\r\n(உங்களுக்கு வாக்களிக்கப்பட்ட சொர்க்கத்தைக் கொண்டு நற்செய்தி பெறுங்கள்!) இவ்வாறு, தீமைகள் முடிவுக்கு வருவதையும் நன்மைகள் வந்து சேருவதையும் பற்றி வானவர்கள் நற்செய்தி கூறுகிறார்கள். இது அல்-பராஃ (ரழி) அவர்கள் அறிவித்த ஹதீஸில் கூறப்பட்டுள்ளதைப் போன்றதாகும்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">الْمَلَائِكَةَ</span> <span class=\"quran-arabic-font text-success\">تَقُولُ</span> <span class=\"quran-arabic-font text-success\">لِرُوحِ</span> <span class=\"quran-arabic-font text-success\">الْمُؤْمِنِ</span>: <span class=\"quran-arabic-font text-success\">اخْرُجِي</span> <span class=\"quran-arabic-font text-success\">أَيَّتُهَا</span> <span class=\"quran-arabic-font text-success\">الرُّوحُ</span> <span class=\"quran-arabic-font text-success\">الطَّيِّـبَةُ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْجَسَدِ</span> <span class=\"quran-arabic-font text-success\">الطَّيِّبِ</span> <span class=\"quran-arabic-font text-success\">كُنْتِ</span> <span class=\"quran-arabic-font text-success\">تَعْمُرِينَهُ،</span> <span class=\"quran-arabic-font text-success\">اخْرُجِي</span> <span class=\"quran-arabic-font text-success\">إِلى</span> <span class=\"quran-arabic-font text-success\">رَوْحٍ</span> <span class=\"quran-arabic-font text-success\">وَرَيْحَانٍ</span> <span class=\"quran-arabic-font text-success\">وَرَبٍّ</span> <span class=\"quran-arabic-font text-success\">غَيْرِ</span> <span class=\"quran-arabic-font text-success\">غَضْبَان</span>»<br />\r\n(வானவர்கள் நம்பிக்கையாளரின் ஆன்மாவிடம், \"நல்ல உடலில் குடியிருந்த தூய ஆன்மாவே! வெளியே வா. அமைதிக்கும், நறுமணத்திற்கும், உன் மீது கோபப்படாத இறைவனிடமும் வெளியே வா\" என்று கூறுவார்கள்.) அவர்கள் தங்கள் கல்லறைகளிலிருந்து எழுப்பப்படும் நாளில் வானவர்கள் அவர்களிடம் இறங்குவார்கள் என்றும் கூறப்படுகிறது. ஸைத் பின் அஸ்லம் அவர்கள் கூறினார்கள்: \"அவர்கள் உயிரிழக்கும் போதும், மண்ணறையிலும், அவர்கள் உயிர்த்தெழுப்பப்படும் போதும் வானவர்கள் அவர்களுக்கு நற்செய்தி கூறுவார்கள்.\" இதனை இப்னு அபீ ஹாதிம் பதிவு செய்துள்ளார். இந்தக் கருத்து மற்ற அனைத்துக் கருத்துகளையும் ஒருங்கிணைப்பதாகவும், உண்மையானதாகவும் உள்ளது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">نَحْنُ</span> <span class=\"quran-arabic-font text-success\">أَوْلِيَآؤُكُمْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْحَيَوةِ</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span> <span class=\"quran-arabic-font text-success\">وَفِى</span> <span class=\"quran-arabic-font text-success\">الاٌّخِرَةِ</span><br />\r\n(இவ்வுலக வாழ்விலும் மறுமையிலும் நாங்களே உங்கள் நண்பர்கள்.) இதன் பொருள், மரணம் நெருங்கும் போது வானவர்கள் நம்பிக்கையாளர்களிடம் கூறுவார்கள்: \"நாங்கள் இவ்வுலகில் உங்கள் நெருங்கிய தோழர்களாக இருந்து, அல்லாஹ்வின் கட்டளைப்படி உங்களைப் பாதுகாத்து உங்களுக்கு உதவினோம். மறுமையிலும் நாங்கள் உங்களுடன் இருப்போம். உங்கள் மண்ணறைகளிலும், ஸூர் (எக்காளம்) ஊதப்படும் போதும் நீங்கள் தனிமையை உணர விடமாட்டோம். உயிர்த்தெழுதல் நாளில் உங்களுக்குத் துணிவைத் தந்து, உங்களை 'ஸிராத்' பாலத்தைக் கடக்கச் செய்து, இன்பங்கள் நிறைந்த சொர்க்கச் சோலைகளுக்கு அழைத்துச் செல்வோம்.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَكُمْ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">تَشْتَهِى</span> <span class=\"quran-arabic-font text-success\">أَنفُسُكُمْ</span><br />\r\n(அங்கு உங்கள் மனம் விரும்புவதெல்லாம் உங்களுக்கு உண்டு,) இதன் பொருள், \"சொர்க்கத்தில் நீங்கள் விரும்புவதும், உங்களுக்கு மகிழ்ச்சி அளிப்பவையும் எல்லாம் உங்களுக்குக் கிடைக்கும்.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَكُمْ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">تَدَّعُونَ</span><br />\r\n(மேலும், அங்கு நீங்கள் கேட்பதெல்லாம் உங்களுக்கு உண்டு.) இதன் பொருள், \"நீங்கள் எதைக் கேட்டாலும், அது நீங்கள் விரும்பியவாறே உங்கள் முன் கொண்டு வரப்படும்.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">نُزُلاً</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">غَفُورٍ</span> <span class=\"quran-arabic-font text-success\">رَّحِيمٍ</span><br />\r\n(மிக்க மன்னிப்பவனும், நிகரற்ற அன்புடையவனுமாகிய (இறைவனிடமிருந்து) விருந்தோம்பலாக இது அமையும்.) இதன் பொருள், உங்கள் பாவங்களை மன்னித்து, உங்கள் மீது கருணையும் அன்பும் காட்டும் இறைவனிடமிருந்து கிடைக்கும் வரவேற்புப் பரிசும் அருளுமாகும். அவன் உங்கள் பாவங்களை மன்னித்து, குறைகளை மறைத்து, அன்பையும் கருணையையும் பொழிந்தான் என்பதாகும்.<br />\r\n<br />","text":"அல்லாஹ்வை மட்டும் நம்பி, (நேர்வழியில்) உறுதியாக இருப்பவர்களுக்கு நற்செய்தி\n\r\n\n\r\nإِنَّ الَّذِينَ قَالُواْ رَبُّنَا اللَّهُ ثُمَّ اسْتَقَـمُواْ\n\r\n(நிச்சயமாக, எவர்கள் \"எங்கள் இறைவன் அல்லாஹ்தான்\" என்று கூறி, பின்னர் (அதில்) உறுதியாக நிலைத்திருக்கிறார்களோ,) இதன் பொருள், அவர்கள் நற்செயல்களை அல்லாஹ்வின் திருப்திக்காகத் தூய எண்ணத்துடன் செய்கிறார்கள்; மேலும் அல்லாஹ் தங்களுக்குக் கடமையாக்கியவற்றைச் செய்து அவனுக்குக் கீழ்ப்படிகிறார்கள் என்பதாகும். ஸயீத் பின் இம்ரான் (ரஹ்) கூறினார்கள்: \"நான் இந்த வசனத்தை அபூபக்ர் அஸ்-ஸித்தீக் (ரழி) அவர்களிடம் ஓதிக் காட்டினேன்:\n\r\n\n\r\nإِنَّ الَّذِينَ قَالُواْ رَبُّنَا اللَّهُ ثُمَّ اسْتَقَـمُواْ\n\r\n(நிச்சயமாக, எவர்கள் \"எங்கள் இறைவன் அல்லாஹ்தான்\" என்று கூறி, பின்னர் (அதில்) உறுதியாக நிலைத்திருக்கிறார்களோ,) அதற்கு அவர்கள், 'இவர்கள் அல்லாஹ்வுக்கு எதையும் இணையாக்காதவர்கள்' என்று கூறினார்கள்.\" பின்னர் அவர் அல்-அஸ்வத் பின் ஹிலால் அவர்களின் அறிவிப்பைக் குறிப்பிடுகிறார். அதில் அபூபக்ர் அஸ்-ஸித்தீக் (ரழி) அவர்கள், \"இந்த வசனத்தைப் பற்றி நீங்கள் என்ன கருதுகிறீர்கள்?\" என்று கேட்டார்கள்.\n\r\n\n\r\nإِنَّ الَّذِينَ قَالُواْ رَبُّنَا اللَّهُ ثُمَّ اسْتَقَـمُواْ\n\r\n(நிச்சயமாக, எவர்கள் \"எங்கள் இறைவன் அல்லாஹ்தான்\" என்று கூறி, பின்னர் (அதில்) உறுதியாக நிலைத்திருக்கிறார்களோ,)\" அவர்கள் பதிலளித்தார்கள்:\n\r\n\n\r\nرَبُّنَا اللَّهُ ثُمَّ اسْتَقَـمُواْ\n\r\n(\"எங்கள் இறைவன் அல்லாஹ்தான்,\" பின்னர் அவர்கள் உறுதியாக நிற்கிறார்கள்,) 'அவர்கள் பாவங்களைத் தவிர்க்கிறார்கள்.' அதற்கு அபூபக்ர் (ரழி) அவர்கள், ' நீங்கள் இதை (முறையாக) விளங்கிக் கொள்ளவில்லை. இவர்கள் 'எங்கள் இறைவன் அல்லாஹ்தான்' என்று கூறி, பின்னர் அதில் உறுதியாக நிலைத்திருந்து, அவனைத் தவிர வேறு எவரையும் வணங்காமல் இருப்பவர்களையே இது குறிக்கிறது' என்று கூறினார்கள்.\" இதுவே முஜாஹித், இக்ரிமா, அஸ்-ஸுத்தீ மற்றும் பிறரின் கருத்தாகவும் இருந்தது.\n\r\n\n\r\nஉமர் (ரழி) அவர்கள் மிம்பரின் மீதிருந்தவாறு இந்த வசனத்தை ஓதி, \"அல்லாஹ்வின் மீது ஆணையாக! அவர்கள் அல்லாஹ்வுக்குக் கீழ்ப்படிவதில் உறுதியாக இருந்தார்கள்; நரிகள் தந்திரம் செய்வது போன்று அவர்கள் தந்திரம் செய்யவில்லை\" என்று கூறினார்கள்.\n\r\n\n\r\nஸுஃப்யான் பின் அப்துல்லாஹ் அஸ்-ஸகஃபீ (ரழி) அவர்கள் கூறினார்கள்: \"நான், 'அல்லாஹ்வின் தூதரே, நான் பற்றிப் பிடித்துக் கொள்ள வேண்டிய ஒரு விஷயத்தை எனக்குச் சொல்லுங்கள்' என்று கேட்டேன். அதற்கு அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«قُلْ: رَبِّيَ اللهُ، ثُمَّ اسْتَقِم»\n\r\n(எனது இறைவன் அல்லாஹ்தான் என்று கூறி, பின்னர் உறுதியாக நிலைத்திருப்பீராக!) நான், 'அல்லாஹ்வின் தூதரே, எனக்காக நீங்கள் மிகவும் அஞ்சுவது எது?' என்று கேட்டேன். அதற்கு அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் தங்களின் நாவின் நுனியைப் பிடித்துக் கொண்டு,\n\r\n\n\r\n«هذَا»\n\r\n(இதனைத்தான்) என்று கூறினார்கள்.\" இதனை அத்-திர்மிதீ மற்றும் இப்னு மாஜா ஆகியோர் பதிவு செய்துள்ளனர்; அத்-திர்மிதீ இதனை \"ஹஸன் ஸஹீஹ்\" என்று குறிப்பிட்டுள்ளார். முஸ்லிம் அவர்களும் தனது ஸஹீஹ் நூலில் இதனைப் பதிவு செய்துள்ளார். அன்-நஸாயீ அவர்கள் பதிவு செய்துள்ள அறிவிப்பில், ஸுஃப்யான் பின் அப்துல்லாஹ் அஸ்-ஸகஃபீ (ரழி) அவர்கள் கூறியதாவது: \"நான், 'அல்லாஹ்வின் தூதரே! இஸ்லாத்தைப் பற்றி எனக்கு ஒரு செய்தியைக் கூறுங்கள். அது குறித்து உங்களுக்குப் பின் நான் வேறு யாரிடமும் கேட்கத் தேவையில்லாத அளவில் அது இருக்கட்டும்' என்று கேட்டேன்.\" அதற்கு அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«قُلْ: آمَنْتُ بِاللهِ ثُمَّ اسْتَقِم»\n\r\n(நான் அல்லாஹ்வை நம்பிக்கை கொண்டேன் என்று கூறி, பின்னர் உறுதியாக நிலைத்திருப்பீராக!)\" -- பின்னர் அவர் மீதமுள்ள ஹதீஸைக் குறிப்பிட்டார்.\n\r\n\n\r\nتَتَنَزَّلُ عَلَيْهِمُ الْمَلَـئِكَةُ\n\r\n(அவர்கள் மீது வானவர்கள் இறங்குவார்கள்). முஜாஹித், அஸ்-ஸுத்தீ, ஸைத் பின் அஸ்லம் மற்றும் அவரது புதல்வர் ஆகியோர், \"இது மரண வேளையில் நிகழும்; அப்போது அவர்கள் (வானவர்கள்) கூறுவார்கள்:\n\r\n\n\r\nأَلاَّ تَخَافُواْ\n\r\n(அஞ்சாதீர்கள்).\" முஜாஹித், இக்ரிமா மற்றும் ஸைத் பின் அஸ்லம் ஆகியோர், \"மறுமையில் நீங்கள் எதிர்கொள்ளப் போவதைக் குறித்து அஞ்சாதீர்கள் என்பது இதன் பொருள்\" எனக் கூறினர்.\n\r\n\n\r\nوَلاَ تَحْزَنُواْ\n\r\n(கவலைப்படாதீர்கள்!) \"உலகில் நீங்கள் விட்டுச் செல்லும் பிள்ளைகள், குடும்பம், செல்வம் மற்றும் கடன்கள் குறித்துக் கவலைப்படாதீர்கள்; அவற்றை நாங்கள் உங்களுக்காகப் பார்த்துக் கொள்வோம்.\"\n\r\n\n\r\nوَأَبْشِرُواْ بِالْجَنَّةِ الَّتِى كُنتُمْ تُوعَدُونَ\n\r\n(உங்களுக்கு வாக்களிக்கப்பட்ட சொர்க்கத்தைக் கொண்டு நற்செய்தி பெறுங்கள்!) இவ்வாறு, தீமைகள் முடிவுக்கு வருவதையும் நன்மைகள் வந்து சேருவதையும் பற்றி வானவர்கள் நற்செய்தி கூறுகிறார்கள். இது அல்-பராஃ (ரழி) அவர்கள் அறிவித்த ஹதீஸில் கூறப்பட்டுள்ளதைப் போன்றதாகும்:\n\r\n\n\r\n«إِنَّ الْمَلَائِكَةَ تَقُولُ لِرُوحِ الْمُؤْمِنِ: اخْرُجِي أَيَّتُهَا الرُّوحُ الطَّيِّـبَةُ فِي الْجَسَدِ الطَّيِّبِ كُنْتِ تَعْمُرِينَهُ، اخْرُجِي إِلى رَوْحٍ وَرَيْحَانٍ وَرَبٍّ غَيْرِ غَضْبَان»\n\r\n(வானவர்கள் நம்பிக்கையாளரின் ஆன்மாவிடம், \"நல்ல உடலில் குடியிருந்த தூய ஆன்மாவே! வெளியே வா. அமைதிக்கும், நறுமணத்திற்கும், உன் மீது கோபப்படாத இறைவனிடமும் வெளியே வா\" என்று கூறுவார்கள்.) அவர்கள் தங்கள் கல்லறைகளிலிருந்து எழுப்பப்படும் நாளில் வானவர்கள் அவர்களிடம் இறங்குவார்கள் என்றும் கூறப்படுகிறது. ஸைத் பின் அஸ்லம் அவர்கள் கூறினார்கள்: \"அவர்கள் உயிரிழக்கும் போதும், மண்ணறையிலும், அவர்கள் உயிர்த்தெழுப்பப்படும் போதும் வானவர்கள் அவர்களுக்கு நற்செய்தி கூறுவார்கள்.\" இதனை இப்னு அபீ ஹாதிம் பதிவு செய்துள்ளார். இந்தக் கருத்து மற்ற அனைத்துக் கருத்துகளையும் ஒருங்கிணைப்பதாகவும், உண்மையானதாகவும் உள்ளது.\n\r\n\n\r\nنَحْنُ أَوْلِيَآؤُكُمْ فِى الْحَيَوةِ الدُّنْيَا وَفِى الاٌّخِرَةِ\n\r\n(இவ்வுலக வாழ்விலும் மறுமையிலும் நாங்களே உங்கள் நண்பர்கள்.) இதன் பொருள், மரணம் நெருங்கும் போது வானவர்கள் நம்பிக்கையாளர்களிடம் கூறுவார்கள்: \"நாங்கள் இவ்வுலகில் உங்கள் நெருங்கிய தோழர்களாக இருந்து, அல்லாஹ்வின் கட்டளைப்படி உங்களைப் பாதுகாத்து உங்களுக்கு உதவினோம். மறுமையிலும் நாங்கள் உங்களுடன் இருப்போம். உங்கள் மண்ணறைகளிலும், ஸூர் (எக்காளம்) ஊதப்படும் போதும் நீங்கள் தனிமையை உணர விடமாட்டோம். உயிர்த்தெழுதல் நாளில் உங்களுக்குத் துணிவைத் தந்து, உங்களை 'ஸிராத்' பாலத்தைக் கடக்கச் செய்து, இன்பங்கள் நிறைந்த சொர்க்கச் சோலைகளுக்கு அழைத்துச் செல்வோம்.\"\n\r\n\n\r\nوَلَكُمْ فِيهَا مَا تَشْتَهِى أَنفُسُكُمْ\n\r\n(அங்கு உங்கள் மனம் விரும்புவதெல்லாம் உங்களுக்கு உண்டு,) இதன் பொருள், \"சொர்க்கத்தில் நீங்கள் விரும்புவதும், உங்களுக்கு மகிழ்ச்சி அளிப்பவையும் எல்லாம் உங்களுக்குக் கிடைக்கும்.\"\n\r\n\n\r\nوَلَكُمْ فِيهَا مَا تَدَّعُونَ\n\r\n(மேலும், அங்கு நீங்கள் கேட்பதெல்லாம் உங்களுக்கு உண்டு.) இதன் பொருள், \"நீங்கள் எதைக் கேட்டாலும், அது நீங்கள் விரும்பியவாறே உங்கள் முன் கொண்டு வரப்படும்.\"\n\r\n\n\r\nنُزُلاً مِّنْ غَفُورٍ رَّحِيمٍ\n\r\n(மிக்க மன்னிப்பவனும், நிகரற்ற அன்புடையவனுமாகிய (இறைவனிடமிருந்து) விருந்தோம்பலாக இது அமையும்.) இதன் பொருள், உங்கள் பாவங்களை மன்னித்து, உங்கள் மீது கருணையும் அன்பும் காட்டும் இறைவனிடமிருந்து கிடைக்கும் வரவேற்புப் பரிசும் அருளுமாகும். அவன் உங்கள் பாவங்களை மன்னித்து, குறைகளை மறைத்து, அன்பையும் கருணையையும் பொழிந்தான் என்பதாகும்."},"33":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=41&ayah=36\" class=\"link\">41:36</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 41:36 ஐ பார்க்கவும்"},"34":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=41&ayah=36\" class=\"link\">41:36</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 41:36 ஐ பார்க்கவும்"},"35":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=41&ayah=36\" class=\"link\">41:36</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 41:36 ஐ பார்க்கவும்"},"36":{"html":"<strong>அல்லாஹ்வின் பக்கம் அழைப்பதன் சிறப்பு</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَنْ</span> <span class=\"quran-arabic-font text-success\">أَحْسَنُ</span> <span class=\"quran-arabic-font text-success\">قَوْلاً</span> <span class=\"quran-arabic-font text-success\">مِّمَّن</span> <span class=\"quran-arabic-font text-success\">دَعَآ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span><br />\r\n<br />\r\n(அல்லாஹ்வின் பக்கம் (மக்களை) அழைப்பவரை விட சொல்லால் மிக அழகானவர் யார்?) என்பதன் பொருள், அவர் அல்லாஹ்வின் அடியார்களை அவன் பக்கமே அழைக்கிறார் என்பதாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَعَمِلَ</span> <span class=\"quran-arabic-font text-success\">صَالِحًا</span> <span class=\"quran-arabic-font text-success\">وَقَالَ</span> <span class=\"quran-arabic-font text-success\">إِنَّنِى</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْمُسْلِمِينَ</span><br />\r\n<br />\r\n(மேலும், அவர் நற்செயல்கள் புரிந்து, \"நிச்சயமாக நான் முஸ்லிம்களில் ஒருவன்\" என்றும் கூறுகிறார்.) என்பதன் பொருள், அவர் எதைச் சொல்கிறாரோ அதையே தாமும் பின்பற்றுகிறார்; இதனால் அது அவருக்கும் பிறருக்கும் பயனளிக்கிறது. நன்மையை ஏவிவிட்டுத் தாம் அதைச் செய்யாமலோ அல்லது தீமையைத் தடுத்துவிட்டுத் தாமே அதைச் செய்துகொண்டோ இருப்பவர்களில் அவர் ஒருவரல்ல. அவர் நன்மைகளைச் செய்கிறார், தீமைகளைத் தவிர்க்கிறார்; மேலும் மக்களை அவர்களின் படைப்பாளனின் பக்கம் அழைக்கிறார் - அவன் பாக்கியம் மிக்கவன், உயர்ந்தவன். இது பொதுவான பொருளைக் கொண்டது; நன்மையின் பக்கம் மக்களை அழைத்து, தாம் சொல்வதைக் கொண்டு தாமே நேர்வழி பெறும் அனைவருக்கும் இது பொருந்தும். முஹம்மது பின் ஸீரீன், அஸ்-ஸுத்தீ மற்றும் அப்துர் ரஹ்மான் பின் ஸைத் பின் அஸ்லம் ஆகியோர் கூறியது போல, இவ்விஷயத்தில் மனிதர்களிலேயே முதன்மையானவர் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களாவார்கள். இது ஒரு நேர்மையான முஅத்தினை (பாங்கு சொல்பவரை)க் குறிக்கிறது என்றும் கூறப்பட்டுள்ளது. ஸஹீஹ் முஸ்லிமில் பின்வருமாறு இடம் பெற்றுள்ளது:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">الْمُؤَذِّنُونَ</span> <span class=\"quran-arabic-font text-success\">أَطْوَلُ</span> <span class=\"quran-arabic-font text-success\">النَّاسِ</span> <span class=\"quran-arabic-font text-success\">أَعْنَاقًا</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">الْقِيَامَة</span>»<br />\r\n<br />\r\n(மறுமை நாளில் முஅத்தின்களே மக்களில் மிக நீண்ட கழுத்துடையவர்களாக இருப்பார்கள்.)\" அஸ்-ஸுனன் நூலில் நபி (ஸல்) அவர்கள் கூறியதாகப் பதிவாகியுள்ளது:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">الْإِمَامُ</span> <span class=\"quran-arabic-font text-success\">ضَامِنٌ،</span> <span class=\"quran-arabic-font text-success\">وَالْمُؤَذِّنُ</span> <span class=\"quran-arabic-font text-success\">مُؤْتَمَنٌ،</span> <span class=\"quran-arabic-font text-success\">فَأَرْشَدَ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">الْأَئِمَّةَ</span> <span class=\"quran-arabic-font text-success\">وَغَفَرَ</span> <span class=\"quran-arabic-font text-success\">لِلْمُؤَذِّنِين</span>»<br />\r\n<br />\r\n(இமாம் ஒரு பொறுப்பாளர், முஅத்தின் நம்பிக்கைக்குரியவர். அல்லாஹ் இமாம்களுக்கு நேர்வழி காட்டுவானாக, முஅத்தின்களை மன்னிப்பானாக.)\" இந்த வசனம் பொதுவான பொருளைக் கொண்டது, இது முஅத்தினையும் மற்றவர்களையும் உள்ளடக்கும் என்பதே சரியான கருத்தாகும். இந்த வசனம் அருளப்பட்டபோது, அதான் (பாங்கு) முறை நடைமுறைக்கே வந்திருக்கவில்லை. இந்த வசனம் மக்காவில் அருளப்பட்டது. ஆனால் அதான், ஹிஜ்ரத்திற்குப் பிறகு மதீனாவில்தான் அப்துல்லாஹ் பின் ஸைத் பின் அப்த் ரப்பிஹி அல்-அன்சாரி (ரழி) அவர்களுக்கு ஒரு கனவில் காட்டப்பட்டபோது அறிமுகப்படுத்தப்பட்டது. அவர் அதை அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் கூறினார்கள். பிலால் (ரழி) அவர்களின் குரல் மிகவும் அழகாக இருந்ததால், அவருக்கு அதைக் கற்றுக்கொடுக்குமாறு நபி (ஸல்) அவர்கள் கூறினார்கள்; இதை நாம் வேறு இடத்தில் விவாதித்துள்ளோம். எனவே, இந்த வசனம் பொதுவான பொருளைக் கொண்டது என்பதே சரியான கருத்தாகும். அப்துர் ரஸ்ஸாக் அவர்கள் மஃமர் வழியாக அல்-ஹஸன் அல்-பஸரீ அவர்களிடமிருந்து அறிவிப்பதாவது, அவர் இந்த வசனத்தை ஓதினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَنْ</span> <span class=\"quran-arabic-font text-success\">أَحْسَنُ</span> <span class=\"quran-arabic-font text-success\">قَوْلاً</span> <span class=\"quran-arabic-font text-success\">مِّمَّن</span> <span class=\"quran-arabic-font text-success\">دَعَآ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">وَعَمِلَ</span> <span class=\"quran-arabic-font text-success\">صَالِحًا</span> <span class=\"quran-arabic-font text-success\">وَقَالَ</span> <span class=\"quran-arabic-font text-success\">إِنَّنِى</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْمُسْلِمِينَ</span><br />\r\n<br />\r\n(அல்லாஹ்வின் பக்கம் அழைத்து, நற்செயல்கள் புரிந்து, \"நிச்சயமாக நான் முஸ்லிம்களில் ஒருவன்\" என்று கூறுபவரை விட சொல்லால் மிக அழகானவர் யார்?) பிறகு அவர் கூறினார்கள்: \"இவரே அல்லாஹ்வின் நேசர், இவரே அல்லாஹ்வின் நெருங்கிய நண்பர், இவரே அல்லாஹ்வினால் தேர்ந்தெடுக்கப்பட்டவர், இவரே பூமியிலுள்ள மனிதர்கள் அனைவரிலும் அல்லாஹ்விற்கு மிகவும் பிரியமானவர். அவர் அல்லாஹ்வின் அழைப்பிற்குப் பதிலளித்தார்; மேலும் தாம் எதற்குப் பதிலளித்தாரோ அதன் பக்கமே மனிதர்களையும் அழைத்தார். அந்த அழைப்பிற்கு இணங்கி நற்செயல்களைப் புரிந்தார், 'நான் முஸ்லிம்களில் ஒருவன்' என்றும் கூறினார். இவரே அல்லாஹ்வின் கலீஃபா (பிரதிநிதி) ஆவார்.\"<br />\r\n<br />\r\n<strong>தஃவாவில் (அழைப்புப் பணியில்) உள்ள ஞானம் போன்றவை</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَسْتَوِي</span> <span class=\"quran-arabic-font text-success\">الْحَسَنَةُ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">السَّيِّئَةُ</span><br />\r\n<br />\r\n(நன்மையும் தீமையும் சமமாக மாட்டா.) அதாவது, இவ்விரண்டிற்கும் இடையே மிகப்பெரிய வேறுபாடு உள்ளது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">ادْفَعْ</span> <span class=\"quran-arabic-font text-success\">بِالَّتِى</span> <span class=\"quran-arabic-font text-success\">هِىَ</span> <span class=\"quran-arabic-font text-success\">أَحْسَنُ</span><br />\r\n<br />\r\n((தீமையை) எது மிகச் சிறந்ததோ அதைக் கொண்டு தடுப்பீராக!) அதாவது, 'உமக்கு யாராவது தீங்கு இழைத்தால், அவரிடம் நன்முறையில் நடந்துகொள்வதன் மூலம் அந்தத் தீமையைத் தடுப்பீராக' என்பதாகும். உமர் (ரழி) அவர்கள் கூறியதைப் போல: \"உம் விஷயத்தில் அல்லாஹ்விற்கு மாறு செய்த ஒருவரைத் தண்டிப்பதற்கு, அவர் விஷயத்தில் நீர் அல்லாஹ்விற்குக் கீழ்ப்படிந்து நடப்பதை விட சிறந்த தண்டனை வேறில்லை.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَإِذَا</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">بَيْنَكَ</span> <span class=\"quran-arabic-font text-success\">وَبَيْنَهُ</span> <span class=\"quran-arabic-font text-success\">عَدَاوَةٌ</span> <span class=\"quran-arabic-font text-success\">كَأَنَّهُ</span> <span class=\"quran-arabic-font text-success\">وَلِىٌّ</span> <span class=\"quran-arabic-font text-success\">حَمِيمٌ</span><br />\r\n<br />\r\n(அப்பொழுது, உமக்கும் எவருக்கும் இடையில் பகைமை இருந்ததோ, அவர் ஒரு நெருங்கிய நண்பரைப் போல் ஆகிவிடுவார்.) இதன் பொருள்: 'உமக்குத் தீங்கிழைப்பவர்களிடம் நீர் நன்முறையில் நடந்துகொண்டால், அந்த நற்செயல் இணக்கத்திற்கும், அன்புக்கும், கருணைக்கும் வழிவகுக்கும். அவர் உமக்கு ஒரு நெருங்கிய நண்பரைப் போலாகிவிடுவார்; உம்மீது இரக்கம் கொண்டு, உம்மிடம் அன்பாக நடந்துகொள்வார்.' பின்னர் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">يُلَقَّاهَا</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">صَبَرُواْ</span><br />\r\n<br />\r\n(ஆனால் பொறுமையைக் கடைப்பிடிப்பவர்களைத் தவிர (வேறு) யாரும் அதை அடைய மாட்டார்கள்.) அதாவது, அவ்வாறு செய்வதில் பொறுமையைக் கடைப்பிடிக்கக் கூடியவர்களைத் தவிர, வேறு யாரும் இந்த ஆலோசனையை ஏற்று அதன்படி செயல்பட மாட்டார்கள். ஏனெனில் இது மனிதர்களுக்குச் செய்யக் கடினமான காரியமாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">يُلَقَّاهَآ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">ذُو</span> <span class=\"quran-arabic-font text-success\">حَظِّ</span> <span class=\"quran-arabic-font text-success\">عَظِيمٍ</span><br />\r\n<br />\r\n(மேலும், பெரும் பாக்கியம் உடையவரைத் தவிர வேறு யாரும் அதை அடைய மாட்டார்கள்.) அதாவது, இம்மையிலும் மறுமையிலும் பெரும் நற்பேற்றினைப் பெற்றவரே இதை அடைய முடியும். அலி பின் அபீ தல்ஹா அவர்கள் இப்னு அப்பாஸ் (ரழி) அவர்களின் விளக்கத்தை அறிவிக்கிறார்கள்: \"முஃமின்கள் (நம்பிக்கையாளர்கள்) கோபத்தின் போது பொறுமையாகவும், அறியாமையை எதிர்கொள்ளும் போது சகிப்புத்தன்மையுடனும், அநீதி இழைக்கப்படும் போது மன்னிப்பவர்களாகவும் இருக்க வேண்டும் என்று அல்லாஹ் கட்டளையிடுகிறான். அவர்கள் இவ்வாறு செய்தால், அல்லாஹ் அவர்களை ஷைத்தானிடமிருந்து பாதுகாப்பான்; மேலும் அவர்களின் எதிரிகள் நெருங்கிய நண்பர்களைப் போல மாறும் வரை அவர்களை இவர்களுக்குப் பணிய வைப்பான்.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِمَّا</span> <span class=\"quran-arabic-font text-success\">يَنَزَغَنَّكَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الشَّيْطَانِ</span> <span class=\"quran-arabic-font text-success\">نَزْغٌ</span> <span class=\"quran-arabic-font text-success\">فَاسْتَعِذْ</span> <span class=\"quran-arabic-font text-success\">بِاللَّهِ</span><br />\r\n<br />\r\n(ஷைத்தானிடமிருந்து ஏதேனும் ஒரு தூண்டுதல் உம்மைத் தீண்டுமானால், அல்லாஹ்விடம் பாதுகாவல் தேடுவீராக.) மனிதர்களில் உள்ள ஷைத்தான்களை உமது கனிவான நடத்தையின் மூலம் திருத்திவிடலாம்; ஆனால் ஜின்களில் உள்ள ஷைத்தான்கள் தீய எண்ணங்களை ஊசலாடச் செய்யும் போது, உம்மீது அவனுக்கு அதிகாரத்தை வழங்கிய படைப்பாளனிடம் பாதுகாவல் தேடுவதைத் தவிர வேறு வழியில்லை. நீர் அல்லாஹ்விடம் பாதுகாவல் தேடி அவன் பக்கம் திரும்பினால், அவன் உமக்குத் தீங்கு செய்வதிலிருந்து அந்த ஷைத்தானைத் தடுத்து, அவனது முயற்சிகளை வீணாக்குவான். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் தொழுகைக்காகத் தயாராகும் போது இவ்வாறு கூறுவார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أَعُوذُ</span> <span class=\"quran-arabic-font text-success\">بِاللهِ</span> <span class=\"quran-arabic-font text-success\">السَّمِيعِ</span> <span class=\"quran-arabic-font text-success\">الْعَلِيمِ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الشَّيْطَانِ</span> <span class=\"quran-arabic-font text-success\">الرَّجِيمِ،</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">هَمْزِهِ</span> <span class=\"quran-arabic-font text-success\">وَنَفْخِهِ</span> <span class=\"quran-arabic-font text-success\">وَنَفْثِه</span>»<br />\r\n<br />\r\n(விரட்டப்பட்ட ஷைத்தானிடமிருந்தும், அவனது தீய தூண்டுதல்கள், அவனது ஊதல் மற்றும் அவனது எச்சில் ஆகியவற்றிலிருந்தும், செவியுறுபவனும் அறிந்தவனுமாகிய அல்லாஹ்விடம் நான் பாதுகாவல் தேடுகிறேன்.)\" குர்ஆனில் சூரா அல்-அஃராஃபில் வரும் இந்த வசனத்தைத் தவிர வேறு எங்கும் இதுபோன்ற கருத்து இடம்பெறவில்லை என்பதை நாம் ஏற்கனவே குறிப்பிட்டுள்ளோம்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">خُذِ</span> <span class=\"quran-arabic-font text-success\">الْعَفْوَ</span> <span class=\"quran-arabic-font text-success\">وَأْمُرْ</span> <span class=\"quran-arabic-font text-success\">بِالْعُرْفِ</span> <span class=\"quran-arabic-font text-success\">وَأَعْرِض</span> <span class=\"quran-arabic-font text-success\">عَنِ</span> <span class=\"quran-arabic-font text-success\">الْجَاهِلِينَ</span> - <span class=\"quran-arabic-font text-success\">وَإِمَّا</span> <span class=\"quran-arabic-font text-success\">يَنَزَغَنَّكَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الشَّيْطَانِ</span> <span class=\"quran-arabic-font text-success\">نَزْغٌ</span> <span class=\"quran-arabic-font text-success\">فَاسْتَعِذْ</span> <span class=\"quran-arabic-font text-success\">بِاللَّهِ</span> <span class=\"quran-arabic-font text-success\">إِنَّهُ</span> <span class=\"quran-arabic-font text-success\">سَمِيعٌ</span> <span class=\"quran-arabic-font text-success\">عَلِيمٌ</span><br />\r\n<br />\r\n(மன்னிப்பைக் கடைப்பிடிப்பீராக, நன்மையை ஏவுவீராக, மேலும் அறிவீனர்களைப் புறக்கணிப்பீராக. ஷைத்தானிடமிருந்து ஏதேனும் ஒரு தூண்டுதல் உம்மைத் தீண்டுமானால், அல்லாஹ்விடம் பாதுகாவல் தேடுவீராக. நிச்சயமாக அவன் செவியுறுபவனும், நன்கறிந்தவனுமாவான்.) (<a href=\"qurandisp.php?sura=7&ayah=199\" class=\"link\">7:199</a>-200). மேலும் சூரா அல்-முஃமினூனில் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">ادْفَعْ</span> <span class=\"quran-arabic-font text-success\">بِالَّتِى</span> <span class=\"quran-arabic-font text-success\">هِىَ</span> <span class=\"quran-arabic-font text-success\">أَحْسَنُ</span> <span class=\"quran-arabic-font text-success\">السَّيِّئَةَ</span> <span class=\"quran-arabic-font text-success\">نَحْنُ</span> <span class=\"quran-arabic-font text-success\">أَعْلَمُ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">يَصِفُونَ</span> - <span class=\"quran-arabic-font text-success\">وَقُلْ</span> <span class=\"quran-arabic-font text-success\">رَّبِّ</span> <span class=\"quran-arabic-font text-success\">أَعُوذُ</span> <span class=\"quran-arabic-font text-success\">بِكَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">هَمَزَاتِ</span> <span class=\"quran-arabic-font text-success\">الشَّيَاطِينِ</span> - <span class=\"quran-arabic-font text-success\">وَأَعُوذُ</span> <span class=\"quran-arabic-font text-success\">بِكَ</span> <span class=\"quran-arabic-font text-success\">رَبِّ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يَحْضُرُونِ</span><br />\r\n<br />\r\n(தீமையை மிகச் சிறந்ததைக் கொண்டு தடுப்பீராக. அவர்கள் வர்ணிப்பவற்றை நாம் நன்கறிவோம். மேலும் கூறுவீராக: \"என் இறைவனே! ஷைத்தான்களின் தூண்டுதல்களிலிருந்து உன்னிடம் நான் பாதுகாவல் தேடுகிறேன். என் இறைவனே! அவர்கள் என்னிடம் நெருங்குவதிலிருந்தும் உன்னிடம் நான் பாதுகாவல் தேடுகிறேன்.\") (<a href=\"qurandisp.php?sura=23&ayah=96\" class=\"link\">23:96</a>-98)<br />\r\n<br />\r\n<strong>அல்லாஹ்வின் அத்தாட்சிகள்</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمِنْ</span> <span class=\"quran-arabic-font text-success\">آيَاتِهِ</span> <span class=\"quran-arabic-font text-success\">الَّيْلُ</span> <span class=\"quran-arabic-font text-success\">وَالنَّهَارُ</span> <span class=\"quran-arabic-font text-success\">وَالشَّمْسُ</span> <span class=\"quran-arabic-font text-success\">وَالْقَمَرُ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">تَسْجُدُواْ</span> <span class=\"quran-arabic-font text-success\">لِلشَّمْسِ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">لِلْقَمَرِ</span> <span class=\"quran-arabic-font text-success\">وَاسْجُدُواْ</span> <span class=\"quran-arabic-font text-success\">لِلَّهِ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">خَلَقَهُنَّ</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">كُنتُمْ</span> <span class=\"quran-arabic-font text-success\">إِيَّاهُ</span> <span class=\"quran-arabic-font text-success\">تَعْبُدُونَ</span> - <span class=\"quran-arabic-font text-success\">فَإِنِ</span> <span class=\"quran-arabic-font text-success\">اسْتَكْبَرُواْ</span> <span class=\"quran-arabic-font text-success\">فَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">عِندَ</span> <span class=\"quran-arabic-font text-success\">رَبِّكَ</span> <span class=\"quran-arabic-font text-success\">يُسَبِّحُونَ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">بِاللَّيْلِ</span> <span class=\"quran-arabic-font text-success\">وَالنَّهَارِ</span> <span class=\"quran-arabic-font text-success\">وَهُمْ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَسْأَمُونَ</span><br />\r\n<br />\r\n(அவனுடைய அத்தாட்சிகளில் இரவும், பகலும்; சூரியனும், சந்திரனும் உள்ளன. சூரியனுக்கோ, சந்திரனுக்கோ நீங்கள் சிரம் பணியாதீர்கள்; இவற்றைப் படைத்தவனான அல்லாஹ்வுக்கே நீங்கள் சிரம் பணியுங்கள் - நீங்கள் அவனையே வணங்குபவர்களாக இருந்தால். அவர்கள் பெருமையடித்தால், (அதனால் அல்லாஹ்வுக்கு ஒன்றும் நஷ்டமில்லை;) உமது இறைவனிடத்தில் இருப்பவர்கள் (வானவர்கள்) இரவிலும், பகலிலும் அவனைத் துதித்துக் கொண்டே இருக்கிறார்கள்; அவர்கள் (சிறிதும்) சளைப்பதில்லை.)<br />\r\n<br />\r\n(அவனுடைய அத்தாட்சிகளில்...) என்று அல்லாஹ் கூறுவதன் பொருள்: வானங்களையும் பூமியையும் படைத்தவன் அவனே; அவையிரண்டிற்கும் உள்ளே இருக்கும் அத்தாட்சிகளையும் படைத்தவன் அவனே. (சூரியனுக்கோ, சந்திரனுக்கோ நீங்கள் சிரம் பணியாதீர்கள்; இவைகளைப் படைத்தவனான அல்லாஹ்வுக்கே நீங்கள் சிரம் பணியுங்கள் - நீங்கள் அவனையே வணங்குபவர்களாக இருந்தால்.) அதாவது, இவையனைத்தையும் படைத்தவன் அல்லாஹ்வே ஆவான்; எனவே அவனையன்றி வேறு எதனையும் நீங்கள் வழிபடாதீர்கள். (அவர்கள் பெருமையடித்தால்...) அதாவது, அல்லாஹ்வை வணங்குவதிலிருந்து அவர்கள் பெருமையடித்து விலகிக்கொண்டால், (உமது இறைவனிடத்தில் இருப்பவர்கள்...) அதாவது வானவர்கள் (இரவிலும், பகலிலும் அவனைத் துதித்துக் கொண்டே இருக்கிறார்கள்; அவர்கள் (சிறிதும்) சளைப்பதில்லை.)<br />\r\n<br />","text":"அல்லாஹ்வின் பக்கம் அழைப்பதன் சிறப்பு\n\r\n\n\r\nوَمَنْ أَحْسَنُ قَوْلاً مِّمَّن دَعَآ إِلَى اللَّهِ\n\r\n\n\r\n(அல்லாஹ்வின் பக்கம் (மக்களை) அழைப்பவரை விட சொல்லால் மிக அழகானவர் யார்?) என்பதன் பொருள், அவர் அல்லாஹ்வின் அடியார்களை அவன் பக்கமே அழைக்கிறார் என்பதாகும்.\n\r\n\n\r\nوَعَمِلَ صَالِحًا وَقَالَ إِنَّنِى مِنَ الْمُسْلِمِينَ\n\r\n\n\r\n(மேலும், அவர் நற்செயல்கள் புரிந்து, \"நிச்சயமாக நான் முஸ்லிம்களில் ஒருவன்\" என்றும் கூறுகிறார்.) என்பதன் பொருள், அவர் எதைச் சொல்கிறாரோ அதையே தாமும் பின்பற்றுகிறார்; இதனால் அது அவருக்கும் பிறருக்கும் பயனளிக்கிறது. நன்மையை ஏவிவிட்டுத் தாம் அதைச் செய்யாமலோ அல்லது தீமையைத் தடுத்துவிட்டுத் தாமே அதைச் செய்துகொண்டோ இருப்பவர்களில் அவர் ஒருவரல்ல. அவர் நன்மைகளைச் செய்கிறார், தீமைகளைத் தவிர்க்கிறார்; மேலும் மக்களை அவர்களின் படைப்பாளனின் பக்கம் அழைக்கிறார் - அவன் பாக்கியம் மிக்கவன், உயர்ந்தவன். இது பொதுவான பொருளைக் கொண்டது; நன்மையின் பக்கம் மக்களை அழைத்து, தாம் சொல்வதைக் கொண்டு தாமே நேர்வழி பெறும் அனைவருக்கும் இது பொருந்தும். முஹம்மது பின் ஸீரீன், அஸ்-ஸுத்தீ மற்றும் அப்துர் ரஹ்மான் பின் ஸைத் பின் அஸ்லம் ஆகியோர் கூறியது போல, இவ்விஷயத்தில் மனிதர்களிலேயே முதன்மையானவர் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களாவார்கள். இது ஒரு நேர்மையான முஅத்தினை (பாங்கு சொல்பவரை)க் குறிக்கிறது என்றும் கூறப்பட்டுள்ளது. ஸஹீஹ் முஸ்லிமில் பின்வருமாறு இடம் பெற்றுள்ளது:\n\r\n\n\r\n«الْمُؤَذِّنُونَ أَطْوَلُ النَّاسِ أَعْنَاقًا يَوْمَ الْقِيَامَة»\n\r\n\n\r\n(மறுமை நாளில் முஅத்தின்களே மக்களில் மிக நீண்ட கழுத்துடையவர்களாக இருப்பார்கள்.)\" அஸ்-ஸுனன் நூலில் நபி (ஸல்) அவர்கள் கூறியதாகப் பதிவாகியுள்ளது:\n\r\n\n\r\n«الْإِمَامُ ضَامِنٌ، وَالْمُؤَذِّنُ مُؤْتَمَنٌ، فَأَرْشَدَ اللهُ الْأَئِمَّةَ وَغَفَرَ لِلْمُؤَذِّنِين»\n\r\n\n\r\n(இமாம் ஒரு பொறுப்பாளர், முஅத்தின் நம்பிக்கைக்குரியவர். அல்லாஹ் இமாம்களுக்கு நேர்வழி காட்டுவானாக, முஅத்தின்களை மன்னிப்பானாக.)\" இந்த வசனம் பொதுவான பொருளைக் கொண்டது, இது முஅத்தினையும் மற்றவர்களையும் உள்ளடக்கும் என்பதே சரியான கருத்தாகும். இந்த வசனம் அருளப்பட்டபோது, அதான் (பாங்கு) முறை நடைமுறைக்கே வந்திருக்கவில்லை. இந்த வசனம் மக்காவில் அருளப்பட்டது. ஆனால் அதான், ஹிஜ்ரத்திற்குப் பிறகு மதீனாவில்தான் அப்துல்லாஹ் பின் ஸைத் பின் அப்த் ரப்பிஹி அல்-அன்சாரி (ரழி) அவர்களுக்கு ஒரு கனவில் காட்டப்பட்டபோது அறிமுகப்படுத்தப்பட்டது. அவர் அதை அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் கூறினார்கள். பிலால் (ரழி) அவர்களின் குரல் மிகவும் அழகாக இருந்ததால், அவருக்கு அதைக் கற்றுக்கொடுக்குமாறு நபி (ஸல்) அவர்கள் கூறினார்கள்; இதை நாம் வேறு இடத்தில் விவாதித்துள்ளோம். எனவே, இந்த வசனம் பொதுவான பொருளைக் கொண்டது என்பதே சரியான கருத்தாகும். அப்துர் ரஸ்ஸாக் அவர்கள் மஃமர் வழியாக அல்-ஹஸன் அல்-பஸரீ அவர்களிடமிருந்து அறிவிப்பதாவது, அவர் இந்த வசனத்தை ஓதினார்கள்:\n\r\n\n\r\nوَمَنْ أَحْسَنُ قَوْلاً مِّمَّن دَعَآ إِلَى اللَّهِ وَعَمِلَ صَالِحًا وَقَالَ إِنَّنِى مِنَ الْمُسْلِمِينَ\n\r\n\n\r\n(அல்லாஹ்வின் பக்கம் அழைத்து, நற்செயல்கள் புரிந்து, \"நிச்சயமாக நான் முஸ்லிம்களில் ஒருவன்\" என்று கூறுபவரை விட சொல்லால் மிக அழகானவர் யார்?) பிறகு அவர் கூறினார்கள்: \"இவரே அல்லாஹ்வின் நேசர், இவரே அல்லாஹ்வின் நெருங்கிய நண்பர், இவரே அல்லாஹ்வினால் தேர்ந்தெடுக்கப்பட்டவர், இவரே பூமியிலுள்ள மனிதர்கள் அனைவரிலும் அல்லாஹ்விற்கு மிகவும் பிரியமானவர். அவர் அல்லாஹ்வின் அழைப்பிற்குப் பதிலளித்தார்; மேலும் தாம் எதற்குப் பதிலளித்தாரோ அதன் பக்கமே மனிதர்களையும் அழைத்தார். அந்த அழைப்பிற்கு இணங்கி நற்செயல்களைப் புரிந்தார், 'நான் முஸ்லிம்களில் ஒருவன்' என்றும் கூறினார். இவரே அல்லாஹ்வின் கலீஃபா (பிரதிநிதி) ஆவார்.\"\n\r\n\n\r\nதஃவாவில் (அழைப்புப் பணியில்) உள்ள ஞானம் போன்றவை\n\r\n\n\r\nوَلاَ تَسْتَوِي الْحَسَنَةُ وَلاَ السَّيِّئَةُ\n\r\n\n\r\n(நன்மையும் தீமையும் சமமாக மாட்டா.) அதாவது, இவ்விரண்டிற்கும் இடையே மிகப்பெரிய வேறுபாடு உள்ளது.\n\r\n\n\r\nادْفَعْ بِالَّتِى هِىَ أَحْسَنُ\n\r\n\n\r\n((தீமையை) எது மிகச் சிறந்ததோ அதைக் கொண்டு தடுப்பீராக!) அதாவது, 'உமக்கு யாராவது தீங்கு இழைத்தால், அவரிடம் நன்முறையில் நடந்துகொள்வதன் மூலம் அந்தத் தீமையைத் தடுப்பீராக' என்பதாகும். உமர் (ரழி) அவர்கள் கூறியதைப் போல: \"உம் விஷயத்தில் அல்லாஹ்விற்கு மாறு செய்த ஒருவரைத் தண்டிப்பதற்கு, அவர் விஷயத்தில் நீர் அல்லாஹ்விற்குக் கீழ்ப்படிந்து நடப்பதை விட சிறந்த தண்டனை வேறில்லை.\"\n\r\n\n\r\nفَإِذَا الَّذِى بَيْنَكَ وَبَيْنَهُ عَدَاوَةٌ كَأَنَّهُ وَلِىٌّ حَمِيمٌ\n\r\n\n\r\n(அப்பொழுது, உமக்கும் எவருக்கும் இடையில் பகைமை இருந்ததோ, அவர் ஒரு நெருங்கிய நண்பரைப் போல் ஆகிவிடுவார்.) இதன் பொருள்: 'உமக்குத் தீங்கிழைப்பவர்களிடம் நீர் நன்முறையில் நடந்துகொண்டால், அந்த நற்செயல் இணக்கத்திற்கும், அன்புக்கும், கருணைக்கும் வழிவகுக்கும். அவர் உமக்கு ஒரு நெருங்கிய நண்பரைப் போலாகிவிடுவார்; உம்மீது இரக்கம் கொண்டு, உம்மிடம் அன்பாக நடந்துகொள்வார்.' பின்னர் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَمَا يُلَقَّاهَا إِلاَّ الَّذِينَ صَبَرُواْ\n\r\n\n\r\n(ஆனால் பொறுமையைக் கடைப்பிடிப்பவர்களைத் தவிர (வேறு) யாரும் அதை அடைய மாட்டார்கள்.) அதாவது, அவ்வாறு செய்வதில் பொறுமையைக் கடைப்பிடிக்கக் கூடியவர்களைத் தவிர, வேறு யாரும் இந்த ஆலோசனையை ஏற்று அதன்படி செயல்பட மாட்டார்கள். ஏனெனில் இது மனிதர்களுக்குச் செய்யக் கடினமான காரியமாகும்.\n\r\n\n\r\nوَمَا يُلَقَّاهَآ إِلاَّ ذُو حَظِّ عَظِيمٍ\n\r\n\n\r\n(மேலும், பெரும் பாக்கியம் உடையவரைத் தவிர வேறு யாரும் அதை அடைய மாட்டார்கள்.) அதாவது, இம்மையிலும் மறுமையிலும் பெரும் நற்பேற்றினைப் பெற்றவரே இதை அடைய முடியும். அலி பின் அபீ தல்ஹா அவர்கள் இப்னு அப்பாஸ் (ரழி) அவர்களின் விளக்கத்தை அறிவிக்கிறார்கள்: \"முஃமின்கள் (நம்பிக்கையாளர்கள்) கோபத்தின் போது பொறுமையாகவும், அறியாமையை எதிர்கொள்ளும் போது சகிப்புத்தன்மையுடனும், அநீதி இழைக்கப்படும் போது மன்னிப்பவர்களாகவும் இருக்க வேண்டும் என்று அல்லாஹ் கட்டளையிடுகிறான். அவர்கள் இவ்வாறு செய்தால், அல்லாஹ் அவர்களை ஷைத்தானிடமிருந்து பாதுகாப்பான்; மேலும் அவர்களின் எதிரிகள் நெருங்கிய நண்பர்களைப் போல மாறும் வரை அவர்களை இவர்களுக்குப் பணிய வைப்பான்.\"\n\r\n\n\r\nوَإِمَّا يَنَزَغَنَّكَ مِنَ الشَّيْطَانِ نَزْغٌ فَاسْتَعِذْ بِاللَّهِ\n\r\n\n\r\n(ஷைத்தானிடமிருந்து ஏதேனும் ஒரு தூண்டுதல் உம்மைத் தீண்டுமானால், அல்லாஹ்விடம் பாதுகாவல் தேடுவீராக.) மனிதர்களில் உள்ள ஷைத்தான்களை உமது கனிவான நடத்தையின் மூலம் திருத்திவிடலாம்; ஆனால் ஜின்களில் உள்ள ஷைத்தான்கள் தீய எண்ணங்களை ஊசலாடச் செய்யும் போது, உம்மீது அவனுக்கு அதிகாரத்தை வழங்கிய படைப்பாளனிடம் பாதுகாவல் தேடுவதைத் தவிர வேறு வழியில்லை. நீர் அல்லாஹ்விடம் பாதுகாவல் தேடி அவன் பக்கம் திரும்பினால், அவன் உமக்குத் தீங்கு செய்வதிலிருந்து அந்த ஷைத்தானைத் தடுத்து, அவனது முயற்சிகளை வீணாக்குவான். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் தொழுகைக்காகத் தயாராகும் போது இவ்வாறு கூறுவார்கள்:\n\r\n\n\r\n«أَعُوذُ بِاللهِ السَّمِيعِ الْعَلِيمِ مِنَ الشَّيْطَانِ الرَّجِيمِ، مِنْ هَمْزِهِ وَنَفْخِهِ وَنَفْثِه»\n\r\n\n\r\n(விரட்டப்பட்ட ஷைத்தானிடமிருந்தும், அவனது தீய தூண்டுதல்கள், அவனது ஊதல் மற்றும் அவனது எச்சில் ஆகியவற்றிலிருந்தும், செவியுறுபவனும் அறிந்தவனுமாகிய அல்லாஹ்விடம் நான் பாதுகாவல் தேடுகிறேன்.)\" குர்ஆனில் சூரா அல்-அஃராஃபில் வரும் இந்த வசனத்தைத் தவிர வேறு எங்கும் இதுபோன்ற கருத்து இடம்பெறவில்லை என்பதை நாம் ஏற்கனவே குறிப்பிட்டுள்ளோம்:\n\r\n\n\r\nخُذِ الْعَفْوَ وَأْمُرْ بِالْعُرْفِ وَأَعْرِض عَنِ الْجَاهِلِينَ - وَإِمَّا يَنَزَغَنَّكَ مِنَ الشَّيْطَانِ نَزْغٌ فَاسْتَعِذْ بِاللَّهِ إِنَّهُ سَمِيعٌ عَلِيمٌ\n\r\n\n\r\n(மன்னிப்பைக் கடைப்பிடிப்பீராக, நன்மையை ஏவுவீராக, மேலும் அறிவீனர்களைப் புறக்கணிப்பீராக. ஷைத்தானிடமிருந்து ஏதேனும் ஒரு தூண்டுதல் உம்மைத் தீண்டுமானால், அல்லாஹ்விடம் பாதுகாவல் தேடுவீராக. நிச்சயமாக அவன் செவியுறுபவனும், நன்கறிந்தவனுமாவான்.) (7:199-200). மேலும் சூரா அல்-முஃமினூனில் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nادْفَعْ بِالَّتِى هِىَ أَحْسَنُ السَّيِّئَةَ نَحْنُ أَعْلَمُ بِمَا يَصِفُونَ - وَقُلْ رَّبِّ أَعُوذُ بِكَ مِنْ هَمَزَاتِ الشَّيَاطِينِ - وَأَعُوذُ بِكَ رَبِّ أَن يَحْضُرُونِ\n\r\n\n\r\n(தீமையை மிகச் சிறந்ததைக் கொண்டு தடுப்பீராக. அவர்கள் வர்ணிப்பவற்றை நாம் நன்கறிவோம். மேலும் கூறுவீராக: \"என் இறைவனே! ஷைத்தான்களின் தூண்டுதல்களிலிருந்து உன்னிடம் நான் பாதுகாவல் தேடுகிறேன். என் இறைவனே! அவர்கள் என்னிடம் நெருங்குவதிலிருந்தும் உன்னிடம் நான் பாதுகாவல் தேடுகிறேன்.\") (23:96-98)\n\r\n\n\r\nஅல்லாஹ்வின் அத்தாட்சிகள்\n\r\n\n\r\nوَمِنْ آيَاتِهِ الَّيْلُ وَالنَّهَارُ وَالشَّمْسُ وَالْقَمَرُ لاَ تَسْجُدُواْ لِلشَّمْسِ وَلاَ لِلْقَمَرِ وَاسْجُدُواْ لِلَّهِ الَّذِى خَلَقَهُنَّ إِن كُنتُمْ إِيَّاهُ تَعْبُدُونَ - فَإِنِ اسْتَكْبَرُواْ فَالَّذِينَ عِندَ رَبِّكَ يُسَبِّحُونَ لَهُ بِاللَّيْلِ وَالنَّهَارِ وَهُمْ لاَ يَسْأَمُونَ\n\r\n\n\r\n(அவனுடைய அத்தாட்சிகளில் இரவும், பகலும்; சூரியனும், சந்திரனும் உள்ளன. சூரியனுக்கோ, சந்திரனுக்கோ நீங்கள் சிரம் பணியாதீர்கள்; இவற்றைப் படைத்தவனான அல்லாஹ்வுக்கே நீங்கள் சிரம் பணியுங்கள் - நீங்கள் அவனையே வணங்குபவர்களாக இருந்தால். அவர்கள் பெருமையடித்தால், (அதனால் அல்லாஹ்வுக்கு ஒன்றும் நஷ்டமில்லை;) உமது இறைவனிடத்தில் இருப்பவர்கள் (வானவர்கள்) இரவிலும், பகலிலும் அவனைத் துதித்துக் கொண்டே இருக்கிறார்கள்; அவர்கள் (சிறிதும்) சளைப்பதில்லை.)\n\r\n\n\r\n(அவனுடைய அத்தாட்சிகளில்...) என்று அல்லாஹ் கூறுவதன் பொருள்: வானங்களையும் பூமியையும் படைத்தவன் அவனே; அவையிரண்டிற்கும் உள்ளே இருக்கும் அத்தாட்சிகளையும் படைத்தவன் அவனே. (சூரியனுக்கோ, சந்திரனுக்கோ நீங்கள் சிரம் பணியாதீர்கள்; இவைகளைப் படைத்தவனான அல்லாஹ்வுக்கே நீங்கள் சிரம் பணியுங்கள் - நீங்கள் அவனையே வணங்குபவர்களாக இருந்தால்.) அதாவது, இவையனைத்தையும் படைத்தவன் அல்லாஹ்வே ஆவான்; எனவே அவனையன்றி வேறு எதனையும் நீங்கள் வழிபடாதீர்கள். (அவர்கள் பெருமையடித்தால்...) அதாவது, அல்லாஹ்வை வணங்குவதிலிருந்து அவர்கள் பெருமையடித்து விலகிக்கொண்டால், (உமது இறைவனிடத்தில் இருப்பவர்கள்...) அதாவது வானவர்கள் (இரவிலும், பகலிலும் அவனைத் துதித்துக் கொண்டே இருக்கிறார்கள்; அவர்கள் (சிறிதும்) சளைப்பதில்லை.)"},"37":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=41&ayah=39\" class=\"link\">41:39</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 41:39 ஐ பார்க்கவும்"},"38":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=41&ayah=39\" class=\"link\">41:39</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 41:39 ஐ பார்க்கவும்"},"39":{"html":"<strong>படைப்புகளும் அவற்றின் ஒழுங்குகளும்</strong><br />\r\n<br />\r\nஇங்கே அல்லாஹ் தனது படைப்புகளுக்குத் தனது ஆற்றலையும், தனக்கு நிகர் எவருமில்லை என்பதையும், தான் அனைத்துப் பொருட்கள் மீதும் பேராற்றல் கொண்டவன் என்பதையும் நினைவூட்டுகிறான். அல்லாஹ் கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَمِنْ</span> <span class=\"quran-arabic-font text-success\">آيَاتِهِ</span> <span class=\"quran-arabic-font text-success\">اللَّيْلُ</span> <span class=\"quran-arabic-font text-success\">وَالنَّهَارُ</span> <span class=\"quran-arabic-font text-success\">وَالشَّمْسُ</span> <span class=\"quran-arabic-font text-success\">وَالْقَمَرُ﴿</span><br />\r\n<br />\r\n(இரவும் பகலும், சூரியனும் சந்திரனும் அவனுடைய அத்தாட்சிகளில் உள்ளவை ஆகும்.) இதன் பொருள்: அவன் இரவை அதன் இருளுடனும், பகலை அதன் ஒளியுடனும் படைத்தான்; அவை தடையின்றி ஒன்றன்பின் ஒன்றாக மாறி மாறி வருகின்றன. மேலும், அவன் சூரியனைப் பிரகாசிக்கும் ஒளியுடனும், சந்திரனைப் பிரதிபலிக்கும் ஒளியுடனும் படைத்தான். அவற்றுக்கு நிலைகளை நிர்ணயித்து, வானத்தில் தனித்தனி சுற்றுப்பாதைகளையும் வழங்கினான். அவற்றின் இயக்கங்களில் ஏற்படும் மாற்றங்களைக் கொண்டு மனிதர்கள் இரவு, பகல், வாரங்கள், மாதங்கள் மற்றும் ஆண்டுகளின் கணக்குகளையும்; மக்களின் உரிமைகள், வணக்க வழிபாடுகள் மற்றும் பல்வேறு கொடுக்கல் வாங்கல்கள் தொடர்பான காலங்களையும் அறிந்து கொள்கின்றனர். மேலும், மேலுலகிலும் கீழுலகிலும் காணப்படக்கூடிய வானுலகப் பொருட்களில் சூரியனும் சந்திரனும் மிகவும் அழகானவை என்பதால், அவை இரண்டும் அல்லாஹ்வினால் படைக்கப்பட்டவை என்றும், அவை அவனது ஆதிக்கம் மற்றும் கட்டுப்பாட்டிற்கு உட்பட்டு அவனுக்கே அடிபணிந்து கிடக்கின்றன என்றும் அவன் சுட்டிக்காட்டுகிறான். எனவே அவன் கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾لاَ</span> <span class=\"quran-arabic-font text-success\">تَسْجُدُواْ</span> <span class=\"quran-arabic-font text-success\">لِلشَّمْسِ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">لِلْقَمَرِ</span> <span class=\"quran-arabic-font text-success\">وَاسْجُدُواْ</span> <span class=\"quran-arabic-font text-success\">لِلَّهِ</span> <span class=\"quran-arabic-font text-success\">الَّذِي</span> <span class=\"quran-arabic-font text-success\">خَلَقَهُنَّ</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">كُنتُمْ</span> <span class=\"quran-arabic-font text-success\">إِيَّاهُ</span> <span class=\"quran-arabic-font text-success\">تَعْبُدُونَ﴿</span><br />\r\n<br />\r\n(நீங்கள் சூரியனுக்கோ அல்லது சந்திரனுக்கோ ஸஜ்தா செய்யாதீர்கள். மாறாக, நீங்கள் (உண்மையாகவே) அவனையே வணங்குபவர்களாக இருந்தால், அவற்றைப்படைத்த அல்லாஹ்வுக்கே ஸஜ்தா செய்யுங்கள்.) அதாவது, \"வணக்கத்தில் அவனுக்கு எதனையும் இணையாக்காதீர்கள்; ஏனெனில் அவனுடன் மற்றவர்களையும் நீங்கள் வணங்கினால், நீங்கள் அவனை வணங்குவதால் உங்களுக்கு எந்தப் பயனும் ஏற்படாது. ஏனெனில், தனக்கு இணையாக்கப்படுவதை அவன் ஒருபோதும் மன்னிக்கமாட்டான்.\" அவன் கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَإِنِ</span> <span class=\"quran-arabic-font text-success\">اسْتَكْبَرُواْ﴿</span><br />\r\n<br />\r\n(ஆனால் அவர்கள் பெருமையடித்தால்,) அதாவது, அவனை மட்டும் வணங்குவதற்குப் பெருமை கொண்டு, அவனுக்கு இணையாக்குவதில் பிடிவாதமாக இருந்தால்,<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">عِندَ</span> <span class=\"quran-arabic-font text-success\">رَبِّكَ﴿</span><br />\r\n<br />\r\n(அப்போது உம்முடைய இறைவனிடம் இருப்பவர்கள்,) அதாவது வானவர்கள்,<br />\r\n<span class=\"quran-arabic-font text-success\">﴾يُسَبِّحُونَ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">بِاللَّيْلِ</span> <span class=\"quran-arabic-font text-success\">وَالنَّهَارِ</span> <span class=\"quran-arabic-font text-success\">وَهُمْ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَسْأَمُونَ﴿</span><br />\r\n<br />\r\n(இரவும் பகலும் அவனைத் துதித்துக் கொண்டிருக்கிறார்கள்; அவர்கள் சோர்வடைவதே இல்லை.) இது பின்வரும் வசனத்தைப் போன்றது:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَإِن</span> <span class=\"quran-arabic-font text-success\">يَكْفُرْ</span> <span class=\"quran-arabic-font text-success\">بِهَا</span> <span class=\"quran-arabic-font text-success\">هَـؤُلاءِ</span> <span class=\"quran-arabic-font text-success\">فَقَدْ</span> <span class=\"quran-arabic-font text-success\">وَكَّلْنَا</span> <span class=\"quran-arabic-font text-success\">بِهَا</span> <span class=\"quran-arabic-font text-success\">قَوْماً</span> <span class=\"quran-arabic-font text-success\">لَّيْسُواْ</span> <span class=\"quran-arabic-font text-success\">بِهَا</span> <span class=\"quran-arabic-font text-success\">بِكَافِرِينَ﴿</span><br />\r\n<br />\r\n(ஆனால் இவர்கள் இதனை நிராகரித்தால், இதனை நிராகரிக்காத ஒரு சமூகத்தினரிடம் நிச்சயமாக நாம் இதனை ஒப்படைத்து விடுவோம்.) (<a href=\"qurandisp.php?sura=6&ayah=89\" class=\"link\">6:89</a>). இவ்வசனத்தை ஓதுபவர் ஸஜ்தாச் செய்வது விரும்பத்தக்கதாகும்.<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَمِنْ</span> <span class=\"quran-arabic-font text-success\">آيَاتِهِ﴿</span><br />\r\n<br />\r\n(அவனுடைய அத்தாட்சிகளில் உள்ளவை) அதாவது, இறந்தவர்களை மீண்டும் உயிர்ப்பிக்கும் அவனது பேராற்றலின் அத்தாட்சிகள்.<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أَنَّكَ</span> <span class=\"quran-arabic-font text-success\">تَرَى</span> <span class=\"quran-arabic-font text-success\">الْأَرْضَ</span> <span class=\"quran-arabic-font text-success\">خَاشِعَةً﴿</span><br />\r\n<br />\r\n(நீர் பூமியை வறண்டு கிடப்பதாகக் காண்கிறீர்,) அதாவது, செடி கொடிகள் ஏதுமின்றி உயிரற்று அது இறந்து கிடக்கிறது.<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَإِذَا</span> <span class=\"quran-arabic-font text-success\">أَنزَلْنَا</span> <span class=\"quran-arabic-font text-success\">عَلَيْهَا</span> <span class=\"quran-arabic-font text-success\">الْمَاءَ</span> <span class=\"quran-arabic-font text-success\">اهْتَزَّتْ</span> <span class=\"quran-arabic-font text-success\">وَرَبَتْ﴿</span><br />\r\n<br />\r\n(ஆனால் நாம் அதன் மீது தண்ணீரை (மழையை) இறக்கினால், அது அசைந்து, செழித்து வளர்கிறது.) அதாவது, அது அசைந்து கொடுக்கிறது; பின்னர் அது அனைத்து வகையான பயிர்களையும் கனிகளையும் வெளிப்படுத்துகிறது.<br />\r\n<span class=\"quran-arabic-font text-success\">﴾إِنَّ</span> <span class=\"quran-arabic-font text-success\">الَّذِي</span> <span class=\"quran-arabic-font text-success\">أَحْيَاهَا</span> <span class=\"quran-arabic-font text-success\">لَمُحْيِي</span> <span class=\"quran-arabic-font text-success\">الْمَوْتَى</span> <span class=\"quran-arabic-font text-success\">إِنَّهُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">كُلِّ</span> <span class=\"quran-arabic-font text-success\">شَيْءٍ</span> <span class=\"quran-arabic-font text-success\">قَدِيرٌ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக அதற்கு உயிர் கொடுத்தவன், நிச்சயமாக மரணித்தோரையும் உயிர்ப்பிப்பவன் ஆவான். நிச்சயமாக அவன் அனைத்துப் பொருட்கள் மீதும் பேராற்றல் கொண்டவன்.)<br />\r\n<br />","text":"படைப்புகளும் அவற்றின் ஒழுங்குகளும்\n\r\n\n\r\nஇங்கே அல்லாஹ் தனது படைப்புகளுக்குத் தனது ஆற்றலையும், தனக்கு நிகர் எவருமில்லை என்பதையும், தான் அனைத்துப் பொருட்கள் மீதும் பேராற்றல் கொண்டவன் என்பதையும் நினைவூட்டுகிறான். அல்லாஹ் கூறுகிறான்:\n\r\n﴾وَمِنْ آيَاتِهِ اللَّيْلُ وَالنَّهَارُ وَالشَّمْسُ وَالْقَمَرُ﴿\n\r\n\n\r\n(இரவும் பகலும், சூரியனும் சந்திரனும் அவனுடைய அத்தாட்சிகளில் உள்ளவை ஆகும்.) இதன் பொருள்: அவன் இரவை அதன் இருளுடனும், பகலை அதன் ஒளியுடனும் படைத்தான்; அவை தடையின்றி ஒன்றன்பின் ஒன்றாக மாறி மாறி வருகின்றன. மேலும், அவன் சூரியனைப் பிரகாசிக்கும் ஒளியுடனும், சந்திரனைப் பிரதிபலிக்கும் ஒளியுடனும் படைத்தான். அவற்றுக்கு நிலைகளை நிர்ணயித்து, வானத்தில் தனித்தனி சுற்றுப்பாதைகளையும் வழங்கினான். அவற்றின் இயக்கங்களில் ஏற்படும் மாற்றங்களைக் கொண்டு மனிதர்கள் இரவு, பகல், வாரங்கள், மாதங்கள் மற்றும் ஆண்டுகளின் கணக்குகளையும்; மக்களின் உரிமைகள், வணக்க வழிபாடுகள் மற்றும் பல்வேறு கொடுக்கல் வாங்கல்கள் தொடர்பான காலங்களையும் அறிந்து கொள்கின்றனர். மேலும், மேலுலகிலும் கீழுலகிலும் காணப்படக்கூடிய வானுலகப் பொருட்களில் சூரியனும் சந்திரனும் மிகவும் அழகானவை என்பதால், அவை இரண்டும் அல்லாஹ்வினால் படைக்கப்பட்டவை என்றும், அவை அவனது ஆதிக்கம் மற்றும் கட்டுப்பாட்டிற்கு உட்பட்டு அவனுக்கே அடிபணிந்து கிடக்கின்றன என்றும் அவன் சுட்டிக்காட்டுகிறான். எனவே அவன் கூறுகிறான்:\n\r\n﴾لاَ تَسْجُدُواْ لِلشَّمْسِ وَلاَ لِلْقَمَرِ وَاسْجُدُواْ لِلَّهِ الَّذِي خَلَقَهُنَّ إِن كُنتُمْ إِيَّاهُ تَعْبُدُونَ﴿\n\r\n\n\r\n(நீங்கள் சூரியனுக்கோ அல்லது சந்திரனுக்கோ ஸஜ்தா செய்யாதீர்கள். மாறாக, நீங்கள் (உண்மையாகவே) அவனையே வணங்குபவர்களாக இருந்தால், அவற்றைப்படைத்த அல்லாஹ்வுக்கே ஸஜ்தா செய்யுங்கள்.) அதாவது, \"வணக்கத்தில் அவனுக்கு எதனையும் இணையாக்காதீர்கள்; ஏனெனில் அவனுடன் மற்றவர்களையும் நீங்கள் வணங்கினால், நீங்கள் அவனை வணங்குவதால் உங்களுக்கு எந்தப் பயனும் ஏற்படாது. ஏனெனில், தனக்கு இணையாக்கப்படுவதை அவன் ஒருபோதும் மன்னிக்கமாட்டான்.\" அவன் கூறுகிறான்:\n\r\n﴾فَإِنِ اسْتَكْبَرُواْ﴿\n\r\n\n\r\n(ஆனால் அவர்கள் பெருமையடித்தால்,) அதாவது, அவனை மட்டும் வணங்குவதற்குப் பெருமை கொண்டு, அவனுக்கு இணையாக்குவதில் பிடிவாதமாக இருந்தால்,\n\r\n﴾فَالَّذِينَ عِندَ رَبِّكَ﴿\n\r\n\n\r\n(அப்போது உம்முடைய இறைவனிடம் இருப்பவர்கள்,) அதாவது வானவர்கள்,\n\r\n﴾يُسَبِّحُونَ لَهُ بِاللَّيْلِ وَالنَّهَارِ وَهُمْ لاَ يَسْأَمُونَ﴿\n\r\n\n\r\n(இரவும் பகலும் அவனைத் துதித்துக் கொண்டிருக்கிறார்கள்; அவர்கள் சோர்வடைவதே இல்லை.) இது பின்வரும் வசனத்தைப் போன்றது:\n\r\n﴾فَإِن يَكْفُرْ بِهَا هَـؤُلاءِ فَقَدْ وَكَّلْنَا بِهَا قَوْماً لَّيْسُواْ بِهَا بِكَافِرِينَ﴿\n\r\n\n\r\n(ஆனால் இவர்கள் இதனை நிராகரித்தால், இதனை நிராகரிக்காத ஒரு சமூகத்தினரிடம் நிச்சயமாக நாம் இதனை ஒப்படைத்து விடுவோம்.) (6:89). இவ்வசனத்தை ஓதுபவர் ஸஜ்தாச் செய்வது விரும்பத்தக்கதாகும்.\n\r\n﴾وَمِنْ آيَاتِهِ﴿\n\r\n\n\r\n(அவனுடைய அத்தாட்சிகளில் உள்ளவை) அதாவது, இறந்தவர்களை மீண்டும் உயிர்ப்பிக்கும் அவனது பேராற்றலின் அத்தாட்சிகள்.\n\r\n﴾أَنَّكَ تَرَى الْأَرْضَ خَاشِعَةً﴿\n\r\n\n\r\n(நீர் பூமியை வறண்டு கிடப்பதாகக் காண்கிறீர்,) அதாவது, செடி கொடிகள் ஏதுமின்றி உயிரற்று அது இறந்து கிடக்கிறது.\n\r\n﴾فَإِذَا أَنزَلْنَا عَلَيْهَا الْمَاءَ اهْتَزَّتْ وَرَبَتْ﴿\n\r\n\n\r\n(ஆனால் நாம் அதன் மீது தண்ணீரை (மழையை) இறக்கினால், அது அசைந்து, செழித்து வளர்கிறது.) அதாவது, அது அசைந்து கொடுக்கிறது; பின்னர் அது அனைத்து வகையான பயிர்களையும் கனிகளையும் வெளிப்படுத்துகிறது.\n\r\n﴾إِنَّ الَّذِي أَحْيَاهَا لَمُحْيِي الْمَوْتَى إِنَّهُ عَلَى كُلِّ شَيْءٍ قَدِيرٌ﴿\n\r\n\n\r\n(நிச்சயமாக அதற்கு உயிர் கொடுத்தவன், நிச்சயமாக மரணித்தோரையும் உயிர்ப்பிப்பவன் ஆவான். நிச்சயமாக அவன் அனைத்துப் பொருட்கள் மீதும் பேராற்றல் கொண்டவன்.)"},"40":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=41&ayah=43\" class=\"link\">41:43</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 41:43 ஐ பார்க்கவும்"},"41":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=41&ayah=43\" class=\"link\">41:43</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 41:43 ஐ பார்க்கவும்"},"42":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=41&ayah=43\" class=\"link\">41:43</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 41:43 ஐ பார்க்கவும்"},"43":{"html":"<strong>மறுப்பாளர்களுக்கான தண்டனையும் குர்ஆனின் சிறப்பும்</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾إِنَّ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">يُلْحِدُونَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">ءَايَـتِنَا﴿</span><br />\r\n<br />\r\n(நிச்சயமாக, எவர் நம் வசனங்களில் திரிபு வேலை செய்கிறார்களோ...) இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: \"அல்-இல்ஹாத் (திரிபுபடுத்துதல்) என்பது வார்த்தைகளை அவற்றிற்குரிய இடங்களிலிருந்து மாற்றி அமைப்பதாகும்.\" கதாதா (ரஹ்) அவர்களும் ஏனையோரும், \"இதன் பொருள் நிராகரிப்பும் பிடிவாதமான போக்கும் ஆகும்\" எனக் கூறினார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾لاَ</span> <span class=\"quran-arabic-font text-success\">يَخْفَوْنَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْنَآ﴿</span><br />\r\n<br />\r\n(...அவர்கள் நமக்கு மறைவானவர்கள் அல்ல.) இது ஒரு கடுமையான எச்சரிக்கையும் அச்சுறுத்தலுமாகும். கண்ணியத்திற்குரிய அல்லாஹ் தனது அத்தாட்சிகள், பெயர்கள் மற்றும் பண்புகளை மறுப்பவர்களை நன்கு அறிவான் என்பதையும், அதற்காக அவர்களை அவன் தண்டிப்பான் என்பதையும் இது குறிக்கிறது. அவன் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أَفَمَن</span> <span class=\"quran-arabic-font text-success\">يُلْقَى</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">النَّارِ</span> <span class=\"quran-arabic-font text-success\">خَيْرٌ</span> <span class=\"quran-arabic-font text-success\">أَم</span> <span class=\"quran-arabic-font text-success\">مَّن</span> <span class=\"quran-arabic-font text-success\">يَأْتِى</span> <span class=\"quran-arabic-font text-success\">ءَامِناً</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">الْقِيَـمَةِ﴿</span><br />\r\n<br />\r\n(நரக நெருப்பில் எறியப்படுபவர் சிறந்தவரா? அல்லது மறுமை நாளில் அச்சமற்றவராக வருபவர் சிறந்தவரா?) அதாவது இவ்விருவரும் சமமாவார்களா? நிச்சயமாக இருவரும் சமமானவர்கள் அல்லர். பின்னர் அல்லாஹ் நிராகரிப்பாளர்களை எச்சரிக்கிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾اعْمَلُواْ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">شِئْتُمْ﴿</span><br />\r\n<br />\r\n(நீங்கள் விரும்புவதைச் செய்யுங்கள்.) முஜாஹித், அத்-தஹ்ஹாக் மற்றும் அதா அல்-குராஸானி (ரஹ்) ஆகியோர் \"(நீங்கள் விரும்புவதைச் செய்யுங்கள்) என்பது ஓர் அச்சுறுத்தலாகும்\" என்று கூறினார்கள். அதாவது, \"நீங்கள் நன்மையோ தீமையோ எதை வேண்டுமானாலும் செய்யுங்கள், நிச்சயமாக அவன் நீங்கள் செய்வதையெல்லாம் பார்த்துக் கொண்டிருக்கிறான்\" என்பதாகும். அவன் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾إِنَّهُ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">تَعْمَلُونَ</span> <span class=\"quran-arabic-font text-success\">بَصِيرٌ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக அவன் நீங்கள் செய்பவற்றைப் பார்ப்பவன் ஆவான்.)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾إِنَّ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُواْ</span> <span class=\"quran-arabic-font text-success\">بِالذِّكْرِ</span> <span class=\"quran-arabic-font text-success\">لَمَّا</span> <span class=\"quran-arabic-font text-success\">جَآءَهُمْ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக, இந்த அறிவுரை (குர்ஆன்) தம்மிடம் வந்தபோது அதனை மறுப்பவர்கள்...) அத்-தஹ்ஹாக், அஸ்-ஸுத்தி மற்றும் கதாதா (ரஹ்) ஆகியோர் \"இது குர்ஆனைக் குறிக்கும்\" என்று கூறினார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَإِنَّهُ</span> <span class=\"quran-arabic-font text-success\">لَكِتَـبٌ</span> <span class=\"quran-arabic-font text-success\">عَزِيزٌ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக அது மகத்துவமிக்க ஒரு வேதமாகும்.) அதாவது இது யாராலும் சிதைக்க முடியாதபடி பாதுகாக்கப்பட்ட வேதமாகும், மேலும் இதைப் போன்ற ஒன்றை எவராலும் கொண்டு வர இயலாது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾لاَّ</span> <span class=\"quran-arabic-font text-success\">يَأْتِيهِ</span> <span class=\"quran-arabic-font text-success\">الْبَـطِلُ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">بَيْنِ</span> <span class=\"quran-arabic-font text-success\">يَدَيْهِ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">خَلْفِهِ﴿</span><br />\r\n<br />\r\n(அதன் முன்னாலிருந்தோ அல்லது அதன் பின்னாலிருந்தோ அதில் பொய் நுழைய முடியாது.) அதாவது, இதனைச் சிதைக்கவோ மாற்றவோ எவ்வித வழியும் இல்லை. ஏனெனில், இது அகிலங்களின் இறைவனால் இறக்கி அருளப்பட்டது. அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾تَنزِيلٌ</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">حَكِيمٍ</span> <span class=\"quran-arabic-font text-success\">حَمِيدٍ﴿</span><br />\r\n<br />\r\n((இது) மகா ஞானமிக்கவனும் புகழுக்குரியவனுமான (அல்லாஹ்வினால்) அருளப்பட்டது.) அதாவது, அவன் தனது சொல் மற்றும் செயல்கள் அனைத்திலும் ஞானமிக்கவன்; தனது கட்டளைகள் மற்றும் விலக்கல்கள் அனைத்திலும் புகழுக்குரியவன். அவன் செய்யும் ஒவ்வொன்றும் போற்றுதலுக்குரிய நோக்கங்களைக் கொண்டவை, அவற்றின் முடிவுகளும் நன்மையாகவே அமையும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾مَّا</span> <span class=\"quran-arabic-font text-success\">يُقَالُ</span> <span class=\"quran-arabic-font text-success\">لَكَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">قَدْ</span> <span class=\"quran-arabic-font text-success\">قِيلَ</span> <span class=\"quran-arabic-font text-success\">لِلرُّسُلِ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَبْلِكَ﴿</span><br />\r\n<br />\r\n((நபியே!) உங்களுக்கு முன்னிருந்த தூதர்களுக்குக் கூறப்பட்டதைத் தவிர வேறெதுவும் உங்களுக்குக் கூறப்படவில்லை.) கதாதா, அஸ்-ஸுத்தி (ரஹ்) மற்றும் பலர் கூறினார்கள்: \"உங்களை நிராகரிப்பதும் பொய்ப்பிப்பதும் புதியதல்ல; உங்களுக்கு முன் வந்த தூதர்களுக்கும் இவ்வாறே கூறப்பட்டது. நீங்கள் பொய்ப்பிக்கப்பட்டது போன்றே அவர்களும் பொய்ப்பிக்கப்பட்டார்கள். அவர்கள் தங்கள் மக்களின் தொல்லைகளை எவ்வாறு பொறுமையுடன் சகித்தார்களோ, அவ்வாறே நீங்களும் உங்கள் மக்களின் தொல்லைகளைப் பொறுமையுடன் சகித்துக் கொள்ளுங்கள்.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَإِنَّ</span> <span class=\"quran-arabic-font text-success\">رَبَّكَ</span> <span class=\"quran-arabic-font text-success\">لَذُو</span> <span class=\"quran-arabic-font text-success\">مَغْفِرَةٍ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக உமது இறைவன் மன்னிப்புடையவன்.) அதாவது, தன்னிடம் பாவமன்னிப்புக் கோரி மீண்டு வருபவர்களை அவன் மன்னிக்கிறான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَذُو</span> <span class=\"quran-arabic-font text-success\">عِقَابٍ</span> <span class=\"quran-arabic-font text-success\">أَلِيمٍ﴿</span><br />\r\n<br />\r\n(மேலும் நோவினை தரும் தண்டனையுடையவனாகவும் இருக்கிறான்.) அதாவது, நிராகரிப்பிலும், வரம்பு மீறுதலிலும், பிடிவாதமான எதிர்ப்பிலும் நிலைத்திருப்பவர்களுக்கு அவன் கடும் தண்டனை அளிப்பவன் ஆவான்.<br />\r\n<br />\r\n<br />\r\n<br />","text":"மறுப்பாளர்களுக்கான தண்டனையும் குர்ஆனின் சிறப்பும்\n\r\n\n\r\n﴾إِنَّ الَّذِينَ يُلْحِدُونَ فِى ءَايَـتِنَا﴿\n\r\n\n\r\n(நிச்சயமாக, எவர் நம் வசனங்களில் திரிபு வேலை செய்கிறார்களோ...) இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: \"அல்-இல்ஹாத் (திரிபுபடுத்துதல்) என்பது வார்த்தைகளை அவற்றிற்குரிய இடங்களிலிருந்து மாற்றி அமைப்பதாகும்.\" கதாதா (ரஹ்) அவர்களும் ஏனையோரும், \"இதன் பொருள் நிராகரிப்பும் பிடிவாதமான போக்கும் ஆகும்\" எனக் கூறினார்கள்.\n\r\n\n\r\n﴾لاَ يَخْفَوْنَ عَلَيْنَآ﴿\n\r\n\n\r\n(...அவர்கள் நமக்கு மறைவானவர்கள் அல்ல.) இது ஒரு கடுமையான எச்சரிக்கையும் அச்சுறுத்தலுமாகும். கண்ணியத்திற்குரிய அல்லாஹ் தனது அத்தாட்சிகள், பெயர்கள் மற்றும் பண்புகளை மறுப்பவர்களை நன்கு அறிவான் என்பதையும், அதற்காக அவர்களை அவன் தண்டிப்பான் என்பதையும் இது குறிக்கிறது. அவன் கூறுகிறான்:\n\r\n\n\r\n﴾أَفَمَن يُلْقَى فِى النَّارِ خَيْرٌ أَم مَّن يَأْتِى ءَامِناً يَوْمَ الْقِيَـمَةِ﴿\n\r\n\n\r\n(நரக நெருப்பில் எறியப்படுபவர் சிறந்தவரா? அல்லது மறுமை நாளில் அச்சமற்றவராக வருபவர் சிறந்தவரா?) அதாவது இவ்விருவரும் சமமாவார்களா? நிச்சயமாக இருவரும் சமமானவர்கள் அல்லர். பின்னர் அல்லாஹ் நிராகரிப்பாளர்களை எச்சரிக்கிறான்:\n\r\n\n\r\n﴾اعْمَلُواْ مَا شِئْتُمْ﴿\n\r\n\n\r\n(நீங்கள் விரும்புவதைச் செய்யுங்கள்.) முஜாஹித், அத்-தஹ்ஹாக் மற்றும் அதா அல்-குராஸானி (ரஹ்) ஆகியோர் \"(நீங்கள் விரும்புவதைச் செய்யுங்கள்) என்பது ஓர் அச்சுறுத்தலாகும்\" என்று கூறினார்கள். அதாவது, \"நீங்கள் நன்மையோ தீமையோ எதை வேண்டுமானாலும் செய்யுங்கள், நிச்சயமாக அவன் நீங்கள் செய்வதையெல்லாம் பார்த்துக் கொண்டிருக்கிறான்\" என்பதாகும். அவன் கூறுகிறான்:\n\r\n\n\r\n﴾إِنَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ﴿\n\r\n\n\r\n(நிச்சயமாக அவன் நீங்கள் செய்பவற்றைப் பார்ப்பவன் ஆவான்.)\n\r\n\n\r\n﴾إِنَّ الَّذِينَ كَفَرُواْ بِالذِّكْرِ لَمَّا جَآءَهُمْ﴿\n\r\n\n\r\n(நிச்சயமாக, இந்த அறிவுரை (குர்ஆன்) தம்மிடம் வந்தபோது அதனை மறுப்பவர்கள்...) அத்-தஹ்ஹாக், அஸ்-ஸுத்தி மற்றும் கதாதா (ரஹ்) ஆகியோர் \"இது குர்ஆனைக் குறிக்கும்\" என்று கூறினார்கள்.\n\r\n\n\r\n﴾وَإِنَّهُ لَكِتَـبٌ عَزِيزٌ﴿\n\r\n\n\r\n(நிச்சயமாக அது மகத்துவமிக்க ஒரு வேதமாகும்.) அதாவது இது யாராலும் சிதைக்க முடியாதபடி பாதுகாக்கப்பட்ட வேதமாகும், மேலும் இதைப் போன்ற ஒன்றை எவராலும் கொண்டு வர இயலாது.\n\r\n\n\r\n﴾لاَّ يَأْتِيهِ الْبَـطِلُ مِن بَيْنِ يَدَيْهِ وَلاَ مِنْ خَلْفِهِ﴿\n\r\n\n\r\n(அதன் முன்னாலிருந்தோ அல்லது அதன் பின்னாலிருந்தோ அதில் பொய் நுழைய முடியாது.) அதாவது, இதனைச் சிதைக்கவோ மாற்றவோ எவ்வித வழியும் இல்லை. ஏனெனில், இது அகிலங்களின் இறைவனால் இறக்கி அருளப்பட்டது. அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\n﴾تَنزِيلٌ مِّنْ حَكِيمٍ حَمِيدٍ﴿\n\r\n\n\r\n((இது) மகா ஞானமிக்கவனும் புகழுக்குரியவனுமான (அல்லாஹ்வினால்) அருளப்பட்டது.) அதாவது, அவன் தனது சொல் மற்றும் செயல்கள் அனைத்திலும் ஞானமிக்கவன்; தனது கட்டளைகள் மற்றும் விலக்கல்கள் அனைத்திலும் புகழுக்குரியவன். அவன் செய்யும் ஒவ்வொன்றும் போற்றுதலுக்குரிய நோக்கங்களைக் கொண்டவை, அவற்றின் முடிவுகளும் நன்மையாகவே அமையும்.\n\r\n\n\r\n﴾مَّا يُقَالُ لَكَ إِلاَّ مَا قَدْ قِيلَ لِلرُّسُلِ مِن قَبْلِكَ﴿\n\r\n\n\r\n((நபியே!) உங்களுக்கு முன்னிருந்த தூதர்களுக்குக் கூறப்பட்டதைத் தவிர வேறெதுவும் உங்களுக்குக் கூறப்படவில்லை.) கதாதா, அஸ்-ஸுத்தி (ரஹ்) மற்றும் பலர் கூறினார்கள்: \"உங்களை நிராகரிப்பதும் பொய்ப்பிப்பதும் புதியதல்ல; உங்களுக்கு முன் வந்த தூதர்களுக்கும் இவ்வாறே கூறப்பட்டது. நீங்கள் பொய்ப்பிக்கப்பட்டது போன்றே அவர்களும் பொய்ப்பிக்கப்பட்டார்கள். அவர்கள் தங்கள் மக்களின் தொல்லைகளை எவ்வாறு பொறுமையுடன் சகித்தார்களோ, அவ்வாறே நீங்களும் உங்கள் மக்களின் தொல்லைகளைப் பொறுமையுடன் சகித்துக் கொள்ளுங்கள்.\"\n\r\n\n\r\n﴾وَإِنَّ رَبَّكَ لَذُو مَغْفِرَةٍ﴿\n\r\n\n\r\n(நிச்சயமாக உமது இறைவன் மன்னிப்புடையவன்.) அதாவது, தன்னிடம் பாவமன்னிப்புக் கோரி மீண்டு வருபவர்களை அவன் மன்னிக்கிறான்.\n\r\n\n\r\n﴾وَذُو عِقَابٍ أَلِيمٍ﴿\n\r\n\n\r\n(மேலும் நோவினை தரும் தண்டனையுடையவனாகவும் இருக்கிறான்.) அதாவது, நிராகரிப்பிலும், வரம்பு மீறுதலிலும், பிடிவாதமான எதிர்ப்பிலும் நிலைத்திருப்பவர்களுக்கு அவன் கடும் தண்டனை அளிப்பவன் ஆவான்."},"44":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=41&ayah=45\" class=\"link\">41:45</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 41:45 ஐ பார்க்கவும்"},"45":{"html":"<strong>குர்ஆனை நிராகரிப்பது அப்பட்டமான பிடிவாதமே</strong><br />\r\nகுர்ஆன் அதன் சொல்லமைப்பிலும் கருத்துகளிலும் மிகுந்த நாவன்மையும் முழுமையும் வாய்ந்தது; இருப்பினும் இணைவைப்பாளர்கள் அதனை நம்புவதில்லை என்று அல்லாஹ் கூறுகிறான். அவர்களின் இந்த நிராகரிப்பு பிடிவாதத்தினால் உருவானது என்று அவன் கூறுகிறான். அவன் வேறொரு இடத்தில் கூறுவது போல்:<span class=\"quran-arabic-font text-success\">﴾وَلَوْ</span> <span class=\"quran-arabic-font text-success\">نَزَّلْنَـهُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">بَعْضِ</span> <span class=\"quran-arabic-font text-success\">الاٌّعْجَمِينَ</span> <span class=\"quran-arabic-font text-success\">﴿﴾فَقَرَأَهُ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِم</span> <span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">كَانُوا</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">مُؤْمِنِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(நாம் இதனை அரபி அல்லாத ஒருவருக்கு வஹீ (இறைச்செய்தி)யாக இறக்கி, அவர் அதனை அவர்களுக்கு ஓதிக்காட்டியிருந்தாலும், அவர்கள் அதனை ஈமான் கொண்டிருக்க மாட்டார்கள்.) (<a href=\"qurandisp.php?sura=26&ayah=198\" class=\"link\">26:198</a>-199). ஒருவேளை குர்ஆன் அரபி அல்லாத வேறு மொழியில் அருளப்பட்டிருந்தால், அவர்கள் தங்களின் பிடிவாதத்தினால் இவ்வாறு கூறியிருப்பார்கள்:<span class=\"quran-arabic-font text-success\">﴾وَلَوْ</span> <span class=\"quran-arabic-font text-success\">جَعَلْنَـهُ</span> <span class=\"quran-arabic-font text-success\">قُرْءَاناً</span> <span class=\"quran-arabic-font text-success\">أَعْجَمِيّاً</span> <span class=\"quran-arabic-font text-success\">لَّقَالُواْ</span> <span class=\"quran-arabic-font text-success\">لَوْلاَ</span> <span class=\"quran-arabic-font text-success\">فُصِّلَتْ</span> <span class=\"quran-arabic-font text-success\">ءَايَـتُهُ</span> <span class=\"quran-arabic-font text-success\">أَأَعْجَمِيٌّ</span> <span class=\"quran-arabic-font text-success\">وَعَرَبِىٌّ﴿</span><br />\r\n<br />\r\n(இதன் வசனங்கள் ஏன் விரிவாக விளக்கப்படவில்லை? என்ன! அரபி அல்லாத மொழியா? தூதரோ ஓர் அரபியா?) அதாவது, இது ஏன் அரபி மொழியில் விரிவாக விளக்கப்படவில்லை? மேலும் அவர்கள் கண்டனம் தெரிவிக்கும் வகையில், \"என்ன! இது அரபியில் இல்லையா? அல்லது ஒரு அரபியிடமிருந்து வரவில்லையா?\" என்று கூறியிருப்பார்கள். அதாவது, புரியாத ஒரு வேற்று மொழி வார்த்தைகள் ஓர் அரபிக்கு எவ்வாறு வஹீ (இறைச்செய்தி)யாக வர முடியும்? இந்த விளக்கம் இப்னு அப்பாஸ் (ரழி), முஜாஹித் (ரழி), இக்ரிமா (ரழி), ஸயீத் பின் ஜுபைர் (ரழி), அஸ்-ஸுத்தி (ரழி) மற்றும் பலரிடமிருந்து அறிவிக்கப்பட்டுள்ளது.<span class=\"quran-arabic-font text-success\">﴾قُلْ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">لِلَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ءَامَنُواْ</span> <span class=\"quran-arabic-font text-success\">هُدًى</span> <span class=\"quran-arabic-font text-success\">وَشِفَآءٌ﴿</span><br />\r\n<br />\r\n(கூறுவீராக: \"இது ஈமான் கொண்டவர்களுக்கு ஒரு நேர்வழியாகவும், நிவாரணமாகவும் இருக்கிறது...\") இதன் பொருள்: \"முஹம்மதே (ஸல்)! நீர் கூறுவீராக: இந்தக் குர்ஆன், இதனை நம்புபவர்களின் உள்ளங்களுக்கு நேர்வழியாகவும், மக்களின் உள்ளங்களில் இருக்கும் சந்தேகங்கள் மற்றும் குழப்பங்களுக்கு ஒரு மருந்தாகவும் இருக்கிறது.\"<span class=\"quran-arabic-font text-success\">﴾وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يُؤْمِنُونَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">ءَاذَانِهِمْ</span> <span class=\"quran-arabic-font text-success\">وَقْرٌ﴿</span><br />\r\n<br />\r\n(ஈமான் கொள்ளாதவர்களைப் பொறுத்தவரை, அவர்களின் காதுகளில் ஒரு செவிட்டுத்தன்மை (மந்தநிலை) இருக்கிறது,) அதாவது, அதில் உள்ளவற்றை அவர்களால் புரிந்து கொள்ள முடிவதில்லை.<span class=\"quran-arabic-font text-success\">﴾وَهُوَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">عَمًى﴿</span><br />\r\n<br />\r\n(அது அவர்களுக்குக் குருட்டுத்தன்மையாக இருக்கிறது.) அதாவது, அதில் உள்ள விளக்கங்களின் பால் அவர்கள் நேர்வழி பெறுவதில்லை. இது இந்த வசனத்தைப் போன்றது:<span class=\"quran-arabic-font text-success\">﴾وَنُنَزِّلُ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْقُرْءَانِ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">شِفَآءٌ</span> <span class=\"quran-arabic-font text-success\">وَرَحْمَةٌ</span> <span class=\"quran-arabic-font text-success\">لِّلْمُؤْمِنِينَ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">يَزِيدُ</span> <span class=\"quran-arabic-font text-success\">الظَّـلِمِينَ</span> <span class=\"quran-arabic-font text-success\">إَلاَّ</span> <span class=\"quran-arabic-font text-success\">خَسَارًا</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(இன்னும், நாம் குர்ஆனிலிருந்து ஈமான் கொண்டவர்களுக்கு நிவாரணமாகவும், அருளாகவும் இருப்பவற்றை இறக்குகிறோம்; ஆனால் அது அநியாயக்காரர்களுக்கு நஷ்டத்தையே தவிர வேறெதனையும் அதிகப்படுத்துவதில்லை.) (<a href=\"qurandisp.php?sura=17&ayah=82\" class=\"link\">17:82</a>).<span class=\"quran-arabic-font text-success\">﴾أُوْلَـئِكَ</span> <span class=\"quran-arabic-font text-success\">يُنَادَوْنَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">مَّكَانٍ</span> <span class=\"quran-arabic-font text-success\">بَعِيدٍ﴿</span><br />\r\n<br />\r\n(அவர்கள் மிகத் தொலைவான இடத்திலிருந்து அழைக்கப்படுகிறார்கள்.) முஜாஹித் (ரழி) கூறினார்கள்: \"அவர்களின் உள்ளங்களை விட்டு வெகு தொலைவில்.\" இப்னு ஜரீர் (ரழி) கூறினார்கள்: \"அவர்களை அழைப்பவர் ஏதோ மிகத் தூரத்திலிருந்து அழைப்பதைப் போன்றும், அவர் சொல்வதை அவர்களால் புரிந்து கொள்ள முடியாததைப் போன்றும் இது இருக்கிறது.\" இது இந்த வசனத்தைப் போன்றது:<span class=\"quran-arabic-font text-success\">﴾وَمَثَلُ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُواْ</span> <span class=\"quran-arabic-font text-success\">كَمَثَلِ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">يَنْعِقُ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَسْمَعُ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">دُعَآءً</span> <span class=\"quran-arabic-font text-success\">وَنِدَآءً</span> <span class=\"quran-arabic-font text-success\">صُمٌّ</span> <span class=\"quran-arabic-font text-success\">بُكْمٌ</span> <span class=\"quran-arabic-font text-success\">عُمْىٌ</span> <span class=\"quran-arabic-font text-success\">فَهُمْ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَعْقِلُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(நிராகரிப்பவர்களுக்கு உதாரணம், வெறும் சப்தத்தையும் கூச்சலையும் தவிர வேறெதனையும் கேட்காத (ஆட்டு மந்தையை) நோக்கிச் சத்தமிடுபவனின் உதாரணத்தைப் போன்றது. அவர்கள் செவிடர்களாகவும், ஊமையர்களாகவும், குருடர்களாகவும் இருக்கின்றனர். எனவே அவர்கள் எதனையும் விளங்கிக் கொள்ள மாட்டார்கள்.) (<a href=\"qurandisp.php?sura=2&ayah=171\" class=\"link\">2:171</a>)<br />\r\n<br />\r\n<strong>மூஸா (அலை) அவர்களை ஒரு முன்மாதிரியாகக் கொள்ளுதல்</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَلَقَدْ</span> <span class=\"quran-arabic-font text-success\">ءَاتَيْنَا</span> <span class=\"quran-arabic-font text-success\">مُوسَى</span> <span class=\"quran-arabic-font text-success\">الْكِتَـبَ</span> <span class=\"quran-arabic-font text-success\">فَاخْتُلِفَ</span> <span class=\"quran-arabic-font text-success\">فِيهِ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக நாம் மூஸாவுக்கு (அலை) வேதத்தைக் கொடுத்தோம்; ஆனால் அதில் கருத்து வேறுபாடுகள் தோற்றுவிக்கப்பட்டன.) அதாவது, அவர்கள் அவரைப் பொய்ப்பித்தார்கள், அவருக்குத் தொல்லை கொடுத்தார்கள்.<span class=\"quran-arabic-font text-success\">﴾فَاصْبِرْ</span> <span class=\"quran-arabic-font text-success\">كَمَا</span> <span class=\"quran-arabic-font text-success\">صَبَرَ</span> <span class=\"quran-arabic-font text-success\">أُوْلُواْ</span> <span class=\"quran-arabic-font text-success\">الْعَزْمِ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الرُّسُلِ﴿</span><br />\r\n<br />\r\n(எனவே, உறுதிமிக்க தூதர்கள் பொறுமையுடன் இருந்தது போல நீரும் பொறுமையுடன் இருப்பீராக) (<a href=\"qurandisp.php?sura=46&ayah=35\" class=\"link\">46:35</a>). <span class=\"quran-arabic-font text-success\">﴾وَلَوْلاَ</span> <span class=\"quran-arabic-font text-success\">كَلِمَةٌ</span> <span class=\"quran-arabic-font text-success\">سَبَقَتْ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">رَّبِّكَ﴿</span><br />\r\n<br />\r\n(உமது இறைவனிடமிருந்து ஏற்கனவே ஒரு வாக்கு முந்திச் சென்றிருக்காவிட்டால்,) அதாவது, மறுமை நாள் வரை தீர்ப்பைத் தள்ளிப்போடுவது என்று அவன் விதித்திருக்காவிட்டால், <span class=\"quran-arabic-font text-success\">﴾لَقُضِيَ</span> <span class=\"quran-arabic-font text-success\">بَيْنَهُمْ﴿</span><br />\r\n<br />\r\n(அவர்களுக்கிடையிலான காரியம் அப்பொழுதே முடிக்கப்பட்டிருக்கும்.) அதாவது, அவர்களுக்கான தண்டனை உடனே வழங்கப்பட்டிருக்கும். ஆனால் அவர்களுக்கு என ஒரு குறிப்பிட்ட தவணை இருக்கிறது, அதிலிருந்து அவர்கள் தப்ப முடியாது.<span class=\"quran-arabic-font text-success\">﴾وَإِنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">لَفِى</span> <span class=\"quran-arabic-font text-success\">شَكٍّ</span> <span class=\"quran-arabic-font text-success\">مِّنْهُ</span> <span class=\"quran-arabic-font text-success\">مُرِيبٍ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக அவர்கள் அதைப் பற்றிப் பெரும் சந்தேகத்திலேயே இருக்கிறார்கள்.) அதாவது, அவர்களின் நிராகரிப்பு வார்த்தைகள் ஏதோ ஒரு ஞானத்தினாலோ அல்லது தெளிவினாலோ வந்தவை அல்ல; மாறாக, எதனையும் ஆழமாக ஆராயாமலேயே அவர்கள் பேசுகிறார்கள். இப்னு ஜரீர் (ரழி) அவர்களும் இவ்வாறே விளக்கியுள்ளார்கள், இதுவே பொருத்தமான விளக்கமுமாகும். அல்லாஹ்வே மிக அறிந்தவன்.<br />\r\n<br />","text":"குர்ஆனை நிராகரிப்பது அப்பட்டமான பிடிவாதமே\n\r\nகுர்ஆன் அதன் சொல்லமைப்பிலும் கருத்துகளிலும் மிகுந்த நாவன்மையும் முழுமையும் வாய்ந்தது; இருப்பினும் இணைவைப்பாளர்கள் அதனை நம்புவதில்லை என்று அல்லாஹ் கூறுகிறான். அவர்களின் இந்த நிராகரிப்பு பிடிவாதத்தினால் உருவானது என்று அவன் கூறுகிறான். அவன் வேறொரு இடத்தில் கூறுவது போல்:﴾وَلَوْ نَزَّلْنَـهُ عَلَى بَعْضِ الاٌّعْجَمِينَ ﴿﴾فَقَرَأَهُ عَلَيْهِم مَّا كَانُوا بِهِ مُؤْمِنِينَ ﴿\n\r\n\n\r\n(நாம் இதனை அரபி அல்லாத ஒருவருக்கு வஹீ (இறைச்செய்தி)யாக இறக்கி, அவர் அதனை அவர்களுக்கு ஓதிக்காட்டியிருந்தாலும், அவர்கள் அதனை ஈமான் கொண்டிருக்க மாட்டார்கள்.) (26:198-199). ஒருவேளை குர்ஆன் அரபி அல்லாத வேறு மொழியில் அருளப்பட்டிருந்தால், அவர்கள் தங்களின் பிடிவாதத்தினால் இவ்வாறு கூறியிருப்பார்கள்:﴾وَلَوْ جَعَلْنَـهُ قُرْءَاناً أَعْجَمِيّاً لَّقَالُواْ لَوْلاَ فُصِّلَتْ ءَايَـتُهُ أَأَعْجَمِيٌّ وَعَرَبِىٌّ﴿\n\r\n\n\r\n(இதன் வசனங்கள் ஏன் விரிவாக விளக்கப்படவில்லை? என்ன! அரபி அல்லாத மொழியா? தூதரோ ஓர் அரபியா?) அதாவது, இது ஏன் அரபி மொழியில் விரிவாக விளக்கப்படவில்லை? மேலும் அவர்கள் கண்டனம் தெரிவிக்கும் வகையில், \"என்ன! இது அரபியில் இல்லையா? அல்லது ஒரு அரபியிடமிருந்து வரவில்லையா?\" என்று கூறியிருப்பார்கள். அதாவது, புரியாத ஒரு வேற்று மொழி வார்த்தைகள் ஓர் அரபிக்கு எவ்வாறு வஹீ (இறைச்செய்தி)யாக வர முடியும்? இந்த விளக்கம் இப்னு அப்பாஸ் (ரழி), முஜாஹித் (ரழி), இக்ரிமா (ரழி), ஸயீத் பின் ஜுபைர் (ரழி), அஸ்-ஸுத்தி (ரழி) மற்றும் பலரிடமிருந்து அறிவிக்கப்பட்டுள்ளது.﴾قُلْ هُوَ لِلَّذِينَ ءَامَنُواْ هُدًى وَشِفَآءٌ﴿\n\r\n\n\r\n(கூறுவீராக: \"இது ஈமான் கொண்டவர்களுக்கு ஒரு நேர்வழியாகவும், நிவாரணமாகவும் இருக்கிறது...\") இதன் பொருள்: \"முஹம்மதே (ஸல்)! நீர் கூறுவீராக: இந்தக் குர்ஆன், இதனை நம்புபவர்களின் உள்ளங்களுக்கு நேர்வழியாகவும், மக்களின் உள்ளங்களில் இருக்கும் சந்தேகங்கள் மற்றும் குழப்பங்களுக்கு ஒரு மருந்தாகவும் இருக்கிறது.\"﴾وَالَّذِينَ لاَ يُؤْمِنُونَ فِى ءَاذَانِهِمْ وَقْرٌ﴿\n\r\n\n\r\n(ஈமான் கொள்ளாதவர்களைப் பொறுத்தவரை, அவர்களின் காதுகளில் ஒரு செவிட்டுத்தன்மை (மந்தநிலை) இருக்கிறது,) அதாவது, அதில் உள்ளவற்றை அவர்களால் புரிந்து கொள்ள முடிவதில்லை.﴾وَهُوَ عَلَيْهِمْ عَمًى﴿\n\r\n\n\r\n(அது அவர்களுக்குக் குருட்டுத்தன்மையாக இருக்கிறது.) அதாவது, அதில் உள்ள விளக்கங்களின் பால் அவர்கள் நேர்வழி பெறுவதில்லை. இது இந்த வசனத்தைப் போன்றது:﴾وَنُنَزِّلُ مِنَ الْقُرْءَانِ مَا هُوَ شِفَآءٌ وَرَحْمَةٌ لِّلْمُؤْمِنِينَ وَلاَ يَزِيدُ الظَّـلِمِينَ إَلاَّ خَسَارًا ﴿\n\r\n\n\r\n(இன்னும், நாம் குர்ஆனிலிருந்து ஈமான் கொண்டவர்களுக்கு நிவாரணமாகவும், அருளாகவும் இருப்பவற்றை இறக்குகிறோம்; ஆனால் அது அநியாயக்காரர்களுக்கு நஷ்டத்தையே தவிர வேறெதனையும் அதிகப்படுத்துவதில்லை.) (17:82).﴾أُوْلَـئِكَ يُنَادَوْنَ مِن مَّكَانٍ بَعِيدٍ﴿\n\r\n\n\r\n(அவர்கள் மிகத் தொலைவான இடத்திலிருந்து அழைக்கப்படுகிறார்கள்.) முஜாஹித் (ரழி) கூறினார்கள்: \"அவர்களின் உள்ளங்களை விட்டு வெகு தொலைவில்.\" இப்னு ஜரீர் (ரழி) கூறினார்கள்: \"அவர்களை அழைப்பவர் ஏதோ மிகத் தூரத்திலிருந்து அழைப்பதைப் போன்றும், அவர் சொல்வதை அவர்களால் புரிந்து கொள்ள முடியாததைப் போன்றும் இது இருக்கிறது.\" இது இந்த வசனத்தைப் போன்றது:﴾وَمَثَلُ الَّذِينَ كَفَرُواْ كَمَثَلِ الَّذِى يَنْعِقُ بِمَا لاَ يَسْمَعُ إِلاَّ دُعَآءً وَنِدَآءً صُمٌّ بُكْمٌ عُمْىٌ فَهُمْ لاَ يَعْقِلُونَ ﴿\n\r\n\n\r\n(நிராகரிப்பவர்களுக்கு உதாரணம், வெறும் சப்தத்தையும் கூச்சலையும் தவிர வேறெதனையும் கேட்காத (ஆட்டு மந்தையை) நோக்கிச் சத்தமிடுபவனின் உதாரணத்தைப் போன்றது. அவர்கள் செவிடர்களாகவும், ஊமையர்களாகவும், குருடர்களாகவும் இருக்கின்றனர். எனவே அவர்கள் எதனையும் விளங்கிக் கொள்ள மாட்டார்கள்.) (2:171)\n\r\n\n\r\nமூஸா (அலை) அவர்களை ஒரு முன்மாதிரியாகக் கொள்ளுதல்\n\r\n\n\r\n﴾وَلَقَدْ ءَاتَيْنَا مُوسَى الْكِتَـبَ فَاخْتُلِفَ فِيهِ﴿\n\r\n\n\r\n(நிச்சயமாக நாம் மூஸாவுக்கு (அலை) வேதத்தைக் கொடுத்தோம்; ஆனால் அதில் கருத்து வேறுபாடுகள் தோற்றுவிக்கப்பட்டன.) அதாவது, அவர்கள் அவரைப் பொய்ப்பித்தார்கள், அவருக்குத் தொல்லை கொடுத்தார்கள்.﴾فَاصْبِرْ كَمَا صَبَرَ أُوْلُواْ الْعَزْمِ مِنَ الرُّسُلِ﴿\n\r\n\n\r\n(எனவே, உறுதிமிக்க தூதர்கள் பொறுமையுடன் இருந்தது போல நீரும் பொறுமையுடன் இருப்பீராக) (46:35). ﴾وَلَوْلاَ كَلِمَةٌ سَبَقَتْ مِن رَّبِّكَ﴿\n\r\n\n\r\n(உமது இறைவனிடமிருந்து ஏற்கனவே ஒரு வாக்கு முந்திச் சென்றிருக்காவிட்டால்,) அதாவது, மறுமை நாள் வரை தீர்ப்பைத் தள்ளிப்போடுவது என்று அவன் விதித்திருக்காவிட்டால், ﴾لَقُضِيَ بَيْنَهُمْ﴿\n\r\n\n\r\n(அவர்களுக்கிடையிலான காரியம் அப்பொழுதே முடிக்கப்பட்டிருக்கும்.) அதாவது, அவர்களுக்கான தண்டனை உடனே வழங்கப்பட்டிருக்கும். ஆனால் அவர்களுக்கு என ஒரு குறிப்பிட்ட தவணை இருக்கிறது, அதிலிருந்து அவர்கள் தப்ப முடியாது.﴾وَإِنَّهُمْ لَفِى شَكٍّ مِّنْهُ مُرِيبٍ﴿\n\r\n\n\r\n(நிச்சயமாக அவர்கள் அதைப் பற்றிப் பெரும் சந்தேகத்திலேயே இருக்கிறார்கள்.) அதாவது, அவர்களின் நிராகரிப்பு வார்த்தைகள் ஏதோ ஒரு ஞானத்தினாலோ அல்லது தெளிவினாலோ வந்தவை அல்ல; மாறாக, எதனையும் ஆழமாக ஆராயாமலேயே அவர்கள் பேசுகிறார்கள். இப்னு ஜரீர் (ரழி) அவர்களும் இவ்வாறே விளக்கியுள்ளார்கள், இதுவே பொருத்தமான விளக்கமுமாகும். அல்லாஹ்வே மிக அறிந்தவன்."},"46":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=41&ayah=48\" class=\"link\">41:48</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 41:48 ஐ பார்க்கவும்"},"47":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=41&ayah=48\" class=\"link\">41:48</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 41:48 ஐ பார்க்கவும்"},"48":{"html":"<strong>ஒவ்வொருவருக்கும் அவரவர் செயல்களுக்கேற்பவே கூலி வழங்கப்படும்</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مَّنْ</span> <span class=\"quran-arabic-font text-success\">عَمِلَ</span> <span class=\"quran-arabic-font text-success\">صَالِحًا</span> <span class=\"quran-arabic-font text-success\">فَلِنَفْسِهِ</span><br />\r\n<br />\r\n(யார் நற்செயல் புரிகிறாரோ, அது அவருக்கே (பயனளிக்கும்);) அதாவது, அதன் பலன் அவரைச் சென்றடையும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَنْ</span> <span class=\"quran-arabic-font text-success\">أَسَآءَ</span> <span class=\"quran-arabic-font text-success\">فَعَلَيْهَا</span><br />\r\n<br />\r\n(மேலும், எவர் தீமை செய்கிறாரோ, அது அவருக்கே எதிராக அமையும்.) அதாவது, அதன் விளைவுகள் அவரையே சாரும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">رَبُّكَ</span> <span class=\"quran-arabic-font text-success\">بِظَلَّامٍ</span> <span class=\"quran-arabic-font text-success\">لِّلْعَبِيدِ</span><br />\r\n<br />\r\n(மேலும், உமது இறைவன் (தன்) அடியார்களுக்கு எவ்வகையிலும் அநீதி இழைப்பவன் அல்லன்) அதாவது, அவன் மனிதர்களை அவர்களின் பாவங்களுக்காக மட்டுமே தண்டிக்கிறான்; மேலும், அத்தாட்சிகளை நிலைநாட்டி, ஒரு தூதரை அவர்களிடம் அனுப்பிய பின்னரே தவிர அவன் எவரையும் தண்டிப்பதில்லை.<br />\r\n<br />\r\n<strong>இறுதி நேரத்தைப் பற்றிய அறிவு அல்லாஹ்விடம் மட்டுமே உள்ளது</strong><br />\r\n<br />\r\nபின்னர் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِلَيْهِ</span> <span class=\"quran-arabic-font text-success\">يُرَدُّ</span> <span class=\"quran-arabic-font text-success\">عِلْمُ</span> <span class=\"quran-arabic-font text-success\">السَّاعَةِ</span><br />\r\n<br />\r\n(இறுதி நேரத்தைப் பற்றிய அறிவு அவனிடமே ஒப்படைக்கப்படுகிறது.) அதாவது, அவனைத் தவிர வேறு எவரும் அதனை அறியமாட்டார்கள். மனிதகுலத்தின் தலைவரான முஹம்மது (ஸல்) அவர்கள், வானவர்களில் முதன்மையானவரான ஜிப்ரீல் (அலை) அவர்கள் இறுதி நேரத்தைப் பற்றிக் கேட்டபோது அவர்களிடம் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">الْمَسْؤُولُ</span> <span class=\"quran-arabic-font text-success\">عَنْهَا</span> <span class=\"quran-arabic-font text-success\">بِأَعْلَمَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">السَّائِل</span>»<br />\r\n<br />\r\n(அதைப் பற்றிக் கேட்கப்படுபவர், அதைக் கேட்பவரை விட அதிகம் அறிந்தவர் அல்ல.) மேலும் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">رَبِّكَ</span> <span class=\"quran-arabic-font text-success\">مُنتَهَاهَا</span><br />\r\n<br />\r\n(அதன் முடிவு உமது இறைவனிடமே உள்ளது.) (<a href=\"qurandisp.php?sura=79&ayah=44\" class=\"link\">79:44</a>)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يُجَلِّيهَا</span> <span class=\"quran-arabic-font text-success\">لِوَقْتِهَا</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span><br />\r\n<br />\r\n(அதற்குரிய நேரத்தில் அவனைத் தவிர வேறு எவரும் அதை வெளிப்படுத்த முடியாது) (<a href=\"qurandisp.php?sura=7&ayah=187\" class=\"link\">7:187</a>).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">تَخْرُجُ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">ثَمَرَاتٍ</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">أَكْمَامِهَا</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">تَحْمِلُ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">أُنْثَى</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَضَعُ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">بِعِلْمِهِ</span><br />\r\n<br />\r\n(எந்த ஒரு கனியும் தனது உறையிலிருந்து வெளிப்படுவதில்லை; எந்த ஒரு பெண்ணும் அவனது அறிவின்றி கருத்தரிப்பதோ அல்லது பிரசவிப்பதோ இல்லை.) அதாவது, இவை அனைத்தும் அவனுக்குத் தெரிந்தவையே; வானங்களிலோ அல்லது பூமியிலோ உள்ள ஓர் அணுவளவும் உமது இறைவனுக்கு மறைவானது அல்ல. அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">تَسْقُطُ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">وَرَقَةٍ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">يَعْلَمُهَا</span><br />\r\n<br />\r\n(ஓர் இலை கீழே விழுந்தாலும், அவன் அதனை அறியாமல் இருப்பதில்லை) (<a href=\"qurandisp.php?sura=6&ayah=59\" class=\"link\">6:59</a>).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَعْلَمُ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">تَحْمِلُ</span> <span class=\"quran-arabic-font text-success\">كُلُّ</span> <span class=\"quran-arabic-font text-success\">أُنثَى</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">تَغِيضُ</span> <span class=\"quran-arabic-font text-success\">الْأَرْحَامُ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">تَزْدَادُ</span> <span class=\"quran-arabic-font text-success\">وَكُلُّ</span> <span class=\"quran-arabic-font text-success\">شَىْءٍ</span> <span class=\"quran-arabic-font text-success\">عِندَهُ</span> <span class=\"quran-arabic-font text-success\">بِمِقْدَارٍ</span><br />\r\n<br />\r\n(ஒவ்வொரு பெண்ணும் சுமப்பதையும், கருப்பைகள் சுருங்குவதையும் அல்லது விரிவடைவதையும் அல்லாஹ் அறிகிறான். அவனிடம் ஒவ்வொரு பொருளுக்கும் ஒரு குறிப்பிட்ட அளவு உண்டு) (<a href=\"qurandisp.php?sura=13&ayah=8\" class=\"link\">13:8</a>).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">يُعَمَّرُ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">مُّعَمَّرٍ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">يُنقَصُ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">عُمُرِهِ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">كِتَابٍ</span> <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">يَسِيرٌ</span><br />\r\n<br />\r\n(நீண்ட ஆயுள் வழங்கப்பட்ட எவரது ஆயுளும் நீட்டிக்கப்படுவதோ அல்லது அவரது ஆயுளிலிருந்து ஒரு பகுதி குறைக்கப்படுவதோ ஒரு பதிவேட்டில் இல்லாமலில்லை. நிச்சயமாக இது அல்லாஹ்வுக்கு மிக எளிதானதாகும்.) (<a href=\"qurandisp.php?sura=35&ayah=11\" class=\"link\">35:11</a>)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَيَوْمَ</span> <span class=\"quran-arabic-font text-success\">يُنَادِيهِمْ</span> <span class=\"quran-arabic-font text-success\">أَيْنَ</span> <span class=\"quran-arabic-font text-success\">شُرَكَآئِى</span><br />\r\n<br />\r\n(அவன் அவர்களை அழைத்து, \"எனக்கு இணையாக நீங்கள் கருதியவர்கள் எங்கே?\" என்று கேட்கும் நாளில்) அதாவது, மறுமை நாளில், அல்லாஹ் அனைத்துப் படைப்புகளுக்கும் முன்னிலையில் இணைவைப்பவர்களை அழைத்து, \"என்னைத் தவிர நீங்கள் வணங்கிக் கொண்டிருந்த எனது கூட்டாளிகள் எங்கே?\" என்று கேட்பான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">ءَاذَنَّاكَ</span><br />\r\n<br />\r\n(அவர்கள் கூறுவார்கள்: \"உன்னிடம் நாங்கள் அறிவிக்கிறோம்...\") அதாவது, 'நாங்கள் உன்னிடம் கூறுகிறோம்,'<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">مِنَّا</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">شَهِيدٍ</span><br />\r\n<br />\r\n(எங்களில் எவரும் அதற்குச் சாட்சியாக இல்லை.) அதாவது, 'உனக்கு எந்தவொரு கூட்டாளியும் இருப்பதாக இன்று எங்களில் ஒருவர்கூட சாட்சி கூறமாட்டோம்.'<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَضَلَّ</span> <span class=\"quran-arabic-font text-success\">عَنْهُم</span> <span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">يَدْعُونَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَبْلُ</span><br />\r\n<br />\r\n(இதற்கு முன்னர் (இவ்வுலகில்) அவர்கள் எவற்றை அழைத்துக்கொண்டிருந்தார்களோ, அவை அவர்களை விட்டு மறைந்துவிடும்,) அதாவது, அவை அவர்களை விட்டு நீங்கிவிடும், அவர்களுக்கு எவ்விதப் பயனும் அளிக்காது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَظَنُّواْ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">مَّحِيصٍ</span><br />\r\n<br />\r\n(மேலும், தங்களுக்குத் தப்பிச்செல்ல இடமே இல்லை என்பதை அவர்கள் உணர்ந்து கொள்வார்கள்) அதாவது, அல்லாஹ்வின் தண்டனையிலிருந்து தப்பிக்க அவர்களுக்கு எந்த வழியும் இருக்காது. இது பின்வரும் வசனத்தைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَرَأَى</span> <span class=\"quran-arabic-font text-success\">الْمُجْرِمُونَ</span> <span class=\"quran-arabic-font text-success\">النَّارَ</span> <span class=\"quran-arabic-font text-success\">فَظَنُّواْ</span> <span class=\"quran-arabic-font text-success\">أَنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">مُّوَاقِعُوهَا</span> <span class=\"quran-arabic-font text-success\">وَلَمْ</span> <span class=\"quran-arabic-font text-success\">يَجِدُواْ</span> <span class=\"quran-arabic-font text-success\">عَنْهَا</span> <span class=\"quran-arabic-font text-success\">مَصْرِفًا</span><br />\r\n<br />\r\n(குற்றவாளிகள் நரக நெருப்பைக் கண்டு, தாங்கள் அதில் விழப்போகிறோம் என்பதை உணர்ந்து கொள்வார்கள்; அதிலிருந்து தப்பிக்க அவர்கள் எந்தவொரு புகலிடத்தையும் காண மாட்டார்கள்.) (<a href=\"qurandisp.php?sura=18&ayah=53\" class=\"link\">18:53</a>)<br />\r\n<br />","text":"ஒவ்வொருவருக்கும் அவரவர் செயல்களுக்கேற்பவே கூலி வழங்கப்படும்\n\r\n\n\r\nمَّنْ عَمِلَ صَالِحًا فَلِنَفْسِهِ\n\r\n\n\r\n(யார் நற்செயல் புரிகிறாரோ, அது அவருக்கே (பயனளிக்கும்);) அதாவது, அதன் பலன் அவரைச் சென்றடையும்.\n\r\n\n\r\nوَمَنْ أَسَآءَ فَعَلَيْهَا\n\r\n\n\r\n(மேலும், எவர் தீமை செய்கிறாரோ, அது அவருக்கே எதிராக அமையும்.) அதாவது, அதன் விளைவுகள் அவரையே சாரும்.\n\r\n\n\r\nوَمَا رَبُّكَ بِظَلَّامٍ لِّلْعَبِيدِ\n\r\n\n\r\n(மேலும், உமது இறைவன் (தன்) அடியார்களுக்கு எவ்வகையிலும் அநீதி இழைப்பவன் அல்லன்) அதாவது, அவன் மனிதர்களை அவர்களின் பாவங்களுக்காக மட்டுமே தண்டிக்கிறான்; மேலும், அத்தாட்சிகளை நிலைநாட்டி, ஒரு தூதரை அவர்களிடம் அனுப்பிய பின்னரே தவிர அவன் எவரையும் தண்டிப்பதில்லை.\n\r\n\n\r\nஇறுதி நேரத்தைப் பற்றிய அறிவு அல்லாஹ்விடம் மட்டுமே உள்ளது\n\r\n\n\r\nபின்னர் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nإِلَيْهِ يُرَدُّ عِلْمُ السَّاعَةِ\n\r\n\n\r\n(இறுதி நேரத்தைப் பற்றிய அறிவு அவனிடமே ஒப்படைக்கப்படுகிறது.) அதாவது, அவனைத் தவிர வேறு எவரும் அதனை அறியமாட்டார்கள். மனிதகுலத்தின் தலைவரான முஹம்மது (ஸல்) அவர்கள், வானவர்களில் முதன்மையானவரான ஜிப்ரீல் (அலை) அவர்கள் இறுதி நேரத்தைப் பற்றிக் கேட்டபோது அவர்களிடம் கூறினார்கள்:\n\r\n\n\r\n«مَا الْمَسْؤُولُ عَنْهَا بِأَعْلَمَ مِنَ السَّائِل»\n\r\n\n\r\n(அதைப் பற்றிக் கேட்கப்படுபவர், அதைக் கேட்பவரை விட அதிகம் அறிந்தவர் அல்ல.) மேலும் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nإِلَى رَبِّكَ مُنتَهَاهَا\n\r\n\n\r\n(அதன் முடிவு உமது இறைவனிடமே உள்ளது.) (79:44)\n\r\n\n\r\nلاَ يُجَلِّيهَا لِوَقْتِهَا إِلاَّ هُوَ\n\r\n\n\r\n(அதற்குரிய நேரத்தில் அவனைத் தவிர வேறு எவரும் அதை வெளிப்படுத்த முடியாது) (7:187).\n\r\n\n\r\nوَمَا تَخْرُجُ مِن ثَمَرَاتٍ مِّنْ أَكْمَامِهَا وَمَا تَحْمِلُ مِنْ أُنْثَى وَلاَ تَضَعُ إِلاَّ بِعِلْمِهِ\n\r\n\n\r\n(எந்த ஒரு கனியும் தனது உறையிலிருந்து வெளிப்படுவதில்லை; எந்த ஒரு பெண்ணும் அவனது அறிவின்றி கருத்தரிப்பதோ அல்லது பிரசவிப்பதோ இல்லை.) அதாவது, இவை அனைத்தும் அவனுக்குத் தெரிந்தவையே; வானங்களிலோ அல்லது பூமியிலோ உள்ள ஓர் அணுவளவும் உமது இறைவனுக்கு மறைவானது அல்ல. அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَمَا تَسْقُطُ مِن وَرَقَةٍ إِلاَّ يَعْلَمُهَا\n\r\n\n\r\n(ஓர் இலை கீழே விழுந்தாலும், அவன் அதனை அறியாமல் இருப்பதில்லை) (6:59).\n\r\n\n\r\nيَعْلَمُ مَا تَحْمِلُ كُلُّ أُنثَى وَمَا تَغِيضُ الْأَرْحَامُ وَمَا تَزْدَادُ وَكُلُّ شَىْءٍ عِندَهُ بِمِقْدَارٍ\n\r\n\n\r\n(ஒவ்வொரு பெண்ணும் சுமப்பதையும், கருப்பைகள் சுருங்குவதையும் அல்லது விரிவடைவதையும் அல்லாஹ் அறிகிறான். அவனிடம் ஒவ்வொரு பொருளுக்கும் ஒரு குறிப்பிட்ட அளவு உண்டு) (13:8).\n\r\n\n\r\nوَمَا يُعَمَّرُ مِن مُّعَمَّرٍ وَلاَ يُنقَصُ مِنْ عُمُرِهِ إِلاَّ فِى كِتَابٍ إِنَّ ذَلِكَ عَلَى اللَّهِ يَسِيرٌ\n\r\n\n\r\n(நீண்ட ஆயுள் வழங்கப்பட்ட எவரது ஆயுளும் நீட்டிக்கப்படுவதோ அல்லது அவரது ஆயுளிலிருந்து ஒரு பகுதி குறைக்கப்படுவதோ ஒரு பதிவேட்டில் இல்லாமலில்லை. நிச்சயமாக இது அல்லாஹ்வுக்கு மிக எளிதானதாகும்.) (35:11)\n\r\n\n\r\nوَيَوْمَ يُنَادِيهِمْ أَيْنَ شُرَكَآئِى\n\r\n\n\r\n(அவன் அவர்களை அழைத்து, \"எனக்கு இணையாக நீங்கள் கருதியவர்கள் எங்கே?\" என்று கேட்கும் நாளில்) அதாவது, மறுமை நாளில், அல்லாஹ் அனைத்துப் படைப்புகளுக்கும் முன்னிலையில் இணைவைப்பவர்களை அழைத்து, \"என்னைத் தவிர நீங்கள் வணங்கிக் கொண்டிருந்த எனது கூட்டாளிகள் எங்கே?\" என்று கேட்பான்.\n\r\n\n\r\nقَالُواْ ءَاذَنَّاكَ\n\r\n\n\r\n(அவர்கள் கூறுவார்கள்: \"உன்னிடம் நாங்கள் அறிவிக்கிறோம்...\") அதாவது, 'நாங்கள் உன்னிடம் கூறுகிறோம்,'\n\r\n\n\r\nمَا مِنَّا مِن شَهِيدٍ\n\r\n\n\r\n(எங்களில் எவரும் அதற்குச் சாட்சியாக இல்லை.) அதாவது, 'உனக்கு எந்தவொரு கூட்டாளியும் இருப்பதாக இன்று எங்களில் ஒருவர்கூட சாட்சி கூறமாட்டோம்.'\n\r\n\n\r\nوَضَلَّ عَنْهُم مَّا كَانُواْ يَدْعُونَ مِن قَبْلُ\n\r\n\n\r\n(இதற்கு முன்னர் (இவ்வுலகில்) அவர்கள் எவற்றை அழைத்துக்கொண்டிருந்தார்களோ, அவை அவர்களை விட்டு மறைந்துவிடும்,) அதாவது, அவை அவர்களை விட்டு நீங்கிவிடும், அவர்களுக்கு எவ்விதப் பயனும் அளிக்காது.\n\r\n\n\r\nوَظَنُّواْ مَا لَهُمْ مِّن مَّحِيصٍ\n\r\n\n\r\n(மேலும், தங்களுக்குத் தப்பிச்செல்ல இடமே இல்லை என்பதை அவர்கள் உணர்ந்து கொள்வார்கள்) அதாவது, அல்லாஹ்வின் தண்டனையிலிருந்து தப்பிக்க அவர்களுக்கு எந்த வழியும் இருக்காது. இது பின்வரும் வசனத்தைப் போன்றது:\n\r\n\n\r\nوَرَأَى الْمُجْرِمُونَ النَّارَ فَظَنُّواْ أَنَّهُمْ مُّوَاقِعُوهَا وَلَمْ يَجِدُواْ عَنْهَا مَصْرِفًا\n\r\n\n\r\n(குற்றவாளிகள் நரக நெருப்பைக் கண்டு, தாங்கள் அதில் விழப்போகிறோம் என்பதை உணர்ந்து கொள்வார்கள்; அதிலிருந்து தப்பிக்க அவர்கள் எந்தவொரு புகலிடத்தையும் காண மாட்டார்கள்.) (18:53)"},"49":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=41&ayah=51\" class=\"link\">41:51</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 41:51 ஐ பார்க்கவும்"},"50":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=41&ayah=51\" class=\"link\">41:51</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 41:51 ஐ பார்க்கவும்"},"51":{"html":"<strong>சிரமத்திற்குப் பிறகு சுகம் வரும்போது மனிதன் மாறும் விதம்</strong><br />\r\n<br />\r\nசெல்வம், உடல் ஆரோக்கியம் போன்ற நன்மைகளைத் தனது இறைவனிடம் கேட்பதில் மனிதன் ஒருபோதும் சோர்வடைவதே இல்லை என்று அல்லாஹ் கூறுகிறான். ஆனால் சோதனைகள், சிரமங்கள் அல்லது வறுமை போன்ற தீங்குகள் அவனைத் தீண்டும்போது <span class=\"quran-arabic-font text-success\">﴾فَيَئُوسٌ</span> <span class=\"quran-arabic-font text-success\">قَنُوطٌ﴿</span> (அவன் பெரும் விரக்தியடைந்து நம்பிக்கையற்றவன் ஆகிவிடுகிறான்). அதாவது, தனக்கு இனி ஒருபோதும் நன்மைகள் ஏற்படாது என்று அவன் எண்ணுகிறான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَلَئِنْ</span> <span class=\"quran-arabic-font text-success\">أَذَقْنَاهُ</span> <span class=\"quran-arabic-font text-success\">رَحْمَةً</span> <span class=\"quran-arabic-font text-success\">مِّنَّا</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">بَعْدِ</span> <span class=\"quran-arabic-font text-success\">ضَرَّآءَ</span> <span class=\"quran-arabic-font text-success\">مَسَّتْهُ</span> <span class=\"quran-arabic-font text-success\">لَيَقُولَنَّ</span> <span class=\"quran-arabic-font text-success\">هَـذَا</span> <span class=\"quran-arabic-font text-success\">لِى﴿</span> (அவனைத் தீண்டிய ஒரு துன்பத்திற்குப் பிறகு, நம்மிடமிருந்து ஒரு அருளை அவன் சுவைக்கும்படி நாம் செய்தால், அவன் நிச்சயமாக, \"இது எனக்குரியது (எனது தகுதியால் கிடைத்தது)...\" என்று கூறுவான்). அதாவது, ஒரு சிரமமான காலத்திற்குப் பிறகு அவனுக்கு ஏதேனும் நன்மையோ அல்லது வாழ்வாதாரமோ கிடைத்தால், அவன் \"இது எனக்குக் கிடைக்க வேண்டியதுதான், என் இறைவனிடம் இதைப் பெற நான் தகுதியானவன்\" என்று கூறுகிறான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَمَآ</span> <span class=\"quran-arabic-font text-success\">أَظُنُّ</span> <span class=\"quran-arabic-font text-success\">السَّاعَةَ</span> <span class=\"quran-arabic-font text-success\">قَائِمَةً﴿</span> (மறுமை நாள் ஏற்படும் என்று நான் நினைக்கவில்லை) என்று அவன் கூறுகிறான். இதன் பொருள், மறுமை வரும் என்று அவன் நம்புவதில்லை. எனவே, அவனுக்கு ஏதேனும் அருட்கொடைகள் வழங்கப்படும்போது, அவன் கவனக்குறைவாகவும், ஆணவமாகவும், நன்றியற்றவனாகவும் மாறுகிறான். அல்லாஹ் கூறுவது போல்: <span class=\"quran-arabic-font text-success\">﴾كَلاَّ</span> <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">الْإِنسَانَ</span> <span class=\"quran-arabic-font text-success\">لَيَطْغَى</span> - <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">رَّءَاهُ</span> <span class=\"quran-arabic-font text-success\">اسْتَغْنَى</span> <span class=\"quran-arabic-font text-success\">﴿</span> (இல்லை! நிச்சயமாக மனிதன் வரம்பு மீறுகிறான். ஏனெனில், அவன் தன்னைத் தன்னிறைவு பெற்றவனாகக் கருதுகிறான்.) (<a href=\"qurandisp.php?sura=96&ayah=6\" class=\"link\">96:6</a>-7)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَلَئِن</span> <span class=\"quran-arabic-font text-success\">رُّجِّعْتُ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">رَبِّى</span> <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">لِى</span> <span class=\"quran-arabic-font text-success\">عِندَهُ</span> <span class=\"quran-arabic-font text-success\">لَلْحُسْنَى﴿</span> (ஒருவேளை நான் என் இறைவனிடம் மீண்டும் கொண்டு செல்லப்பட்டாலும், நிச்சயமாக அவனிடம் எனக்குச் சிறந்ததே இருக்கும்) என்று அவன் கூறுகிறான். அதாவது, 'மறுமை என்று ஒன்று இருந்தால், இவ்வுலகில் என் இறைவன் எனக்குத் தாராளமாகவும் கனிவாகவும் இருந்தது போலவே அங்கேயும் இருப்பான்' என்று அவன் கருதுகிறான். இவ்வாறாக, தனது தீய செயல்களையும் உறுதியான ஈமான் (நம்பிக்கை) இல்லாததையும் பொருட்படுத்தாமல், அல்லாஹ் தனக்கு அருளுவான் என்று அவன் எதிர்பார்க்கிறான்.<br />\r\n<br />\r\nஅல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾فَلَنُنَبِّئَنَّ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُواْ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">عَمِلُواْ</span> <span class=\"quran-arabic-font text-success\">وَلَنُذِيقَنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">عَذَابٍ</span> <span class=\"quran-arabic-font text-success\">غَلِيظٍ﴿</span> (அப்போது, நிராகரித்தவர்கள் செய்தவற்றை அவர்களுக்கு நாம் நிச்சயமாகத் தெரிவிப்போம்; மேலும், அவர்களைக் கடுமையான வேதனையைச் சுவைக்கச் செய்வோம்.) இத்தகைய நடத்தையையும் நம்பிக்கையையும் கொண்டவர்களுக்கு அல்லாஹ் தண்டனையையும் பழிவாங்கலையும் எச்சரிக்கிறான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَإِذَآ</span> <span class=\"quran-arabic-font text-success\">أَنْعَمْنَا</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الْإِنسَانِ</span> <span class=\"quran-arabic-font text-success\">أَعْرَضَ</span> <span class=\"quran-arabic-font text-success\">وَنَأَى</span> <span class=\"quran-arabic-font text-success\">بِجَانِبِهِ﴿</span> (நாம் மனிதனுக்கு அருட்கொடையை வழங்கும்போது, அவன் (நன்றியின்றிப்) புறக்கணித்து, ஆணவத்துடன் விலகிச் செல்கிறான்). அதாவது, அவன் வழிபாடுகளைச் செய்வதிலிருந்து விலகி, அல்லாஹ்வின் கட்டளைகளுக்குக் கீழ்ப்படியப் பெருமை கொள்கிறான். இது இந்த வசனத்தைப் போன்றது: <span class=\"quran-arabic-font text-success\">﴾فَتَوَلَّى</span> <span class=\"quran-arabic-font text-success\">بِرُكْنِهِ﴿</span> (ஆனால், ஃபிர்அவ்ன் தனது படைகளுடன் புறக்கணித்துச் சென்றான்.) (<a href=\"qurandisp.php?sura=51&ayah=39\" class=\"link\">51:39</a>).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَإِذَا</span> <span class=\"quran-arabic-font text-success\">مَسَّهُ</span> <span class=\"quran-arabic-font text-success\">الشَّرُّ﴿</span> (ஆனால், அவனைத் தீமை தீண்டும்போது,) அதாவது சிரமங்கள் ஏற்படும்போது, <span class=\"quran-arabic-font text-success\">﴾فَذُو</span> <span class=\"quran-arabic-font text-success\">دُعَآءٍ</span> <span class=\"quran-arabic-font text-success\">عَرِيضٍ﴿</span> (அவன் நீண்ட பிரார்த்தனைகளைச் செய்கிறான்.) அதாவது, அவன் ஒரே ஒரு விஷயத்திற்காக விரிவாக இறைவனிடம் வேண்டுகிறான். நீண்ட பிரார்த்தனைகள் என்பது சொற்கள் அதிகமாகவும், அதன் கருத்து சுருக்கமாகவும் இருப்பதாகும். இதற்கு நேர்மாற்றமானது சுருக்கமான ஆனால் ஆழமான கருத்துடைய பேச்சாகும்.<br />\r\n<br />\r\nமேலும் அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾وَإِذَا</span> <span class=\"quran-arabic-font text-success\">مَسَّ</span> <span class=\"quran-arabic-font text-success\">الْإِنسَانَ</span> <span class=\"quran-arabic-font text-success\">الضُّرُّ</span> <span class=\"quran-arabic-font text-success\">دَعَانَا</span> <span class=\"quran-arabic-font text-success\">لِجَنبِهِ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">قَاعِدًا</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">قَآئِمًا</span> <span class=\"quran-arabic-font text-success\">فَلَمَّا</span> <span class=\"quran-arabic-font text-success\">كَشَفْنَا</span> <span class=\"quran-arabic-font text-success\">عَنْهُ</span> <span class=\"quran-arabic-font text-success\">ضُرَّهُ</span> <span class=\"quran-arabic-font text-success\">مَرَّ</span> <span class=\"quran-arabic-font text-success\">كَأَن</span> <span class=\"quran-arabic-font text-success\">لَّمْ</span> <span class=\"quran-arabic-font text-success\">يَدْعُنَآ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">ضُرٍّ</span> <span class=\"quran-arabic-font text-success\">مَّسَّهُ﴿</span> (மனிதனைத் துன்பம் தீண்டும்போது, அவன் படுத்த நிலையிலோ, உட்கார்ந்த நிலையிலோ அல்லது நின்ற நிலையிலோ நம்மை அழைக்கிறான். ஆனால், அவனது துன்பத்தை நாம் நீக்கியபோது, தன்னைத் தீண்டிய துன்பத்திற்காக அவன் நம்மை அழைக்கவே இல்லை என்பது போல் கடந்து செல்கிறான்!) (<a href=\"qurandisp.php?sura=10&ayah=12\" class=\"link\">10:12</a>)<br />\r\n<br />","text":"சிரமத்திற்குப் பிறகு சுகம் வரும்போது மனிதன் மாறும் விதம்\n\r\n\n\r\nசெல்வம், உடல் ஆரோக்கியம் போன்ற நன்மைகளைத் தனது இறைவனிடம் கேட்பதில் மனிதன் ஒருபோதும் சோர்வடைவதே இல்லை என்று அல்லாஹ் கூறுகிறான். ஆனால் சோதனைகள், சிரமங்கள் அல்லது வறுமை போன்ற தீங்குகள் அவனைத் தீண்டும்போது ﴾فَيَئُوسٌ قَنُوطٌ﴿ (அவன் பெரும் விரக்தியடைந்து நம்பிக்கையற்றவன் ஆகிவிடுகிறான்). அதாவது, தனக்கு இனி ஒருபோதும் நன்மைகள் ஏற்படாது என்று அவன் எண்ணுகிறான்.\n\r\n\n\r\n﴾وَلَئِنْ أَذَقْنَاهُ رَحْمَةً مِّنَّا مِن بَعْدِ ضَرَّآءَ مَسَّتْهُ لَيَقُولَنَّ هَـذَا لِى﴿ (அவனைத் தீண்டிய ஒரு துன்பத்திற்குப் பிறகு, நம்மிடமிருந்து ஒரு அருளை அவன் சுவைக்கும்படி நாம் செய்தால், அவன் நிச்சயமாக, \"இது எனக்குரியது (எனது தகுதியால் கிடைத்தது)...\" என்று கூறுவான்). அதாவது, ஒரு சிரமமான காலத்திற்குப் பிறகு அவனுக்கு ஏதேனும் நன்மையோ அல்லது வாழ்வாதாரமோ கிடைத்தால், அவன் \"இது எனக்குக் கிடைக்க வேண்டியதுதான், என் இறைவனிடம் இதைப் பெற நான் தகுதியானவன்\" என்று கூறுகிறான்.\n\r\n\n\r\n﴾وَمَآ أَظُنُّ السَّاعَةَ قَائِمَةً﴿ (மறுமை நாள் ஏற்படும் என்று நான் நினைக்கவில்லை) என்று அவன் கூறுகிறான். இதன் பொருள், மறுமை வரும் என்று அவன் நம்புவதில்லை. எனவே, அவனுக்கு ஏதேனும் அருட்கொடைகள் வழங்கப்படும்போது, அவன் கவனக்குறைவாகவும், ஆணவமாகவும், நன்றியற்றவனாகவும் மாறுகிறான். அல்லாஹ் கூறுவது போல்: ﴾كَلاَّ إِنَّ الْإِنسَانَ لَيَطْغَى - أَن رَّءَاهُ اسْتَغْنَى ﴿ (இல்லை! நிச்சயமாக மனிதன் வரம்பு மீறுகிறான். ஏனெனில், அவன் தன்னைத் தன்னிறைவு பெற்றவனாகக் கருதுகிறான்.) (96:6-7)\n\r\n\n\r\n﴾وَلَئِن رُّجِّعْتُ إِلَى رَبِّى إِنَّ لِى عِندَهُ لَلْحُسْنَى﴿ (ஒருவேளை நான் என் இறைவனிடம் மீண்டும் கொண்டு செல்லப்பட்டாலும், நிச்சயமாக அவனிடம் எனக்குச் சிறந்ததே இருக்கும்) என்று அவன் கூறுகிறான். அதாவது, 'மறுமை என்று ஒன்று இருந்தால், இவ்வுலகில் என் இறைவன் எனக்குத் தாராளமாகவும் கனிவாகவும் இருந்தது போலவே அங்கேயும் இருப்பான்' என்று அவன் கருதுகிறான். இவ்வாறாக, தனது தீய செயல்களையும் உறுதியான ஈமான் (நம்பிக்கை) இல்லாததையும் பொருட்படுத்தாமல், அல்லாஹ் தனக்கு அருளுவான் என்று அவன் எதிர்பார்க்கிறான்.\n\r\n\n\r\nஅல்லாஹ் கூறுகிறான்: ﴾فَلَنُنَبِّئَنَّ الَّذِينَ كَفَرُواْ بِمَا عَمِلُواْ وَلَنُذِيقَنَّهُمْ مِّنْ عَذَابٍ غَلِيظٍ﴿ (அப்போது, நிராகரித்தவர்கள் செய்தவற்றை அவர்களுக்கு நாம் நிச்சயமாகத் தெரிவிப்போம்; மேலும், அவர்களைக் கடுமையான வேதனையைச் சுவைக்கச் செய்வோம்.) இத்தகைய நடத்தையையும் நம்பிக்கையையும் கொண்டவர்களுக்கு அல்லாஹ் தண்டனையையும் பழிவாங்கலையும் எச்சரிக்கிறான்.\n\r\n\n\r\n﴾وَإِذَآ أَنْعَمْنَا عَلَى الْإِنسَانِ أَعْرَضَ وَنَأَى بِجَانِبِهِ﴿ (நாம் மனிதனுக்கு அருட்கொடையை வழங்கும்போது, அவன் (நன்றியின்றிப்) புறக்கணித்து, ஆணவத்துடன் விலகிச் செல்கிறான்). அதாவது, அவன் வழிபாடுகளைச் செய்வதிலிருந்து விலகி, அல்லாஹ்வின் கட்டளைகளுக்குக் கீழ்ப்படியப் பெருமை கொள்கிறான். இது இந்த வசனத்தைப் போன்றது: ﴾فَتَوَلَّى بِرُكْنِهِ﴿ (ஆனால், ஃபிர்அவ்ன் தனது படைகளுடன் புறக்கணித்துச் சென்றான்.) (51:39).\n\r\n\n\r\n﴾وَإِذَا مَسَّهُ الشَّرُّ﴿ (ஆனால், அவனைத் தீமை தீண்டும்போது,) அதாவது சிரமங்கள் ஏற்படும்போது, ﴾فَذُو دُعَآءٍ عَرِيضٍ﴿ (அவன் நீண்ட பிரார்த்தனைகளைச் செய்கிறான்.) அதாவது, அவன் ஒரே ஒரு விஷயத்திற்காக விரிவாக இறைவனிடம் வேண்டுகிறான். நீண்ட பிரார்த்தனைகள் என்பது சொற்கள் அதிகமாகவும், அதன் கருத்து சுருக்கமாகவும் இருப்பதாகும். இதற்கு நேர்மாற்றமானது சுருக்கமான ஆனால் ஆழமான கருத்துடைய பேச்சாகும்.\n\r\n\n\r\nமேலும் அல்லாஹ் கூறுகிறான்: ﴾وَإِذَا مَسَّ الْإِنسَانَ الضُّرُّ دَعَانَا لِجَنبِهِ أَوْ قَاعِدًا أَوْ قَآئِمًا فَلَمَّا كَشَفْنَا عَنْهُ ضُرَّهُ مَرَّ كَأَن لَّمْ يَدْعُنَآ إِلَى ضُرٍّ مَّسَّهُ﴿ (மனிதனைத் துன்பம் தீண்டும்போது, அவன் படுத்த நிலையிலோ, உட்கார்ந்த நிலையிலோ அல்லது நின்ற நிலையிலோ நம்மை அழைக்கிறான். ஆனால், அவனது துன்பத்தை நாம் நீக்கியபோது, தன்னைத் தீண்டிய துன்பத்திற்காக அவன் நம்மை அழைக்கவே இல்லை என்பது போல் கடந்து செல்கிறான்!) (10:12)"},"52":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=41&ayah=54\" class=\"link\">41:54</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 41:54 ஐ பார்க்கவும்"},"53":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=41&ayah=54\" class=\"link\">41:54</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 41:54 ஐ பார்க்கவும்"},"54":{"html":"<strong>குர்ஆனும் அதன் உண்மைக்கான அத்தாட்சிகளும்; அல்லாஹ் கூறுகிறான்:</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قُلْ</span><br />\r\n(கூறுவீராக) -- \"முஹம்மதே (ஸல்)! குர்ஆனை நிராகரிக்கின்ற இந்த இணைவைப்பாளர்களிடம் கூறுவீராக\" --<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَرَءَيْتُمْ</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">كَانَ</span><br />\r\n(நீங்கள் கூறுங்கள், இது இருந்தால்) -- இந்தக் குர்ஆன் --<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">عِندِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">كَفَرْتُمْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span><br />\r\n(அல்லாஹ்விடமிருந்து வந்திருந்து, பின்னர் நீங்கள் அதனை நிராகரித்தால்) இதன் பொருள், \"தனது தூதருக்கு இதனை அருளியவனுக்கு முன்னால் உங்கள் நிலை என்னவாகும் என்று நீங்கள் கருதுகிறீர்கள்?\" அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">أَضَلُّ</span> <span class=\"quran-arabic-font text-success\">مِمَّنْ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">شِقَاقٍ</span> <span class=\"quran-arabic-font text-success\">بَعِيدٍ</span><br />\r\n(வெகுதூரம் விலகிச் சென்ற பிடிவாதத்தில் இருப்பவரை விட அதிக வழிகெட்டவர் யார்?) இதன் பொருள், அவர் குஃப்ரிலும் (நிராகரிப்பு), பிடிவாதத்திலும், சத்தியத்திற்கு எதிரான நிலையிலும் இருக்கிறார்; மேலும் நேர்வழியிலிருந்து வெகுதூரம் விலகிச் செல்லும் ஒரு பாதையைப் பின்பற்றுகிறார். பிறகு அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">سَنُرِيهِمْ</span> <span class=\"quran-arabic-font text-success\">آيَاتِنَا</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْآفَاقِ</span> <span class=\"quran-arabic-font text-success\">وَفِي</span> <span class=\"quran-arabic-font text-success\">أَنفُسِهِمْ</span><br />\r\n(அண்டவெளிகளிலும், அவர்களுக்குள்ளேயும் நம்முடைய அத்தாட்சிகளை விரைவில் நாம் அவர்களுக்குக் காட்டுவோம்.) இதன் பொருள், 'குர்ஆன் உண்மையானது என்றும், அது நிச்சயமாக அல்லாஹ்வின் தூதர் (ஸல்) அவர்களுக்கு அல்லாஹ்விடமிருந்துதான் வஹீ (இறைச்செய்தி)யாக அருளப்பட்டது என்றும் நமது ஆதாரங்களையும் அத்தாட்சிகளையும் புறவயமான சான்றுகள் மூலம் அவர்களுக்குக் காட்டுவோம்,'<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْآفَاقِ</span><br />\r\n(அண்டவெளிகளில்),\" அதாவது வெற்றிகள் மற்றும் பல்வேறு பகுதிகளிலும் மற்ற அனைத்து மதங்களை விடவும் இஸ்லாம் மேலோங்கி நின்ற நிகழ்வுகள் போன்றவையாகும். முஜாஹித், அல்-ஹஸன் மற்றும் அஸ்-ஸுத்தி (ரஹ்) ஆகியோர் கூறினார்கள்: \"அவர்களுக்குள்ளேயான அத்தாட்சிகள் என்பது பத்ருப் போர், மக்கா வெற்றி மற்றும் அவர்களுக்கு ஏற்பட்ட ஏனைய நிகழ்வுகளைக் குறிக்கும்; அவற்றில் அல்லாஹ் முஹம்மது (ஸல்) அவர்களுக்கும் அவரது ஸஹாபாக்களுக்கும் (ரழி) வெற்றியை வழங்கினான், மேலும் அசத்தியத்திற்கும் அதனைப் பின்பற்றுபவர்களுக்கும் இழிவான தோல்வியைத் தந்தான்.\" இங்கு மனிதனையும் அவனது உடல் அமைப்பையும் கூட இது குறிக்கலாம். உடற்கூறியல் அறிவியலில் விவரிக்கப்பட்டுள்ளபடி, அது படைப்பாளனின் (அவன் பாக்கியம் மிக்கவன், உயர்ந்தவன்) ஞானத்தைச் சுட்டிக்காட்டுகிறது. மேலும் மக்களிடம் உள்ள நன்மை, தீமை போன்ற பல்வேறு நாட்டங்கள் மற்றும் ஒன்றுக்கொன்று முரணான இயல்புகள், மற்றும் மனிதன் உட்படுத்தப்படும் (இறை) விதிகள் ஆகியவற்றையும் இது குறிக்கும்; இவற்றை மாற்றவோ அல்லது கட்டுப்படுத்தவோ மனிதனுக்கு எந்த அதிகாரமும் இல்லை.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">يَتَبَيَّنَ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">أَنَّهُ</span> <span class=\"quran-arabic-font text-success\">الْحَقُّ</span> <span class=\"quran-arabic-font text-success\">أَوَلَمْ</span> <span class=\"quran-arabic-font text-success\">يَكْفِ</span> <span class=\"quran-arabic-font text-success\">بِرَبِّكَ</span> <span class=\"quran-arabic-font text-success\">أَنَّهُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">كُلِّ</span> <span class=\"quran-arabic-font text-success\">شَيْءٍ</span> <span class=\"quran-arabic-font text-success\">شَهِيدٌ</span><br />\r\n(இது (குர்ஆன்) தான் சத்தியம் என்பது அவர்களுக்குத் தெளிவாகும் வரை (நம் அத்தாட்சிகளைக் காட்டுவோம்). உம்முடைய இறைவன் அனைத்துப் பொருட்கள் மீதும் சாட்சியாக இருப்பது போதுமானதாக இல்லையா?) இதன் பொருள், தனது அடியார்களின் சொல் மற்றும் செயல்களுக்கு அல்லாஹ் சாட்சியாக இருப்பதே போதுமானது என்பதாகும்; மேலும் முஹம்மது (ஸல்) அவர்கள் கூறுவதில் உண்மையானவர் என்பதற்கு அவன் சாட்சி கூறுகிறான். அல்லாஹ் கூறுவது போல:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَّـكِنِ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">يَشْهَدُ</span> <span class=\"quran-arabic-font text-success\">بِمَآ</span> <span class=\"quran-arabic-font text-success\">أَنزَلَ</span> <span class=\"quran-arabic-font text-success\">إِلَيْكَ</span> <span class=\"quran-arabic-font text-success\">أَنزَلَهُ</span> <span class=\"quran-arabic-font text-success\">بِعِلْمِهِ</span><br />\r\n(எனினும் அல்லாஹ் உமக்கு எதனை இறக்கிவைத்தாரோ, அதனைத் தனது ஞானத்தைக் கொண்டே இறக்கினான் என்பதற்கு அவனே சாட்சி கூறுகிறான்) (<a href=\"qurandisp.php?sura=4&ayah=166\" class=\"link\">4:166</a>).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَلاَ</span> <span class=\"quran-arabic-font text-success\">إِنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">مِرْيَةٍ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">لِّقَآءِ</span> <span class=\"quran-arabic-font text-success\">رَبِّهِمْ</span><br />\r\n(அறிந்து கொள்க! நிச்சயமாக அவர்கள் தங்கள் இறைவனைச் சந்திப்பது குறித்து சந்தேகத்தில் இருக்கின்றனர்.) இதன் பொருள், அந்த (மறுமை) நாள் வரும் என்பதில் அவர்கள் சந்தேகப்படுகிறார்கள்; அவர்கள் அதைப் பற்றிச் சிந்திப்பதோ, அதற்காகப் பாடுபடுவதோ அல்லது அதைக் கவனத்தில் கொள்வதோ இல்லை. மாறாக, அவர்கள் அதனை முக்கியத்துவமற்ற ஒன்றாகக் கருதி அலட்சியம் செய்கிறார்கள். ஆனால் அது சந்தேகமின்றி நிகழும். பிறகு தான் அனைத்தின் மீதும் பேராற்றல் கொண்டவன் என்றும், அனைத்தையும் சூழ்ந்திருப்பவன் என்றும், அந்த நேரத்தைக் கொண்டு வருவது தனக்கு மிக எளிதானது என்றும் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَلاَ</span> <span class=\"quran-arabic-font text-success\">إِنَّهُ</span> <span class=\"quran-arabic-font text-success\">بِكُلِّ</span> <span class=\"quran-arabic-font text-success\">شَيْءٍ</span> <span class=\"quran-arabic-font text-success\">مُّحِيطٌ</span><br />\r\n(நிச்சயமாக அவன் அனைத்துப் பொருட்களையும் சூழ்ந்திருப்பவன்!) இதன் பொருள், படைப்புகள் அனைத்தும் அவனது கட்டுப்பாடு, அதிகாரம் மற்றும் அறிவுக்கு உட்பட்டவை; அவன் தனது வல்லமையால் அனைத்தையும் நிர்வகிக்கிறான். எனவே அவன் நாடியது நடக்கும், அவன் நாடாதது நடக்காது. அவனைத் தவிர வணக்கத்திற்குரிய இறைவன் வேறு யாருமில்லை. இத்துடன் ஸூரா ஃபுஸ்ஸிலத்தின் தஃப்ஸீர் நிறைவுற்றது. புகழும் அருளும் அல்லாஹ்வுக்கே உரியது.<br />\r\n<br />","text":"குர்ஆனும் அதன் உண்மைக்கான அத்தாட்சிகளும்; அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nقُلْ\n\r\n(கூறுவீராக) -- \"முஹம்மதே (ஸல்)! குர்ஆனை நிராகரிக்கின்ற இந்த இணைவைப்பாளர்களிடம் கூறுவீராக\" --\n\r\n\n\r\nأَرَءَيْتُمْ إِن كَانَ\n\r\n(நீங்கள் கூறுங்கள், இது இருந்தால்) -- இந்தக் குர்ஆன் --\n\r\n\n\r\nمِنْ عِندِ اللَّهِ ثُمَّ كَفَرْتُمْ بِهِ\n\r\n(அல்லாஹ்விடமிருந்து வந்திருந்து, பின்னர் நீங்கள் அதனை நிராகரித்தால்) இதன் பொருள், \"தனது தூதருக்கு இதனை அருளியவனுக்கு முன்னால் உங்கள் நிலை என்னவாகும் என்று நீங்கள் கருதுகிறீர்கள்?\" அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nمَنْ أَضَلُّ مِمَّنْ هُوَ فِي شِقَاقٍ بَعِيدٍ\n\r\n(வெகுதூரம் விலகிச் சென்ற பிடிவாதத்தில் இருப்பவரை விட அதிக வழிகெட்டவர் யார்?) இதன் பொருள், அவர் குஃப்ரிலும் (நிராகரிப்பு), பிடிவாதத்திலும், சத்தியத்திற்கு எதிரான நிலையிலும் இருக்கிறார்; மேலும் நேர்வழியிலிருந்து வெகுதூரம் விலகிச் செல்லும் ஒரு பாதையைப் பின்பற்றுகிறார். பிறகு அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nسَنُرِيهِمْ آيَاتِنَا فِي الْآفَاقِ وَفِي أَنفُسِهِمْ\n\r\n(அண்டவெளிகளிலும், அவர்களுக்குள்ளேயும் நம்முடைய அத்தாட்சிகளை விரைவில் நாம் அவர்களுக்குக் காட்டுவோம்.) இதன் பொருள், 'குர்ஆன் உண்மையானது என்றும், அது நிச்சயமாக அல்லாஹ்வின் தூதர் (ஸல்) அவர்களுக்கு அல்லாஹ்விடமிருந்துதான் வஹீ (இறைச்செய்தி)யாக அருளப்பட்டது என்றும் நமது ஆதாரங்களையும் அத்தாட்சிகளையும் புறவயமான சான்றுகள் மூலம் அவர்களுக்குக் காட்டுவோம்,'\n\r\n\n\r\nفِي الْآفَاقِ\n\r\n(அண்டவெளிகளில்),\" அதாவது வெற்றிகள் மற்றும் பல்வேறு பகுதிகளிலும் மற்ற அனைத்து மதங்களை விடவும் இஸ்லாம் மேலோங்கி நின்ற நிகழ்வுகள் போன்றவையாகும். முஜாஹித், அல்-ஹஸன் மற்றும் அஸ்-ஸுத்தி (ரஹ்) ஆகியோர் கூறினார்கள்: \"அவர்களுக்குள்ளேயான அத்தாட்சிகள் என்பது பத்ருப் போர், மக்கா வெற்றி மற்றும் அவர்களுக்கு ஏற்பட்ட ஏனைய நிகழ்வுகளைக் குறிக்கும்; அவற்றில் அல்லாஹ் முஹம்மது (ஸல்) அவர்களுக்கும் அவரது ஸஹாபாக்களுக்கும் (ரழி) வெற்றியை வழங்கினான், மேலும் அசத்தியத்திற்கும் அதனைப் பின்பற்றுபவர்களுக்கும் இழிவான தோல்வியைத் தந்தான்.\" இங்கு மனிதனையும் அவனது உடல் அமைப்பையும் கூட இது குறிக்கலாம். உடற்கூறியல் அறிவியலில் விவரிக்கப்பட்டுள்ளபடி, அது படைப்பாளனின் (அவன் பாக்கியம் மிக்கவன், உயர்ந்தவன்) ஞானத்தைச் சுட்டிக்காட்டுகிறது. மேலும் மக்களிடம் உள்ள நன்மை, தீமை போன்ற பல்வேறு நாட்டங்கள் மற்றும் ஒன்றுக்கொன்று முரணான இயல்புகள், மற்றும் மனிதன் உட்படுத்தப்படும் (இறை) விதிகள் ஆகியவற்றையும் இது குறிக்கும்; இவற்றை மாற்றவோ அல்லது கட்டுப்படுத்தவோ மனிதனுக்கு எந்த அதிகாரமும் இல்லை.\n\r\n\n\r\nحَتَّى يَتَبَيَّنَ لَهُمْ أَنَّهُ الْحَقُّ أَوَلَمْ يَكْفِ بِرَبِّكَ أَنَّهُ عَلَى كُلِّ شَيْءٍ شَهِيدٌ\n\r\n(இது (குர்ஆன்) தான் சத்தியம் என்பது அவர்களுக்குத் தெளிவாகும் வரை (நம் அத்தாட்சிகளைக் காட்டுவோம்). உம்முடைய இறைவன் அனைத்துப் பொருட்கள் மீதும் சாட்சியாக இருப்பது போதுமானதாக இல்லையா?) இதன் பொருள், தனது அடியார்களின் சொல் மற்றும் செயல்களுக்கு அல்லாஹ் சாட்சியாக இருப்பதே போதுமானது என்பதாகும்; மேலும் முஹம்மது (ஸல்) அவர்கள் கூறுவதில் உண்மையானவர் என்பதற்கு அவன் சாட்சி கூறுகிறான். அல்லாஹ் கூறுவது போல:\n\r\n\n\r\nلَّـكِنِ اللَّهُ يَشْهَدُ بِمَآ أَنزَلَ إِلَيْكَ أَنزَلَهُ بِعِلْمِهِ\n\r\n(எனினும் அல்லாஹ் உமக்கு எதனை இறக்கிவைத்தாரோ, அதனைத் தனது ஞானத்தைக் கொண்டே இறக்கினான் என்பதற்கு அவனே சாட்சி கூறுகிறான்) (4:166).\n\r\n\n\r\nأَلاَ إِنَّهُمْ فِي مِرْيَةٍ مِّن لِّقَآءِ رَبِّهِمْ\n\r\n(அறிந்து கொள்க! நிச்சயமாக அவர்கள் தங்கள் இறைவனைச் சந்திப்பது குறித்து சந்தேகத்தில் இருக்கின்றனர்.) இதன் பொருள், அந்த (மறுமை) நாள் வரும் என்பதில் அவர்கள் சந்தேகப்படுகிறார்கள்; அவர்கள் அதைப் பற்றிச் சிந்திப்பதோ, அதற்காகப் பாடுபடுவதோ அல்லது அதைக் கவனத்தில் கொள்வதோ இல்லை. மாறாக, அவர்கள் அதனை முக்கியத்துவமற்ற ஒன்றாகக் கருதி அலட்சியம் செய்கிறார்கள். ஆனால் அது சந்தேகமின்றி நிகழும். பிறகு தான் அனைத்தின் மீதும் பேராற்றல் கொண்டவன் என்றும், அனைத்தையும் சூழ்ந்திருப்பவன் என்றும், அந்த நேரத்தைக் கொண்டு வருவது தனக்கு மிக எளிதானது என்றும் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nأَلاَ إِنَّهُ بِكُلِّ شَيْءٍ مُّحِيطٌ\n\r\n(நிச்சயமாக அவன் அனைத்துப் பொருட்களையும் சூழ்ந்திருப்பவன்!) இதன் பொருள், படைப்புகள் அனைத்தும் அவனது கட்டுப்பாடு, அதிகாரம் மற்றும் அறிவுக்கு உட்பட்டவை; அவன் தனது வல்லமையால் அனைத்தையும் நிர்வகிக்கிறான். எனவே அவன் நாடியது நடக்கும், அவன் நாடாதது நடக்காது. அவனைத் தவிர வணக்கத்திற்குரிய இறைவன் வேறு யாருமில்லை. இத்துடன் ஸூரா ஃபுஸ்ஸிலத்தின் தஃப்ஸீர் நிறைவுற்றது. புகழும் அருளும் அல்லாஹ்வுக்கே உரியது."}}};})(self);
